def _sci_super(x):
    """1.55125e-10 → '1.55125 × 10⁻¹⁰' (notación de artículo)."""
    m, e = f"{float(x):.6e}".split("e")
    m = m.rstrip("0").rstrip(".")
    sup = str(int(e)).translate(str.maketrans("-0123456789", "⁻⁰¹²³⁴⁵⁶⁷⁸⁹"))
    return f"{m} × 10{sup}"


# ══════════════════════════════════════════════════════════════════════════
# §Ola8 — Compendio TEÓRICO en PDF ("Theory & methods")
# ──────────────────────────────────────────────────────────────────────────
# Pipeline: contenido HTML (QTextDocument) + diagramas/ecuaciones matplotlib
# embebidos como imágenes (addResource) → QPdfWriter. SIN dependencias nuevas.
# Cada sección es una función `(_n, accent, ink) -> (html, {clave: QImage})` con
# claves de recurso namespaceadas por número de sección (s{n}_…). Para agregar
# una sección: escribir la función y añadirla a _THEORY_SECTIONS.
# El texto/matemática los VERIFICA Guillermo (dominio); Claude arma estructura y
# geometría. Look aprobado por Guillermo el 2026-07-22 (prototipo §1).
_THEORY_INK = "#1a2a3a"


def _pdf_fig_to_qimage(fig, dpi=200):
    """Figura matplotlib → QImage (PNG en memoria, fondo transparente)."""
    import io
    import matplotlib.pyplot as plt
    from PyQt6.QtGui import QImage
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=dpi, bbox_inches="tight", transparent=True)
    plt.close(fig)
    return QImage.fromData(buf.getvalue(), "PNG")


def _pdf_math_img(expr, fontsize=17, color=_THEORY_INK):
    """Ecuación (mathtext) → QImage ajustada. mathtext NO soporta matrices/arrays
    (para eso hay dibujos ad-hoc); sí fracciones, raíces, griegas, sub/superíndices."""
    import matplotlib.pyplot as plt
    fig = plt.figure(figsize=(0.1, 0.1))
    fig.text(0.5, 0.5, expr, fontsize=fontsize, color=color, ha="center", va="center")
    return _pdf_fig_to_qimage(fig)


def _theory_sec_ellipses(n, accent, ink):
    """§ Elipses de error y el coeficiente de correlación ρ (prototipo aprobado)."""
    import numpy as np
    import matplotlib.pyplot as plt
    from matplotlib.patches import Ellipse

    def cov_matrix_img():
        fig, ax = plt.subplots(figsize=(3.4, 1.3))
        ax.set_xlim(0, 10); ax.set_ylim(0, 4); ax.axis("off")
        ax.text(0.2, 2, r"$\Sigma \;=\;$", fontsize=17, va="center", color=ink)
        for x0 in (3.1, 9.4):
            d = 0.25 if x0 < 5 else -0.25
            ax.plot([x0, x0], [0.4, 3.6], color=ink, lw=1.4)
            ax.plot([x0, x0 + d], [0.4, 0.4], color=ink, lw=1.4)
            ax.plot([x0, x0 + d], [3.6, 3.6], color=ink, lw=1.4)
        ax.text(4.4, 2.8, r"$\sigma_x^{2}$", fontsize=15, ha="center", va="center", color=ink)
        ax.text(7.6, 2.8, r"$\rho\,\sigma_x\sigma_y$", fontsize=15, ha="center", va="center", color=ink)
        ax.text(4.4, 1.1, r"$\rho\,\sigma_x\sigma_y$", fontsize=15, ha="center", va="center", color=ink)
        ax.text(7.6, 1.1, r"$\sigma_y^{2}$", fontsize=15, ha="center", va="center", color=ink)
        return _pdf_fig_to_qimage(fig)

    def _ellipse(ax, sx, sy, rho, k=2.0):
        cov = np.array([[sx**2, rho*sx*sy], [rho*sx*sy, sy**2]])
        vals, vecs = np.linalg.eigh(cov)
        order = vals.argsort()[::-1]
        vals, vecs = vals[order], vecs[:, order]
        angle = np.degrees(np.arctan2(vecs[1, 0], vecs[0, 0]))
        w, h = 2*k*np.sqrt(vals[0]), 2*k*np.sqrt(vals[1])
        ax.add_patch(Ellipse((0, 0), w, h, angle=angle, facecolor=accent,
                             alpha=0.18, edgecolor=accent, lw=1.6))
        ax.plot([-k*sx, k*sx, k*sx, -k*sx, -k*sx],
                [-k*sy, -k*sy, k*sy, k*sy, -k*sy], ls="--", lw=0.8, color="#888")
        ax.axhline(0, color="#bbb", lw=0.6); ax.axvline(0, color="#bbb", lw=0.6)
        lim = k*max(sx, sy)*1.25
        ax.set_xlim(-lim, lim); ax.set_ylim(-lim, lim)
        ax.set_aspect("equal"); ax.tick_params(labelsize=7)
        ax.set_xlabel("x  (e.g. ²⁰⁷Pb/²³⁵U)", fontsize=8)
        ax.set_ylabel("y  (e.g. ²⁰⁶Pb/²³⁸U)", fontsize=8)

    def ellipse_diagram():
        fig, axs = plt.subplots(1, 2, figsize=(6.6, 3.2))
        _ellipse(axs[0], 1.0, 0.6, 0.0)
        axs[0].set_title(r"$\rho = 0$  (axis-aligned)", fontsize=9, color=ink)
        _ellipse(axs[1], 1.0, 0.6, 0.85)
        axs[1].set_title(r"$\rho = 0.85$  (tilted, narrower)", fontsize=9, color=ink)
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {f"s{n}_cov": cov_matrix_img(), f"s{n}_ell": ellipse_diagram(),
           f"s{n}_tilt": _pdf_math_img(
               r"$\tan 2\theta \;=\; \dfrac{2\,\rho\,\sigma_x\sigma_y}"
               r"{\sigma_x^{2}-\sigma_y^{2}}$")}
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Uncertainty ellipses and
the correlation coefficient ρ</h2>
<p style="font-size:12.5pt; line-height:150%;">Every U–Pb analysis carries two
<i>correlated</i> ratio measurements — for example ²⁰⁷Pb/²³⁵U and ²⁰⁶Pb/²³⁸U on a
Wetherill concordia diagram. Their joint uncertainty is fully described by a
2&times;2 <b>covariance matrix</b>, built from the two 1σ uncertainties
σ<sub>x</sub>, σ<sub>y</sub> and the <b>error correlation</b> ρ&nbsp;∈&nbsp;[−1,&nbsp;+1]:</p>
<p align="center"><img src="s{n}_cov" width="230"/></p>
<p style="font-size:12.5pt; line-height:150%;">The <b>uncertainty ellipse</b> (often
called the <i>error ellipse</i>) is the set of
points at a fixed statistical distance from the centre. Its size, shape and
orientation come from the eigen-decomposition of Σ: the eigenvalues give the
squared semi-axis lengths (a <i>k</i>σ ellipse has semi-axes <i>k</i>√λ<sub>1</sub>
and <i>k</i>√λ<sub>2</sub>) and the eigenvectors give the orientation.</p>
<p style="font-size:12.5pt; line-height:150%;">When ρ&nbsp;=&nbsp;0 the ellipse axes
align with x and y, and the semi-axes are simply <i>k</i>σ<sub>x</sub> and
<i>k</i>σ<sub>y</sub> — the ellipse is inscribed in the ±<i>k</i>σ box. As ρ moves
away from zero the ellipse <b>tilts</b>; the tilt angle θ satisfies</p>
<p align="center"><img src="s{n}_tilt" width="200"/></p>
<p style="font-size:12.5pt; line-height:150%;">Positive ρ tilts the ellipse toward the
+45° diagonal and makes it narrower; as ρ&nbsp;→&nbsp;±1 the ellipse collapses toward
a straight line, because the two ratios become perfectly correlated.</p>
<p align="center"><img src="s{n}_ell" width="440"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> The same
σ<sub>x</sub>, σ<sub>y</sub> with ρ&nbsp;=&nbsp;0 (left) and ρ&nbsp;=&nbsp;0.85
(right). Both ellipses are inscribed in the identical ±2σ box (dashed); ρ only
rotates and narrows the ellipse.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>Where ZirClock gets ρ.</b> It is read
from the <i>Rho</i> column of Table 1 — the value reported by the data-reduction
software (Iolite, Glitter and the like), obtained from the covariance of the two ratios
during the ablation. That is the preferred source. If the column is empty, ZirClock
reconstructs ρ from the three ages and their ±2σ through the identity
r<sub>7/6</sub>&nbsp;=&nbsp;r<sub>7/35</sub>&nbsp;/&nbsp;(137.818&nbsp;&middot;&nbsp;r<sub>6/38</sub>),
as IsoplotR does when no correlation is supplied. That reconstruction is an
<i>inference</i>, not a measurement: when the three uncertainties are not mutually
consistent — commonly the ²⁰⁷Pb/²⁰⁶Pb age is quoted more precisely than the identity
allows — it tends to the extreme and is capped at |ρ|&nbsp;=&nbsp;0.9999. Table 2
labels each value with its origin (<i>From Table 1</i> / <i>Derived from age
uncertainties</i>), and the status bar reports how many analyses needed the fallback.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>What ρ affects.</b> The shape and tilt
of every 2σ uncertainty ellipse, the concordia-age calculation and the concordance test, and
the weights of the York (2004) discordia regression — so supplying the measured value
is worth the trouble whenever the laboratory reports it.</p>
"""
    return html, res


def _theory_sec_concordia(n, accent, ink):
    """§ La curva de concordia y la edad de concordia (Ludwig 1998)."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt
    from matplotlib.patches import Ellipse

    def concordia_diagram():
        fig, ax = plt.subplots(figsize=(5.4, 4.0))
        ages = np.linspace(250e6, 1700e6, 400)
        X = np.exp(LAMBDA_U235 * ages) - 1.0
        Y = np.exp(LAMBDA_U238 * ages) - 1.0
        ax.plot(X, Y, color=ink, lw=1.8, zorder=2)
        for t_ma in (500, 1000, 1500):
            ty = t_ma * 1e6
            xx = math.exp(LAMBDA_U235 * ty) - 1.0
            yy = math.exp(LAMBDA_U238 * ty) - 1.0
            ax.plot(xx, yy, "o", ms=5, color=ink, zorder=3)
            ax.annotate(f"{t_ma} Ma", (xx, yy), textcoords="offset points",
                        xytext=(-6, 8), fontsize=8, ha="right", color=ink)
        # análisis CONCORDANTE (sobre la curva, con elipse) a ~1000 Ma
        ty = 1000e6
        cx = math.exp(LAMBDA_U235 * ty) - 1.0
        cy = math.exp(LAMBDA_U238 * ty) - 1.0
        ax.add_patch(Ellipse((cx, cy), 0.16, 0.018, angle=6, facecolor=accent,
                             alpha=0.25, edgecolor=accent, lw=1.4, zorder=4))
        ax.annotate("concordant", (cx, cy), textcoords="offset points",
                    xytext=(12, -14), fontsize=8, color=accent)
        # análisis DISCORDANTE (bajo la curva → pérdida de Pb) con flecha
        dx, dy = cx * 0.72, cy * 0.60
        ax.add_patch(Ellipse((dx, dy), 0.16, 0.018, angle=8, facecolor="#c0392b",
                             alpha=0.22, edgecolor="#c0392b", lw=1.4, zorder=4))
        ax.annotate("discordant\n(Pb loss)", (dx, dy), textcoords="offset points",
                    xytext=(10, -2), fontsize=8, color="#c0392b")
        ax.annotate("", xy=(dx, dy), xytext=(cx, cy),
                    arrowprops=dict(arrowstyle="->", color="#c0392b", lw=1.0,
                                    ls="--"), zorder=3)
        ax.set_xlabel("²⁰⁷Pb/²³⁵U", fontsize=9)
        ax.set_ylabel("²⁰⁶Pb/²³⁸U", fontsize=9)
        ax.tick_params(labelsize=8)
        ax.set_xlim(0, X.max() * 1.05); ax.set_ylim(0, Y.max() * 1.08)
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_par": _pdf_math_img(
            r"$X(t) = e^{\lambda_{235}\,t} - 1, \qquad "
            r"Y(t) = e^{\lambda_{238}\,t} - 1$"),
        f"s{n}_S": _pdf_math_img(
            r"$S(t) = \dfrac{1}{1-\rho^{2}}\left[\dfrac{\Delta x^{2}}{\sigma_x^{2}}"
            r" + \dfrac{\Delta y^{2}}{\sigma_y^{2}}"
            r" - \dfrac{2\rho\,\Delta x\,\Delta y}{\sigma_x\sigma_y}\right]$",
            fontsize=16),
        f"s{n}_conc": concordia_diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;The concordia curve and
the concordia age</h2>
<p style="font-size:12.5pt; line-height:150%;">On a <b>Wetherill</b> diagram the two
U–Pb chronometers are plotted against each other: ²⁰⁷Pb/²³⁵U on the x-axis and
²⁰⁶Pb/²³⁸U on the y-axis. For a system that has remained closed since an age
<i>t</i>, both ratios grow with time according to the decay law, tracing the
<b>concordia curve</b> (t in years; λ from Jaffey et al. 1971):</p>
<p align="center"><img src="s{n}_par" width="300"/></p>
<p style="font-size:12.5pt; line-height:150%;">An analysis that has stayed a closed
system plots <b>on</b> the curve — it is <i>concordant</i>. Later Pb loss (or U gain)
pulls it <b>off</b> the curve, toward the origin, making it <i>discordant</i>
(&sect;{n + 1}).</p>
<p align="center"><img src="s{n}_conc" width="360"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> Wetherill
concordia with age ticks. A concordant analysis (blue) sits on the curve with its 2σ
ellipse; Pb loss displaces an analysis below the curve (red).</p>
<p style="font-size:12.5pt; line-height:150%;">When several concordant analyses share
one age, their best common age — the <b>concordia age</b> (Ludwig 1998) — is the
value of <i>t</i> that minimizes the squared <b>Mahalanobis distance</b> S(t) from
the mean measured point (x, y) to the concordia point (X(t), Y(t)), with
Δx&nbsp;=&nbsp;x&nbsp;−&nbsp;X(t), Δy&nbsp;=&nbsp;y&nbsp;−&nbsp;Y(t), weighted by the
covariance (σ<sub>x</sub>, σ<sub>y</sub>, ρ; &sect;{n - 1}):</p>
<p align="center"><img src="s{n}_S" width="360"/></p>
<p style="font-size:12.5pt; line-height:150%;">ZirClock solves dS/dt&nbsp;=&nbsp;0 by
Newton–Raphson with analytic derivatives. At the minimum, S(t*) equals the
<b>MSWD</b> of the concordia age (one degree of freedom), and its uncertainty comes
from the curvature, σ²(t)&nbsp;=&nbsp;2&nbsp;/&nbsp;(d²S/dt²). The same information can
be shown on a <b>Tera–Wasserburg</b> diagram, in (²³⁸U/²⁰⁶Pb, ²⁰⁷Pb/²⁰⁶Pb) space,
which is convenient for young or common-Pb-bearing samples; ZirClock builds both.
In very young zircon the measured ²⁰⁷Pb/²³⁵U can fall <b>below zero</b> by counting
noise: that analysis has no ²⁰⁷Pb/²³⁵U age, but its ratio, with its uncertainty, is
still a valid observation, and it enters the concordia age as measured (taking its
absolute value would bias the young analyses toward older ages).</p>
"""
    return html, res


def _theory_sec_discordance(n, accent, ink):
    """§ Discordance and P(concordance) — Ludwig (1998); criterio de traslape
    recomendado por Spencer et al. (2016)."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt
    from matplotlib.patches import Ellipse

    def diagram():
        fig, ax = plt.subplots(figsize=(5.2, 3.7))
        ages = np.linspace(850e6, 1150e6, 300)
        X = np.exp(LAMBDA_U235 * ages) - 1.0
        Y = np.exp(LAMBDA_U238 * ages) - 1.0
        ax.plot(X, Y, color=ink, lw=1.8, zorder=2)

        def curve_y(xq):
            t = math.log(xq + 1.0) / LAMBDA_U235
            return math.exp(LAMBDA_U238 * t) - 1.0

        xmid = float(X.mean())
        off = 0.013
        xa, xb = xmid - 0.055, xmid + 0.06
        ya, yb = curve_y(xa) - off, curve_y(xb) - off
        # A: preciso (elipse chica) → NO toca la curva → discordante
        ax.add_patch(Ellipse((xa, ya), 0.045, 0.011, angle=10,
                             facecolor="#c0392b", alpha=0.30, edgecolor="#c0392b",
                             lw=1.3, zorder=4))
        ax.annotate("precise\nP < 5%  ✗", (xa, ya), textcoords="offset points",
                    xytext=(0, -30), fontsize=8, color="#c0392b", ha="center")
        # B: impreciso (elipse grande) → SÍ toca la curva → concordante
        ax.add_patch(Ellipse((xb, yb), 0.12, 0.033, angle=10,
                             facecolor="#1d9e75", alpha=0.22, edgecolor="#1d9e75",
                             lw=1.3, zorder=4))
        ax.annotate("imprecise\nP ≥ 5%  ✓", (xb, yb), textcoords="offset points",
                    xytext=(0, -34), fontsize=8, color="#1d9e75", ha="center")
        ax.set_xlabel("²⁰⁷Pb/²³⁵U", fontsize=9)
        ax.set_ylabel("²⁰⁶Pb/²³⁸U", fontsize=9)
        ax.tick_params(labelsize=8)
        ax.set_xlim(X.min(), X.max()); ax.set_ylim(Y.min() - 0.03, Y.max())
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_disc": _pdf_math_img(
            r"$\mathrm{Disc\%} = \left(1 - \dfrac{t_{206/238}}"
            r"{t_{207/206}}\right)\times 100$", fontsize=16),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Discordance and
P(concordance)</h2>
<p style="font-size:12.5pt; line-height:150%;">A <i>discordant</i> analysis plots off
the concordia curve (&sect;{n - 1}). ZirClock offers two ways to decide whether an
analysis is concordant.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>1. Percentage discordance (Disc%).</b>
The classic measure compares two of the dates. By default ZirClock uses the
²⁰⁶Pb/²³⁸U vs ²⁰⁷Pb/²⁰⁶Pb pair (a ²⁰⁷Pb/²³⁵U variant is available):</p>
<p align="center"><img src="s{n}_disc" width="320"/></p>
<p style="font-size:12.5pt; line-height:150%;">An analysis is called concordant when
|Disc%| ≤ a chosen threshold (default 10%). This is simple, but it <b>ignores the
uncertainty</b>: a very precise analysis and a very imprecise one with the same
Disc% are treated identically.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>2. Probability of concordance,
P(concordance)</b> (Ludwig 1998). Spencer et al. (2016) recommend replacing an
arbitrary Disc% threshold with a test of whether each analysis lies within
analytical uncertainty of concordia; Ludwig's concordance statistic provides that
test. It uses the full uncertainty of the analysis, including the error correlation
ρ. ZirClock computes the analysis's own concordia age (&sect;{n - 1}); the minimized
Mahalanobis distance S at that age is the <i>concordance statistic</i>. Two ratios
are measured and one parameter (the age) is fitted, so S has one degree of freedom
and</p>
<p align="center" style="font-size:12.5pt;"><i>P</i>(concordance) =
1 − χ²<sub>CDF</sub>(<i>S</i>; 1&nbsp;d.o.f.),&nbsp;&nbsp;reported as a percentage.</p>
<p style="font-size:12.5pt; line-height:150%;">The analysis is concordant when
P&nbsp;≥&nbsp;5% (equivalently S&nbsp;≤&nbsp;3.84&nbsp;=&nbsp;1.96²). Geometrically,
S&nbsp;≤&nbsp;k² means that the error ellipse scaled to kσ reaches the concordia
curve, so P&nbsp;≥&nbsp;5% is the same as the 1.96σ ellipse overlapping the curve.
Because the test scales the offset by the ellipse, a <b>precise</b> analysis a small
distance off concordia can be <i>discordant</i> (its tight ellipse does not overlap
the curve), while an <b>imprecise</b> one at the same distance is <i>concordant</i>
(its wide ellipse does) — exactly the situation Disc% misses:</p>
<p align="center"><img src="s{n}_fig" width="340"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> Two
analyses the same distance below concordia. The precise one (red) does not reach the
curve at 1.96σ → discordant; the imprecise one (green) overlaps it → concordant.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>Note.</b> The ellipses drawn on
ZirClock's concordia diagrams are 95% confidence regions for the two ratios
jointly (χ² with two degrees of freedom, 2.45σ), slightly larger than the 1.96σ
ellipse of this test. An analysis whose drawn ellipse only grazes the curve can
therefore still have P between 1.4% and 5%.</p>
<p style="font-size:12.5pt; line-height:150%;">In ZirClock the criterion is chosen in
the U–Pb dialog, and the outcome feeds the ✓/✗ reliability column and, if enabled,
the exclusion of discordant analyses from the weighted mean (&sect;{n + 1}).</p>
"""
    return html, res


def _theory_sec_wmean(n, accent, ink):
    """§ Weighted mean, MSWD and P(MSWD)."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        rng = np.random.default_rng(7)
        m = 7
        true = 1000.0
        s2 = np.array([12., 15., 10., 18., 11., 14., 16.])   # ±2σ de cada análisis
        vals = true + rng.normal(0.0, (s2 / 2.0) * 1.25, m)
        w = 1.0 / (s2 / 2.0) ** 2
        mean = float((vals * w).sum() / w.sum())
        sig_int_1 = 1.0 / math.sqrt(w.sum())
        chi2 = float((w * (vals - mean) ** 2).sum())
        mswd = chi2 / (m - 1)
        expand = math.sqrt(mswd) if mswd > 1 else 1.0
        sig_ext_2 = 2.0 * sig_int_1 * expand
        fig, ax = plt.subplots(figsize=(5.6, 3.2))
        xs = np.arange(1, m + 1)
        ax.errorbar(xs, vals, yerr=s2, fmt="o", ms=5, color=accent,
                    ecolor=accent, elinewidth=1.2, capsize=3, zorder=3)
        ax.axhspan(mean - sig_ext_2, mean + sig_ext_2, color=accent, alpha=0.13,
                   zorder=1)
        ax.axhline(mean, color=accent, lw=1.4, zorder=2)
        ax.set_xlim(0.4, m + 0.6)
        ax.set_xlabel("analysis", fontsize=9); ax.set_ylabel("age (Ma)", fontsize=9)
        ax.tick_params(labelsize=8)
        ax.text(0.97, 0.05,
                f"weighted mean = {mean:.0f} ± {sig_ext_2:.0f} Ma (2σ)\n"
                f"MSWD = {mswd:.2f}   n = {m}",
                transform=ax.transAxes, ha="right", va="bottom", fontsize=8,
                color=ink, bbox=dict(boxstyle="round,pad=0.3", facecolor="white",
                                     edgecolor=accent, alpha=0.85))
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_wm": _pdf_math_img(
            r"$\bar{x} = \dfrac{\sum_i w_i x_i}{\sum_i w_i}, \qquad "
            r"w_i = \dfrac{1}{\sigma_i^{2}}, \qquad "
            r"\sigma_{\bar{x}} = \dfrac{1}{\sqrt{\sum_i w_i}}$", fontsize=15),
        f"s{n}_mswd": _pdf_math_img(
            r"$\mathrm{MSWD} = \dfrac{1}{n-1}\sum_i "
            r"\dfrac{(x_i-\bar{x})^{2}}{\sigma_i^{2}}$", fontsize=16),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Weighted mean, MSWD and
P(MSWD)</h2>
<p style="font-size:12.5pt; line-height:150%;">When several analyses date the same
event, their best estimate is the <b>inverse-variance weighted mean</b>: each
analysis is weighted by 1/σ², so more precise analyses count more. The mean and its
<i>internal</i> (analytical) uncertainty are</p>
<p align="center"><img src="s{n}_wm" width="380"/></p>
<p style="font-size:12.5pt; line-height:150%;">The <b>MSWD</b> (Mean Square of the
Weighted Deviates) tests whether the observed scatter matches what the analytical
uncertainties predict:</p>
<p align="center"><img src="s{n}_mswd" width="270"/></p>
<p style="font-size:12.5pt; line-height:150%;">MSWD&nbsp;≈&nbsp;1 means the scatter is
consistent with the stated errors (a single population); MSWD&nbsp;≫&nbsp;1 signals
<b>overdispersion</b> — excess scatter from geological or unaccounted sources;
MSWD&nbsp;≪&nbsp;1 suggests the uncertainties were overestimated.
<b>P(MSWD)</b>&nbsp;=&nbsp;1&nbsp;−&nbsp;χ²<sub>CDF</sub>(χ²; n−1) is the probability
of seeing that much scatter by chance; small P (&lt;&nbsp;~5%) points to
overdispersion. ZirClock also flags overdispersion when
MSWD&nbsp;&gt;&nbsp;1&nbsp;+&nbsp;2√(2/(n−1)).</p>
<p style="font-size:12.5pt; line-height:150%;">Following the IsoplotR convention (Vermeesch 2018), when
MSWD&nbsp;&gt;&nbsp;1 ZirClock reports an <i>external</i> uncertainty inflated by
√MSWD (σ<sub>ext</sub>&nbsp;=&nbsp;σ<sub>int</sub>·√MSWD), making the quoted error
consistent with the real scatter; when MSWD&nbsp;≤&nbsp;1 the error is not reduced.</p>
<p align="center"><img src="s{n}_fig" width="380"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> Seven
analyses (points, 2σ bars) and their weighted mean (line) with the √MSWD-expanded 2σ
band (shaded).</p>
"""
    return html, res


def _theory_sec_discordia(n, accent, ink):
    """§ Discordia regression (York 2004) and intercept ages."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt
    from matplotlib.patches import Ellipse

    def diagram():
        fig, ax = plt.subplots(figsize=(5.4, 3.9))
        ages = np.linspace(40e6, 2000e6, 400)
        X = np.exp(LAMBDA_U235 * ages) - 1.0
        Y = np.exp(LAMBDA_U238 * ages) - 1.0
        ax.plot(X, Y, color=ink, lw=1.8, zorder=2)

        def cpt(t_ma):
            ty = t_ma * 1e6
            return (math.exp(LAMBDA_U235 * ty) - 1.0,
                    math.exp(LAMBDA_U238 * ty) - 1.0)

        up, lo = cpt(1800), cpt(300)
        slope = (up[1] - lo[1]) / (up[0] - lo[0])
        xline = np.array([lo[0] - 0.25, up[0] + 0.5])
        yline = lo[1] + slope * (xline - lo[0])
        ax.plot(xline, yline, color="#c0392b", lw=1.4, zorder=3)
        for f in (0.22, 0.44, 0.62, 0.82):
            px = lo[0] + f * (up[0] - lo[0])
            py = lo[1] + f * (up[1] - lo[1])
            ax.add_patch(Ellipse((px, py), 0.10, 0.013, angle=0,
                                 facecolor=accent, alpha=0.24, edgecolor=accent,
                                 lw=1.1, zorder=4))
        for pt, lab, dxy, ha in ((up, "upper intercept\n1800 Ma", (6, 4), "left"),
                                 (lo, "lower intercept\n300 Ma", (6, -20), "left")):
            ax.plot(*pt, "o", ms=6, color="#c0392b", zorder=5)
            ax.annotate(lab, pt, textcoords="offset points", xytext=dxy,
                        fontsize=8, color="#c0392b", ha=ha)
        ax.set_xlabel("²⁰⁷Pb/²³⁵U", fontsize=9)
        ax.set_ylabel("²⁰⁶Pb/²³⁸U", fontsize=9)
        ax.tick_params(labelsize=8)
        ax.set_xlim(0, X.max() * 1.05); ax.set_ylim(0, Y.max() * 1.10)
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_W": _pdf_math_img(
            r"$W_i = \dfrac{w_{x_i}\,w_{y_i}}{w_{x_i} + b^{2} w_{y_i}"
            r" - 2\,b\,\rho_i\sqrt{w_{x_i}w_{y_i}}}, \qquad "
            r"w_{x_i} = 1/\sigma_{x_i}^{2}$", fontsize=15),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Discordia regression
(York) and intercept ages</h2>
<p style="font-size:12.5pt; line-height:150%;">A suite of grains affected by
<b>variable Pb loss</b> at one time does not scatter randomly: the analyses fall
along a straight <b>chord</b> — the <b>discordia</b> — that cuts the concordia at
two points. The <b>upper intercept</b> gives the original crystallization age and
the <b>lower intercept</b> gives the age of the disturbance (e.g. metamorphism, or
near-zero for recent loss).</p>
<p align="center"><img src="s{n}_fig" width="360"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> Four
discordant analyses (blue) define a discordia (red) whose intercepts with concordia
give the upper (1800 Ma) and lower (300 Ma) ages.</p>
<p style="font-size:12.5pt; line-height:150%;">Fitting that line is not ordinary
least squares: <b>both</b> axes carry uncertainty and they are correlated
(σ<sub>x</sub>, σ<sub>y</sub>, ρ; &sect;{n - 4}). ZirClock uses the unified
least-squares algorithm of <b>York et al. (2004)</b>, which iterates the slope
<i>b</i> using the effective weight</p>
<p align="center"><img src="s{n}_W" width="330"/></p>
<p style="font-size:12.5pt; line-height:150%;">with w<sub>x</sub>&nbsp;=&nbsp;1/σ<sub>x</sub>²
and w<sub>y</sub>&nbsp;=&nbsp;1/σ<sub>y</sub>²; the intercept and both intercept ages
follow from the converged line, and its scatter is summarised by
MSWD&nbsp;=&nbsp;S/(n−2). Three fit models are available:
<b>Model&nbsp;1</b> assumes the scatter is fully explained by the analytical
uncertainties (use when MSWD&nbsp;≈&nbsp;1); <b>Model&nbsp;2</b> is a total-least-squares
(orthogonal) fit that de-emphasises the stated errors when they are not trusted; and
<b>Model&nbsp;3</b> adds a Gaussian over-dispersion term ω², estimated by maximum
likelihood (n&nbsp;≥&nbsp;4), for genuine geological excess scatter. The same
machinery drives the Tera–Wasserburg discordia.</p>
"""
    return html, res


def _theory_sec_bestage(n, accent, ink):
    """§ Best-age selection (Spencer et al. 2016 cutoff)."""
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        fig, ax = plt.subplots(figsize=(5.6, 3.3))
        age = np.linspace(0, 3000, 400)
        u638 = 0.4 + 0.00070 * age              # sube con la edad (esquemático)
        u76 = 9.0 * np.exp(-age / 750.0) + 0.25  # baja con la edad (esquemático)
        cutoff = 1500.0
        ax.plot(age, u638, color=accent, lw=2.0, label="²⁰⁶Pb/²³⁸U")
        ax.plot(age, u76, color="#c0392b", lw=2.0, label="²⁰⁷Pb/²⁰⁶Pb")
        ax.axvline(cutoff, color=ink, lw=1.0, ls="--")
        ax.axvspan(0, cutoff, color=accent, alpha=0.06)
        ax.axvspan(cutoff, 3000, color="#c0392b", alpha=0.06)
        ax.annotate("use ²⁰⁶Pb/²³⁸U", (cutoff*0.5, 3.2), fontsize=8,
                    color=accent, ha="center")
        ax.annotate("use ²⁰⁷Pb/²⁰⁶Pb", (cutoff + (3000-cutoff)*0.5, 3.2),
                    fontsize=8, color="#c0392b", ha="center")
        ax.annotate("cutoff\n1500 Ma", (cutoff, 0.15), fontsize=7.5, color=ink,
                    ha="center", va="bottom")
        ax.set_xlabel("age (Ma)", fontsize=9)
        ax.set_ylabel("relative age uncertainty (schematic)", fontsize=8.5)
        ax.set_ylim(0, 3.6); ax.set_xlim(0, 3000)
        ax.tick_params(labelsize=8)
        ax.legend(fontsize=8, loc="upper center")
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {f"s{n}_fig": diagram()}
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Best-age selection</h2>
<p style="font-size:12.5pt; line-height:150%;">Each analysis yields three dates
(²⁰⁶Pb/²³⁸U, ²⁰⁷Pb/²³⁵U, ²⁰⁷Pb/²⁰⁶Pb). Which one is the most reliable depends on
age. For <b>young</b> grains the ²⁰⁶Pb/²³⁸U clock is by far the most precise. For
<b>old</b> grains ²³⁵U is nearly extinct and radiogenic ²⁰⁷Pb has accumulated, so
the ²⁰⁷Pb/²⁰⁶Pb ratio becomes the most precise and least sensitive to recent
disturbance, while the ²⁰⁶Pb/²³⁸U precision degrades.</p>
<p align="center"><img src="s{n}_fig" width="370"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b>
Schematic relative precision of the two chronometers versus age. They cross near
1–1.5 Ga; below the cutoff ²⁰⁶Pb/²³⁸U is preferred, above it ²⁰⁷Pb/²⁰⁶Pb.</p>
<p style="font-size:12.5pt; line-height:150%;">Following <b>Spencer et al. (2016)</b>,
ZirClock applies a single crossover cutoff (default <b>1500 Ma</b>, editable): the
<b>preferred (best) age</b> is the ²⁰⁶Pb/²³⁸U date when it is at or below the cutoff,
and the ²⁰⁷Pb/²⁰⁶Pb date when it is above. This preferred age is what feeds the
reliability column, the weighted means (&sect;{n - 2}) and every Panel&nbsp;5 diagram
that plots "Best age".</p>
"""
    return html, res


def _theory_sec_hf(n, accent, ink):
    """§ Lu–Hf isotopes: εHf(t), T_DM and two-stage T_DM^C."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        lam = LAMBDA_LU176
        chur = CHUR_OPTIONS["Bouvier et al. (2008)"]
        chur_hf, chur_luhf = chur["hf_ratio"], chur["lu_hf"]
        dm_hf, dm_luhf = DM_HF_RATIO, DM_LU_HF
        crust = CRUSTAL_LU_HF_OPTIONS["Griffin et al. (2002)"]
        ages = np.linspace(0, 2500e6, 400)

        def et(t):
            return np.exp(lam * t) - 1.0

        fig, ax = plt.subplots(figsize=(5.6, 3.9))
        ax.plot(ages / 1e6, dm_hf - dm_luhf * et(ages), color="#2a8a5a",
                lw=2.0, label="DM (Blichert-Toft & Albarède 1997)")
        _vk = DM_OPTIONS["Vervoort & Kemp (2025)"]       # 2026-09-29
        ax.plot(ages / 1e6, _vk["hf_ratio"] - _vk["lu_hf"] * et(ages),
                color="#2a8a5a", lw=1.2, ls=":",
                label="DM (Vervoort & Kemp 2025)")
        ax.plot(ages / 1e6, chur_hf - chur_luhf * et(ages), color=ink, lw=1.4,
                ls="--", label="CHUR")
        tc = 1200e6
        hf_i = 0.28215
        hf_dm_tc = dm_hf - dm_luhf * (math.exp(lam * tc) - 1.0)
        arg = 1.0 + (hf_i - hf_dm_tc) / (crust - dm_luhf)
        tdmc = math.log(arg) / lam + tc
        ts = np.linspace(tc, tdmc, 40)
        ax.plot(ts / 1e6, hf_i - crust * (np.exp(lam * ts) - math.exp(lam * tc)),
                color=accent, lw=1.8)
        ax.plot([tc / 1e6], [hf_i], "o", ms=6, color=accent, zorder=5)
        ax.annotate("zircon\n(t = 1200 Ma)", (tc / 1e6, hf_i),
                    textcoords="offset points", xytext=(8, 4), fontsize=8,
                    color=accent)
        ax.plot([tdmc / 1e6], [dm_hf - dm_luhf * (math.exp(lam * tdmc) - 1)],
                "s", ms=6, color=accent, zorder=5)
        ax.annotate(f"T$_{{DM}}^C$ ≈ {tdmc/1e6:.0f} Ma",
                    (tdmc / 1e6, dm_hf - dm_luhf * (math.exp(lam * tdmc) - 1)),
                    textcoords="offset points", xytext=(6, -14), fontsize=8,
                    color=accent)
        ax.set_xlabel("age (Ma)", fontsize=9)
        ax.set_ylabel("¹⁷⁶Hf/¹⁷⁷Hf", fontsize=9)
        ax.set_ylim(0.2811, 0.28345); ax.set_xlim(0, 2500)
        ax.tick_params(labelsize=8)
        ax.legend(fontsize=8, loc="lower left")
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_ri": _pdf_math_img(
            r"$R_i = R_{meas} - (Lu/Hf)_{meas}\,(e^{\lambda t}-1)$", fontsize=15),
        f"s{n}_eps": _pdf_math_img(
            r"$\varepsilon_{Hf}(t) = \left[\dfrac{R_i}{R_{CHUR}(t)} - 1\right]"
            r"\times 10^{4}$", fontsize=16),
        f"s{n}_tdm": _pdf_math_img(
            r"$T_{DM} = \dfrac{1}{\lambda}\ln\!\left(1 + "
            r"\dfrac{R_{meas}-R_{DM}}{(Lu/Hf)_{meas}-(Lu/Hf)_{DM}}\right)$",
            fontsize=15),
        f"s{n}_tdmc": _pdf_math_img(
            r"$T_{DM}^{C} = \dfrac{1}{\lambda}\ln\!\left(1 + "
            r"\dfrac{R_i(t)-R_{DM}(t)}{(Lu/Hf)_{crust}-(Lu/Hf)_{DM}}\right) + t$",
            fontsize=15),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Lu–Hf isotopes: εHf(t)
and model ages</h2>
<p style="font-size:12.5pt; line-height:150%;">The ¹⁷⁶Lu&nbsp;→&nbsp;¹⁷⁶Hf decay
tracks crust–mantle differentiation. Zircon incorporates almost no Lu, so its
¹⁷⁶Hf/¹⁷⁷Hf is essentially frozen at crystallization and records the Hf isotope
composition of its <b>source</b>. Writing <i>R</i> for ¹⁷⁶Hf/¹⁷⁷Hf and (Lu/Hf) for
¹⁷⁶Lu/¹⁷⁷Hf, the <b>initial ratio</b> at the crystallization age <i>t</i> is</p>
<p align="center"><img src="s{n}_ri" width="300"/></p>
<p style="font-size:12.5pt; line-height:150%;"><b>εHf(t)</b> expresses that initial
ratio relative to a chondritic reservoir (CHUR) at the same age, in parts per 10⁴,
with R<sub>CHUR</sub>(t)&nbsp;=&nbsp;R<sub>CHUR</sub>&nbsp;−&nbsp;(Lu/Hf)<sub>CHUR</sub>(e<sup>λt</sup>−1):</p>
<p align="center"><img src="s{n}_eps" width="270"/></p>
<p style="font-size:12.5pt; line-height:150%;">Positive εHf(t) means the magma came
from a <b>depleted (juvenile) source</b>; negative εHf(t) means it reworked <b>older
crust</b>. λ¹⁷⁶Lu is from Söderlund et al. (2004); CHUR from Bouvier et al. (2008).</p>
<p style="font-size:12.5pt; line-height:150%;"><b>Model ages</b> estimate when the
source separated from the mantle. The single-stage <b>T<sub>DM</sub></b>
back-projects the measured ratio with the grain's own (Lu/Hf) until it meets the
depleted-mantle line:</p>
<p align="center"><img src="s{n}_tdm" width="330"/></p>
<p style="font-size:12.5pt; line-height:150%;">Two depleted-mantle references are
offered (Panel&nbsp;4&nbsp;▸&nbsp;Hf): the classic line of Blichert-Toft &amp;
Albarède (1997), and that of <b>Vervoort &amp; Kemp (2025)</b>, which stays
chondritic until 3.8&nbsp;Ga and then evolves in a single stage to εHf&nbsp;=&nbsp;+18
today (R<sub>DM</sub>&nbsp;=&nbsp;0.283294, (Lu/Hf)<sub>DM</sub>&nbsp;=&nbsp;0.04052).
With the latter, a model age older than 3.8&nbsp;Ga is computed against CHUR, and
CHUR is fixed to Bouvier et al. (2008), on which it is defined. As those authors
stress, model ages are reference values, not precise dates.</p>
<p style="font-size:12.5pt; line-height:150%;">Because zircon (Lu/Hf) is atypically
low, the two-stage crustal model age <b>T<sub>DM</sub><sup>C</sup></b> is preferred:
from the initial ratio at <i>t</i> it back-projects with an average <b>crustal</b>
(Lu/Hf) (0.015, Griffin et al. 2002) to the depleted mantle:</p>
<p align="center"><img src="s{n}_tdmc" width="360"/></p>
<p align="center"><img src="s{n}_fig" width="380"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> A zircon
crystallized at 1200 Ma evolves back along a crustal (Lu/Hf) path (blue) until it
meets the depleted mantle at T<sub>DM</sub><sup>C</sup>. CHUR (dashed) is the
reference for εHf(t).</p>
"""
    return html, res


def _theory_sec_ti(n, accent, ink):
    """§ Ti-in-zircon thermometry (Ferry & Watson 2007 / Crisp 2023)."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        fig, ax = plt.subplots(figsize=(5.4, 3.4))
        ti = np.linspace(2, 70, 300)

        def T_of_Ti(a_ti):
            denom = TI_FW07_A - np.log10(ti) - 0.0 + math.log10(a_ti)  # aSiO2=1
            return TI_FW07_B / denom - 273.15

        ax.plot(ti, T_of_Ti(1.0), color=accent, lw=2.0,
                label="a$_{TiO_2}$ = 1 (rutile-saturated)")
        ax.plot(ti, T_of_Ti(0.7), color="#c0392b", lw=1.6, ls="--",
                label="a$_{TiO_2}$ = 0.7")
        ax.set_xscale("log")
        ax.set_xlabel("Ti in zircon (ppm)", fontsize=9)
        ax.set_ylabel("T (°C)", fontsize=9)
        ax.tick_params(labelsize=8)
        ax.grid(True, which="both", alpha=0.25, lw=0.5)
        ax.legend(fontsize=8, loc="upper left")
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_eq": _pdf_math_img(
            r"$\log(\mathrm{Ti^{zrc}}) = A - \dfrac{B}{T} "
            r"- \log a_{\mathrm{SiO_2}} + \log a_{\mathrm{TiO_2}}$", fontsize=15),
        f"s{n}_solve": _pdf_math_img(
            r"$T(\mathrm{K}) = \dfrac{B}{A - \log\mathrm{Ti} "
            r"- \log a_{\mathrm{SiO_2}} + \log a_{\mathrm{TiO_2}}}$", fontsize=15),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Ti-in-zircon
thermometry</h2>
<p style="font-size:12.5pt; line-height:150%;">The amount of Ti that substitutes into
the zircon lattice increases with <b>temperature</b>, provided the activities of
TiO₂ and SiO₂ in the system are known. Ferry &amp; Watson (2007) calibrated this as</p>
<p align="center"><img src="s{n}_eq" width="330"/></p>
<p style="font-size:12.5pt; line-height:150%;">with A&nbsp;=&nbsp;5.711 and
B&nbsp;=&nbsp;4800, which ZirClock inverts for the crystallization temperature:</p>
<p align="center"><img src="s{n}_solve" width="330"/></p>
<p align="center"><img src="s{n}_fig" width="360"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> Ti-in-zircon
temperature versus Ti content (Ferry &amp; Watson 2007), for two TiO₂ activities. A
lower a<sub>TiO₂</sub> raises the inferred temperature for the same Ti.</p>
<p style="font-size:12.5pt; line-height:150%;">The <b>activities</b> matter: with
rutile present a<sub>TiO₂</sub>&nbsp;=&nbsp;1 and with quartz a<sub>SiO₂</sub>&nbsp;=&nbsp;1,
but without those buffers the activities are &lt;&nbsp;1 and must be estimated — the
largest source of systematic error. ZirClock lets you set a<sub>TiO₂</sub>,
a<sub>SiO₂</sub> (and pressure) per sample, and offers the pressure-corrected
calibration of <b>Crisp et al. (2023)</b>, which adds a pressure term and a
Ti-site-occupancy factor. The analytical temperature uncertainty is propagated as
σ<sub>T</sub>&nbsp;=&nbsp;T²σ<sub>Ti</sub>/(B·Ti·ln10); a population option reports
the scatter of the grains instead.</p>
"""
    return html, res


def _theory_sec_ree(n, accent, ink):
    """§ REE normalization and the Eu / Ce anomalies."""
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        els = ["La", "Ce", "Pr", "Nd", "Sm", "Eu", "Gd", "Tb", "Dy", "Ho",
               "Er", "Tm", "Yb", "Lu"]
        vals = np.array([0.8, 12, 1.5, 4, 15, 6, 40, 90, 300, 700, 1500, 2200,
                         3500, 4500.0])
        x = np.arange(len(els))
        fig, ax = plt.subplots(figsize=(5.8, 3.6))
        ax.plot(x, vals, "-o", color=accent, ms=4, lw=1.6, zorder=3)
        ax.set_yscale("log")
        # Ce*: interpolación geométrica La–Pr
        i_la, i_ce, i_pr = 0, 1, 2
        ce_star = np.sqrt(vals[i_la] * vals[i_pr])
        ax.plot([i_la, i_pr], [vals[i_la], vals[i_pr]], ls="--", color="#c0392b",
                lw=1.0, zorder=2)
        ax.plot(i_ce, ce_star, "s", color="#c0392b", ms=5, zorder=4)
        ax.annotate("Ce/Ce* > 1", (i_ce, vals[i_ce]), textcoords="offset points",
                    xytext=(4, 6), fontsize=8, color="#c0392b")
        # Eu*: interpolación geométrica Sm–Gd
        i_sm, i_eu, i_gd = 4, 5, 6
        eu_star = np.sqrt(vals[i_sm] * vals[i_gd])
        ax.plot([i_sm, i_gd], [vals[i_sm], vals[i_gd]], ls="--", color="#8e44ad",
                lw=1.0, zorder=2)
        ax.plot(i_eu, eu_star, "s", color="#8e44ad", ms=5, zorder=4)
        ax.annotate("Eu/Eu* < 1", (i_eu, vals[i_eu]), textcoords="offset points",
                    xytext=(-4, -16), fontsize=8, color="#8e44ad", ha="center")
        ax.set_xticks(x); ax.set_xticklabels(els, fontsize=7.5)
        ax.set_ylabel("sample / chondrite", fontsize=9)
        ax.tick_params(axis="y", labelsize=8)
        ax.grid(True, which="both", axis="y", alpha=0.2, lw=0.5)
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_norm": _pdf_math_img(
            r"$X_N = X_{sample}\,/\,X_{chondrite}$", fontsize=15),
        f"s{n}_eu": _pdf_math_img(
            r"$\mathrm{Eu/Eu^{*}} = \dfrac{Eu_N}{\sqrt{Sm_N\cdot Gd_N}}$",
            fontsize=16),
        f"s{n}_ce": _pdf_math_img(
            r"$\mathrm{Ce/Ce^{*}} = \dfrac{Ce_N}{\sqrt{La_N\cdot Pr_N}}$",
            fontsize=16),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;REE normalization and the
Eu / Ce anomalies</h2>
<p style="font-size:12.5pt; line-height:150%;">Raw rare-earth-element (REE)
abundances zig-zag with atomic number (even elements are more abundant than odd —
the Oddo–Harkins effect). Dividing each element by a <b>chondrite</b> reference
removes that sawtooth and reveals the petrological signal:</p>
<p align="center"><img src="s{n}_norm" width="230"/></p>
<p style="font-size:12.5pt; line-height:150%;">ZirClock normalizes to a chondrite
reference chosen in Panel&nbsp;4 (Sun &amp; McDonough 1989, Boynton 1984, or
McDonough &amp; Sun 1995) and plots La&nbsp;→&nbsp;Lu on a log scale — the
<b>spider</b> pattern. Zircon is characteristically depleted in light REE, enriched
in heavy REE, with a <b>positive Ce</b> and a <b>negative Eu</b> anomaly:</p>
<p align="center"><img src="s{n}_fig" width="380"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> A typical
chondrite-normalized zircon pattern. Ce* and Eu* (squares) are the values expected
by interpolating the neighbours; the gap to the measured point is the anomaly.</p>
<p style="font-size:12.5pt; line-height:150%;">An <b>anomaly</b> compares an element
to what it "should" be, interpolated from its neighbours by the geometric mean. The
<b>Eu anomaly</b> uses Sm and Gd:</p>
<p align="center"><img src="s{n}_eu" width="230"/></p>
<p style="font-size:12.5pt; line-height:150%;">Eu/Eu*&nbsp;&lt;&nbsp;1 (a trough) records
<b>plagioclase</b> fractionation, since Eu²⁺ enters plagioclase under reducing
conditions. The <b>Ce anomaly</b> uses La and Pr:</p>
<p align="center"><img src="s{n}_ce" width="230"/></p>
<p style="font-size:12.5pt; line-height:150%;">Ce/Ce*&nbsp;&gt;&nbsp;1 (a peak) reflects
<b>oxidising</b> conditions, where Ce⁴⁺ is preferentially taken up by zircon. Because
La in zircon is often near the detection limit, Ce/Ce* can be unreliable; ZirClock
lets you drop anomalously low La values, in which case Ce/Ce* is left undefined.</p>
"""
    return html, res


def _theory_sec_kde(n, accent, ink):
    """§ Age distributions: KDE, PDP and peak detection."""
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        rng = np.random.default_rng(11)
        a1 = rng.normal(550, 20, 13)
        a2 = rng.normal(1050, 32, 8)
        ages = np.concatenate([a1, a2])
        sig = np.concatenate([rng.uniform(7, 16, 13), rng.uniform(14, 30, 8)])
        grid = np.linspace(430, 1230, 600)
        std = ages.std(ddof=1)
        q75, q25 = np.percentile(ages, [75, 25])
        iqr = q75 - q25
        sig_s = min(std, iqr / 1.349) if iqr > 0 else std
        bw = 0.9 * sig_s * ages.size ** (-0.2)
        z = (grid[:, None] - ages[None, :]) / bw
        kde = (np.exp(-0.5 * z * z) / (bw * np.sqrt(2 * np.pi))).sum(1) / ages.size
        zp = (grid[:, None] - ages[None, :]) / sig[None, :]
        pdp = (np.exp(-0.5 * zp * zp) / (sig[None, :] * np.sqrt(2 * np.pi))
               ).sum(1) / ages.size
        fig, ax = plt.subplots(figsize=(5.8, 3.4))
        ax.plot(grid, kde / kde.max(), color=accent, lw=2.0,
                label=f"KDE (Silverman, h = {bw:.0f} Ma)")
        ax.plot(grid, pdp / pdp.max(), color="#c0392b", lw=1.4, ls="--",
                label="PDP")
        ax.plot(ages, np.full_like(ages, -0.04), "|", color=ink, ms=9, mew=1.0)
        for pk in (550, 1050):
            ax.annotate("peak", (pk, 1.0), textcoords="offset points",
                        xytext=(0, 2), fontsize=7.5, color=ink, ha="center")
        ax.set_xlabel("age (Ma)", fontsize=9)
        ax.set_ylabel("relative density", fontsize=9)
        ax.set_ylim(-0.08, 1.15)
        ax.tick_params(labelsize=8)
        ax.legend(fontsize=8, loc="upper right")
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_kde": _pdf_math_img(
            r"$f(x) = \dfrac{1}{n}\sum_i \dfrac{1}{h\sqrt{2\pi}}\,"
            r"\exp\!\left(-\dfrac{(x-a_i)^{2}}{2h^{2}}\right)$", fontsize=15),
        f"s{n}_bw": _pdf_math_img(
            r"$h = 0.9\,\min\!\left(\sigma,\; \mathrm{IQR}/1.349\right)\,n^{-1/5}$",
            fontsize=15),
        f"s{n}_pdp": _pdf_math_img(
            r"$f(x) = \dfrac{1}{n}\sum_i \dfrac{1}{\sigma_i\sqrt{2\pi}}\,"
            r"\exp\!\left(-\dfrac{(x-a_i)^{2}}{2\sigma_i^{2}}\right)$", fontsize=15),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Age distributions: KDE,
PDP and peaks</h2>
<p style="font-size:12.5pt; line-height:150%;">A suite of detrital or inherited dates
is best seen as a smooth distribution rather than a histogram. ZirClock builds two
kinds of curve.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>Kernel density estimate (KDE).</b>
Each age is replaced by a Gaussian of a common <b>bandwidth</b> <i>h</i>, and the
Gaussians are summed and normalized:</p>
<p align="center"><img src="s{n}_kde" width="330"/></p>
<p style="font-size:12.5pt; line-height:150%;">The bandwidth is a smoothing choice, not
the analytical error. ZirClock uses Silverman's robust rule (editable),</p>
<p align="center"><img src="s{n}_bw" width="320"/></p>
<p style="font-size:12.5pt; line-height:150%;">so the KDE shows the shape of the
population without letting one very precise analysis spike the curve (Vermeesch
2012).</p>
<p style="font-size:12.5pt; line-height:150%;"><b>Probability density plot (PDP).</b>
Here each age is a Gaussian of its <b>own</b> uncertainty σ<sub>i</sub>:</p>
<p align="center"><img src="s{n}_pdp" width="330"/></p>
<p style="font-size:12.5pt; line-height:150%;">so precise analyses form sharp spikes
and imprecise ones broad bumps. This can create artefacts, which is why the KDE is
now preferred; ZirClock draws both.</p>
<p align="center"><img src="s{n}_fig" width="380"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> The same
21 dates as a KDE (solid) and a PDP (dashed), each scaled to its maximum; ticks mark
the individual ages. The PDP is spikier around the more precise analyses.</p>
<p style="font-size:12.5pt; line-height:150%;"><b>Peaks (populations).</b> ZirClock
flags a curve maximum as an age population when it clears a prominence threshold
<i>and</i> is backed by at least <i>N</i> analyses whose age ± <i>k</i>σ interval
covers the peak — the YC2σ convention (default N&nbsp;≥&nbsp;3 at 2σ; Dickinson &amp;
Gehrels 2009). Each peak is reported with its supporting grain count.</p>
"""
    return html, res


def _theory_sec_radial(n, accent, ink):
    """§ Radial plot, central age and mixture model (2026-09-26)."""
    import math
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        rng = np.random.default_rng(5)
        ages = np.concatenate([600 * np.exp(rng.normal(0, 0.015, 9)),
                               1000 * np.exp(rng.normal(0, 0.015, 14))])
        rel = rng.uniform(0.008, 0.03, ages.size)
        sig = rel * ages
        z, s = _radial_transform(list(ages), list(sig), True)
        mu, _se, _d = _central_age(z, s)
        fit = _mixture_best(z, s, kmax=3)
        x = np.array([1 / v for v in s])
        y = np.array([(a - mu) / b for a, b in zip(z, s)])
        xs = x.max() / (1.4 * max(2.5, np.abs(y).max()))
        X = x / xs
        R = 1.04 * np.hypot(X, y).max()

        def arc(zv, r=R):
            m = (zv - mu) * xs
            c = 1 / math.sqrt(1 + m * m)
            return r * c, r * m * c
        th0 = math.atan((min(z) - mu) * xs) - 0.08
        th1 = math.atan((max(z) - mu) * xs) + 0.08
        th = np.linspace(th0, th1, 200)
        fig, ax = plt.subplots(figsize=(5.8, 3.9))
        ax.fill_between([0, math.sqrt(R * R - 4)], -2, 2, color="#94a3b8",
                        alpha=0.25, lw=0)
        ax.plot(R * np.cos(th), R * np.sin(th), color=ink, lw=1.0)
        ax.plot([0, R], [0, 0], color=ink, lw=0.8)
        for t in (500, 600, 700, 800, 1000, 1200):
            zt = math.log(t)
            if not (th0 <= math.atan((zt - mu) * xs) <= th1):
                continue
            a0, b0 = arc(zt)
            a1, b1 = arc(zt, R * 1.03)
            ax.plot([a0, a1], [b0, b1], color=ink, lw=0.9)
            a2, b2 = arc(zt, R * 1.05)
            ax.text(a2, b2, f"{t}", fontsize=7.5, color=ink,
                    rotation=math.degrees(math.atan((zt - mu) * xs)),
                    rotation_mode="anchor", va="center")
        for mj in (fit["mu"] if fit else []):
            a0, b0 = arc(mj)
            ax.plot([0, a0], [0, b0], color="#7a3b8f", lw=1.2, ls=(0, (4, 2)))
        ax.plot(X, y, "o", ms=5, mfc=accent, mec="#222222", mew=0.4)
        ax.set_aspect("equal", adjustable="box")
        ax.set_xlim(0, R * 1.2)
        # Con mucha dispersión la banda es angosta y −2/0/+2 se enciman:
        # solo el 0 (lo mismo que hace la app).
        ax.set_yticks([-2, 0, 2] if np.abs(y).max() < 8 else [0])
        for sp in ("top", "right"):
            ax.spines[sp].set_visible(False)
        ax.spines["left"].set_bounds(-2, 2)
        ax.spines["bottom"].set_bounds(0, X.max())
        ax.set_xticks([v / xs for v in (0, 50, 100) if v <= x.max()])
        ax.set_xticklabels([f"{v}" for v in (0, 50, 100) if v <= x.max()])
        ax.set_xlabel("precision  t/σ", fontsize=9)
        ax.set_ylabel("standardized estimate", fontsize=9)
        ax.tick_params(labelsize=8)
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    P = "font-size:12.5pt; line-height:150%;"
    res = {
        f"s{n}_xy": _pdf_math_img(
            r"$x_i = \dfrac{1}{s_i}, \qquad y_i = \dfrac{z_i - z_0}{s_i},"
            r"\qquad z_i = \ln t_i,\; s_i = \sigma_i/t_i$", fontsize=15),
        f"s{n}_cen": _pdf_math_img(
            r"$w_i = \dfrac{1}{s_i^{2}+\sigma^{2}},\quad "
            r"\mu = \dfrac{\sum w_i z_i}{\sum w_i},\quad "
            r"\sigma^{2} \leftarrow \sigma^{2}\,"
            r"\dfrac{\sum w_i^{2}(z_i-\mu)^{2}}{\sum w_i}$", fontsize=15),
        f"s{n}_mix": _pdf_math_img(
            r"$w_{ij} \propto \dfrac{\pi_j}{s_i}\,"
            r"\phi\!\left(\dfrac{z_i-\mu_j}{s_i}\right),\quad "
            r"\mu_j = \dfrac{\sum_i w_{ij} z_i / s_i^{2}}"
            r"{\sum_i w_{ij} / s_i^{2}}$", fontsize=15),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Radial plot, central age
and mixtures</h2>
<p style="{P}">A KDE hides how precise each date is. The <b>radial plot</b>
(Galbraith 1988, 1990) shows every grain with its precision. Ages are taken on a log
scale, so that relative errors are comparable (a linear scale is available for a
narrow range), and each grain is placed at</p>
<p align="center"><img src="s{n}_xy" width="360"/></p>
<p style="{P}">where <i>z</i><sub>0</sub> is the reference age. The line from the
origin through a point has slope <i>z</i><sub>i</sub> − <i>z</i><sub>0</sub>, so it
meets the curved scale — the <b>arc</b> — exactly at that grain's age. Precise grains
plot far to the right and imprecise ones near the origin, and grains consistent with a
single age fall within the band |<i>y</i>| ≤ 2.</p>
<p style="{P}"><b>Central age.</b> The reference is the central age of a
random-effects model: each <i>z</i><sub>i</sub> scatters about μ with its own error
and an extra <b>dispersion</b> σ common to all (Galbraith &amp; Laslett 1993).
ZirClock finds the maximum-likelihood μ and σ by iterating</p>
<p align="center"><img src="s{n}_cen" width="420"/></p>
<p style="{P}">until σ² stops changing; the standard error of μ is
1/√Σ<i>w</i><sub>i</sub>. The dispersion is the scatter left over once the
analytical errors are accounted for: zero for a single population, and on the log
scale it reads directly as a percentage.</p>
<p style="{P}"><b>Age components.</b> A mixed sample is modelled as a finite
mixture of <i>k</i> discrete ages μ<sub>j</sub> with proportions π<sub>j</sub>
(Galbraith &amp; Green 1990), fitted by expectation–maximization:</p>
<p align="center"><img src="s{n}_mix" width="420"/></p>
<p style="{P}">with π<sub>j</sub> the mean of <i>w</i><sub>ij</sub> over the grains.
With <i>Auto</i>, <i>k</i> is the one with the lowest BIC = −2&nbsp;ln&nbsp;<i>L</i>
+ (2<i>k</i> − 1)&nbsp;ln&nbsp;<i>n</i>. Strongly overdispersed data drive BIC
towards the largest <i>k</i>, so a fixed number is then the safer choice.</p>
<p align="center"><img src="s{n}_fig" width="360"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> A
radial plot of 23 synthetic dates from two populations (600 and 1000 Ma). Each dashed
radius is a mixture component, read on the arc; the grey band is ±2 around the
central age.</p>
"""
    return html, res


def _theory_sec_halpin(n, accent, ink):
    """§ The Halpin oldest-coherent-cluster method (Halpin et al. 2011)."""
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        rng = np.random.default_rng(5)
        true = 1000.0
        cluster = [(rng.normal(true, 8), rng.uniform(7, 13)) for _ in range(5)]
        tail = [(true - rng.uniform(45, 230), rng.uniform(9, 18)) for _ in range(7)]
        data = sorted(cluster + tail, key=lambda p: -p[0])
        ages = np.array([d[0] for d in data])
        sig = np.array([d[1] for d in data])
        rank = np.arange(len(ages))
        t0, s0 = ages[0], sig[0]
        lo = t0 - 2.0 * s0
        incl = ages + 2.0 * sig >= lo
        halpin = float(ages[incl].mean())
        fig, ax = plt.subplots(figsize=(5.8, 3.4))
        ax.axhspan(lo, t0 + 2.0 * s0, color=accent, alpha=0.08, zorder=1)
        for i in range(len(ages)):
            c = accent if incl[i] else "#b8b8b8"
            ax.errorbar(rank[i], ages[i], yerr=2.0 * sig[i], fmt="o", ms=5,
                        color=c, ecolor=c, elinewidth=1.2, capsize=2, zorder=3)
        ax.axhline(halpin, color=accent, lw=1.4, zorder=2)
        ax.annotate(f"oldest coherent cluster → {halpin:.0f} Ma",
                    (0.5, halpin), textcoords="offset points", xytext=(4, 6),
                    fontsize=8, color=accent)
        ax.annotate("Pb-loss tail\n(excluded)", (len(ages) - 1.5, ages[-1]),
                    textcoords="offset points", xytext=(-4, -4), fontsize=8,
                    color="#8a8a8a", ha="right")
        ax.set_xlabel("grain (ranked by concordia age)", fontsize=9)
        ax.set_ylabel("age (Ma)", fontsize=9)
        ax.tick_params(labelsize=8)
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {
        f"s{n}_crit": _pdf_math_img(
            r"$a_i + k\,\sigma_i \;\geq\; t_0 - k\,\sigma_0$", fontsize=16),
        f"s{n}_fig": diagram(),
    }
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;The Halpin
oldest-coherent-cluster method</h2>
<p style="font-size:12.5pt; line-height:150%;">When grains from a single rock have
suffered <b>variable Pb loss</b>, they smear to younger ages along the concordia. A
plain weighted mean of all of them <b>underestimates</b> the true age, because the
disturbed young tail drags it down. Halpin et al. (2011) reasoned that the
<b>oldest</b> grains are the least disturbed, so the crystallization age is best
taken from the oldest <i>coherent</i> cluster.</p>
<p style="font-size:12.5pt; line-height:150%;">ZirClock anchors on the oldest grain
(concordia age t<sub>0</sub>, uncertainty σ<sub>0</sub>) and adds every grain whose
uncertainty interval overlaps the anchor's, i.e.</p>
<p align="center"><img src="s{n}_crit" width="220"/></p>
<p style="font-size:12.5pt; line-height:150%;">(default k&nbsp;=&nbsp;2). If the
resulting cluster reaches the minimum size (default 3), its weighted mean
(&sect;{n - 7}) is reported as the age and the younger tail is excluded:</p>
<p align="center"><img src="s{n}_fig" width="380"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> Grains
ranked by age. The oldest overlap within 2σ (blue, shaded window) and define the
age; the scattered younger grains (grey) are the Pb-loss tail.</p>
<p style="font-size:12.5pt; line-height:150%;">Because an old grain can also be an
<b>inherited xenocryst</b>, ZirClock can additionally require the cluster to be
coherent in Hf isotopes (εHf(t) within k·σ) and/or in fingerprint trace-element
ratios (robust median&nbsp;±&nbsp;k·MAD); grains that fail are removed and the anchor
re-chosen. These filters are optional diagnostics, off by default.</p>
"""
    return html, res


def _theory_sec_tectonic(n, accent, ink):
    """§ Tectonic discrimination from zircon trace elements (Grimes et al. 2015)."""
    import numpy as np
    import matplotlib.pyplot as plt

    def diagram():
        fig, ax = plt.subplots(figsize=(5.4, 4.0))
        (x1, y1), (x2, y2) = (0.0004, 0.02), (1.0, 10.0)
        m = (np.log10(y2) - np.log10(y1)) / (np.log10(x2) - np.log10(x1))
        b_up = np.log10(y1) - m * np.log10(x1)
        b_lo = b_up - 0.6
        xs = np.logspace(-2, 2, 80)
        ax.fill_between(xs, 10 ** (m * np.log10(xs) + b_lo),
                        10 ** (m * np.log10(xs) + b_up), color="#dadada", lw=0,
                        zorder=1)
        ax.plot(xs, 10 ** (m * np.log10(xs) + b_up), color="#555", lw=1.6, zorder=2)
        ax.plot(xs, 10 ** (m * np.log10(xs) + b_lo), color="#888", lw=1.0,
                ls="--", zorder=2)
        rng = np.random.default_rng(3)
        cx = 10 ** rng.uniform(-1.4, 0.2, 9)
        cy = 10 ** (m * np.log10(cx) + b_up + rng.uniform(0.35, 1.05, 9))
        ax.plot(cx, cy, "^", color="#7a3b8f", ms=5.5, label="continental / arc")
        mx = 10 ** rng.uniform(-1.0, 1.0, 9)
        my = 10 ** (m * np.log10(mx) + b_up - rng.uniform(0.05, 0.55, 9))
        ax.plot(mx, my, "o", color="#2a6a8a", ms=5, label="MOR / OIB (mantle)")
        ax.set_xscale("log"); ax.set_yscale("log")
        ax.set_xlim(0.02, 60); ax.set_ylim(0.02, 60)
        ax.set_xlabel("Nb/Yb", fontsize=9); ax.set_ylabel("U/Yb", fontsize=9)
        ax.tick_params(labelsize=8)
        ax.text(0.62, 0.12, "mantle-zircon array\n(MOR / OIB)",
                transform=ax.transAxes, fontsize=8, color="#3a3a3a",
                style="italic")
        ax.legend(fontsize=8, loc="upper left")
        fig.tight_layout()
        return _pdf_fig_to_qimage(fig)

    res = {f"s{n}_fig": diagram()}
    html = f"""
<h2 style="color:{accent}; font-size:16.5pt;">{n}&nbsp;&nbsp;Tectonic discrimination
from zircon chemistry</h2>
<p style="font-size:12.5pt; line-height:150%;">Because incompatible-element ratios
differ between magmas from different settings, the trace-element chemistry of zircon
can fingerprint its <b>tectono-magmatic environment</b>. Grimes et al. (2015) showed
that ratios of U, Nb, Sc and Yb separate <b>continental-arc</b>, <b>mid-ocean-ridge
(MOR)</b> and <b>ocean-island / plume (OIB)</b> zircon. ZirClock plots two of their
diagrams.</p>
<p style="font-size:12.5pt; line-height:150%;">On <b>U/Yb vs Nb/Yb</b>, mantle-derived
(MOR / OIB) zircon falls within the <b>mantle-zircon array</b> (grey band), whereas
continental and arc zircon — enriched in U relative to Yb — plots <b>above</b> it:</p>
<p align="center"><img src="s{n}_fig" width="360"/></p>
<p align="center" style="color:#6a8aaa; font-size:10pt;"><b>Figure {n}.1.</b> U/Yb vs
Nb/Yb after Grimes et al. (2015). The upper edge of the mantle array is a published
line; continental / arc grains (triangles) plot above it.</p>
<p style="font-size:12.5pt; line-height:150%;">The second diagram, <b>Sc/Yb vs
Nb/Yb</b>, splits the settings into a "T"-shaped arrangement of three fields
(continental arc above; MOR-type at lower Nb/Yb; OI-type / plume at higher Nb/Yb).
In ZirClock the discrimination fields are reproduced <b>clean-room</b> from the
published boundaries (the band widths were digitized from the original figures and
are adjustable), drawn beneath a high-zorder log grid so the graticule stays
readable.</p>
"""
    return html, res


# Registro de secciones del compendio (en orden). Se irán agregando.
_THEORY_SECTIONS = [
    _theory_sec_ellipses,
    _theory_sec_concordia,
    _theory_sec_discordance,
    _theory_sec_wmean,
    _theory_sec_discordia,
    _theory_sec_bestage,
    _theory_sec_hf,
    _theory_sec_ti,
    _theory_sec_ree,
    _theory_sec_kde,
    _theory_sec_radial,
    _theory_sec_halpin,
    _theory_sec_tectonic,
]


def _theory_build_document(accent, ink=_THEORY_INK):
    """Ensambla (html, {clave: QImage}) del compendio completo."""
    import datetime
    res = {}
    parts = [
        f"""<div style="font-family:'Helvetica','Arial',sans-serif; color:{ink};">
<h1 style="color:{accent}; font-size:22pt; margin-bottom:0;">ZirClock — Theory &amp;
methods</h1>
<p style="color:#6a8aaa; font-size:10pt; margin-top:2px;">The mathematics and
geometry behind each calculation and diagram · draft ·
{datetime.date.today().isoformat()}</p>
<hr/>"""]
    for i, fn in enumerate(_THEORY_SECTIONS, 1):
        h, r = fn(i, accent, ink)
        parts.append(h)
        res.update(r)
    parts.append(_theory_references_html(accent, ink))
    parts.append("</div>")
    return "\n".join(parts), res


def _theory_references_html(accent, ink):
    """Lista de referencias consolidada al pie del compendio. Reusa las citas
    del generador de Methods (_METHODS_REFS) para las compartidas + extras
    propias del teórico. Auto-compilada; el usuario verifica cada entrada."""
    extra = {
        "dickinson2009": "Dickinson, W.R., Gehrels, G.E. (2009) Use of U–Pb ages "
            "of detrital zircons to infer maximum depositional ages of strata: a "
            "test against a Colorado Plateau Mesozoic database. Earth and "
            "Planetary Science Letters 288, 115–125.",
        "grimes2015": "Grimes, C.B., Wooden, J.L., Cheadle, M.J., John, B.E. "
            "(2015) “Fingerprinting” tectono-magmatic provenance using "
            "trace elements in igneous zircon. Contributions to Mineralogy and "
            "Petrology 170, 46.",
        "silverman1986": "Silverman, B.W. (1986) Density Estimation for Statistics "
            "and Data Analysis. Chapman & Hall, London.",
        "vermeesch2012": "Vermeesch, P. (2012) On the visualisation of detrital age "
            "distributions. Chemical Geology 312–313, 190–194.",
        "vermeesch2018": "Vermeesch, P. (2018) IsoplotR: a free and open toolbox "
            "for geochronology. Geoscience Frontiers 9, 1479–1493.",
    }
    shared = ["blichert1997", "bouvier2008", "boynton1984", "crisp2023",
              "ferry2007", "galbraith1988", "galbraith1990",
              "galbraith1990b", "galbraith1993",
              "griffin2002", "halpin2011", "jaffey1971",
              "ludwig1998", "mcdsun1995", "soderlund2004", "spencer2016",
              "sunmcd1989", "vervoort2025", "york2004"]
    refs = sorted([_METHODS_REFS[k] for k in shared] + list(extra.values()))
    items = "".join(
        f'<p style="font-size:11pt; line-height:145%; margin:2px 0;">{r}</p>'
        for r in refs)
    return (f'<h2 style="color:{accent}; font-size:16.5pt;">References</h2>'
            f'<p style="color:#6a8aaa; font-size:10pt;">Auto-compiled from the '
            f'works cited above — verify each entry against the original source '
            f'before use.</p>{items}')


# ══════════════════════════════════════════════════════════════════════════
# §Ola8 — Instructivo / User guide en PDF ("User guide")
# ──────────────────────────────────────────────────────────────────────────
# Doc 2: guía ilustrada del flujo de trabajo. Screenshots REALES capturados en
# desarrollo (grab() headless con plataforma cocoa) → PNGs pre-capturados en
# `guide_assets/` (empaquetados con la app); las ANOTACIONES (llamadas
# numeradas, flechas) se dibujan al vuelo con matplotlib sobre el asset crudo.
# Reusa el pipeline del teórico (_pdf_fig_to_qimage, QTextDocument→QPdfWriter).
# Cada sección = función `(_n, accent, ink)->(html, {clave: QImage})`.
_GUIDE_ASSETS_DIR = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "guide_assets")


def _guide_asset_qimage(name, annotate=None, width_in=9.0, dpi=165):
    """Carga guide_assets/{name}.png y, si se da `annotate(ax, w, h)`, dibuja
    encima (llamadas/flechas) con matplotlib. Devuelve QImage embebible."""
    import matplotlib.image as mpimg
    import matplotlib.pyplot as plt
    img = mpimg.imread(os.path.join(_GUIDE_ASSETS_DIR, name + ".png"))
    h, w = img.shape[0], img.shape[1]
    fig, ax = plt.subplots(figsize=(width_in, width_in * h / w))
    ax.imshow(img); ax.axis("off")
    fig.subplots_adjust(left=0, right=1, top=1, bottom=0)
    if annotate is not None:
        annotate(ax, w, h)
    return _pdf_fig_to_qimage(fig, dpi=dpi)


def _guide_callout(ax, w, h, fx, fy, num, accent):
    """Círculo numerado (llamada) en la fracción (fx, fy) de la imagen."""
    from matplotlib.patches import Circle
    cx, cy = fx * w, fy * h
    ax.add_patch(Circle((cx, cy), 0.018 * w, facecolor=accent,
                        edgecolor="white", lw=2, zorder=5))
    ax.text(cx, cy, num, color="white", fontsize=12, fontweight="bold",
            ha="center", va="center", zorder=6)


def _guide_workflow_flow(accent, ink):
    import matplotlib.pyplot as plt
    from matplotlib.patches import FancyBboxPatch, FancyArrowPatch
    # 2026-09-25: sin botón Calculate — los resultados se recalculan solos.
    # 2026-09-30: sin paso "Variables" — Tabla 1 nace completa.
    steps = ["New\nproject", "Import or\nenter data", "Results\n(automatic)",
             "Visualize", "Save &\nexport"]
    fig, ax = plt.subplots(figsize=(7.2, 1.15))
    ax.set_xlim(0, len(steps)); ax.set_ylim(0, 1); ax.axis("off")
    for i, s in enumerate(steps):
        ax.add_patch(FancyBboxPatch((i + 0.08, 0.2), 0.84, 0.6,
                     boxstyle="round,pad=0.02,rounding_size=0.1",
                     facecolor="#eef3fe", edgecolor=accent, lw=1.3))
        ax.text(i + 0.5, 0.5, s, ha="center", va="center", fontsize=8.5,
                color=ink, fontweight="bold")
        if i < len(steps) - 1:
            ax.add_patch(FancyArrowPatch((i + 0.93, 0.5), (i + 1.07, 0.5),
                         arrowstyle="-|>", mutation_scale=11, color=accent, lw=1.4))
    return _pdf_fig_to_qimage(fig, dpi=200)


