def _ri_results(p, ink, pal):
    """Resultados (2026-09-27, pedido de Guillermo): el recuadro negro de la
    ventana de resultados con una Σ blanca — sumas, medias ponderadas, MSWD.
    La concordia con su elipse pasó al botón Plot it!, que es donde se dibuja.
    El cuadro toma la TINTA: negro de serie, ámbar cuando Data QA avisa."""
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(ink))
    p.drawRoundedRect(QRectF(10, 10, 80, 80), 17, 17)
    pen = QPen(QColor("#ffffff"))
    pen.setWidthF(8.5)
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    pen.setJoinStyle(Qt.PenJoinStyle.MiterJoin)
    p.setPen(pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    sigma = QPainterPath()
    sigma.moveTo(69, 33)
    sigma.lineTo(69, 28)
    sigma.lineTo(32, 28)
    sigma.lineTo(51, 50)
    sigma.lineTo(32, 72)
    sigma.lineTo(69, 72)
    sigma.lineTo(69, 67)
    p.drawPath(sigma)


# ── Ola "E" (2026-09-23): iconos de la barra de Panel 5, en el MISMO idioma
# que los del riel (pedido de Guillermo: "¿podemos diseñar un aspecto para
# estos botones que sea congruente con los botones del menú vertical?").
# Mismo trazo (tinta negra, 6-7 px sobre 100) y el acento azul como único
# color. Sustituyen a los emoji (🔓📏⧉) — que traen su propio color y no se
# pueden teñir — y a los PNG de matplotlib (Home/Pan/Zoom).
def _pi_lock(p, ink, pal, closed):
    _ri_pen(p, ink, 7)
    shackle = QPainterPath()
    if closed:
        shackle.moveTo(32, 46)
        shackle.lineTo(32, 32)
        shackle.arcTo(QRectF(32, 14, 36, 36), 180, -180)
        shackle.lineTo(68, 46)
    else:
        shackle.moveTo(56, 46)
        shackle.lineTo(56, 26)
        shackle.arcTo(QRectF(56, 8, 32, 36), 180, -180)
        shackle.lineTo(88, 34)
    p.drawPath(shackle)
    p.setBrush(QColor(pal["cool"]) if closed else Qt.BrushStyle.NoBrush)
    p.drawRoundedRect(QRectF(20, 46, 60, 42), 8, 8)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#ffffff") if closed else QColor(ink))
    p.drawEllipse(QRectF(44, 60, 12, 12))


def _pi_lock_closed(p, ink, pal):
    _pi_lock(p, ink, pal, True)


def _pi_lock_open(p, ink, pal):
    _pi_lock(p, ink, pal, False)


