    p.drawLine(QPointF(14, 50), QPointF(86, 50))
    for (x, y, ax_, ay) in ((50, 12, 1, 0), (50, 88, 1, 0),
                             (12, 50, 0, 1), (88, 50, 0, 1)):
        path = QPainterPath()
        dx, dy = (0, 1) if y == 12 else (0, -1) if y == 88 else \
            (1, 0) if x == 12 else (-1, 0)
        path.moveTo(x + dx * 14 - ax_ * 12 + ay * 0, y + dy * 14 - ay * 12)
        path.lineTo(x, y)
        path.lineTo(x + dx * 14 + ax_ * 12, y + dy * 14 + ay * 12)
        p.drawPath(path)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(pal["cool"]))
    p.drawEllipse(QRectF(41, 41, 18, 18))


