def _ti_gear(p, ink, pal):
    """Settings: una tuerca de 8 dientes trapezoidales, cuerpo en el tono
    claro del acento y el eje hueco (pedido de Guillermo, 2026-09-23)."""
    import math
    cx = cy = 50.0
    r_out, r_in, n = 44.0, 33.0, 8
    path = QPainterPath()
    for i in range(n):
        a0 = 2 * math.pi * i / n
        half = math.pi / n
        pts = ((r_in, a0 - half * 0.95), (r_out, a0 - half * 0.45),
               (r_out, a0 + half * 0.45), (r_in, a0 + half * 0.95))
        for j, (rr, aa) in enumerate(pts):
            x, y = cx + rr * math.cos(aa), cy + rr * math.sin(aa)
            if i == 0 and j == 0:
                path.moveTo(x, y)
            else:
                path.lineTo(x, y)
    path.closeSubpath()
    hole = QPainterPath()
    hole.addEllipse(QRectF(cx - 13, cy - 13, 26, 26))
    _ri_pen(p, ink, 6)
    p.setBrush(QColor(pal["cool"]).lighter(165))
    p.drawPath(path.subtracted(hole))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.drawEllipse(QRectF(cx - 13, cy - 13, 26, 26))


