def _rail_icon_pixmap(key, px, ink=None, dpr=2.0, alpha=1.0):
    """QPixmap del icono `key` a `px` px lógicos. `ink` permite teñirlo (lo
    usa el aviso ámbar de Data QA); `alpha` < 1 lo atenúa (un dominio de
    Panel 4 que no está activo)."""
    painter_fn = _RAIL_ICON_PAINTERS.get(key)
    pm = QPixmap(max(1, int(px * dpr)), max(1, int(px * dpr)))
    pm.setDevicePixelRatio(dpr)
    pm.fill(Qt.GlobalColor.transparent)
    if painter_fn is None:
        return pm
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    # ⚠ con devicePixelRatio el QPainter trabaja en px LÓGICOS: escalar por
    # px*dpr pinta al doble y recorta el icono (cazado en el mockup).
    p.setTransform(QTransform().scale(px / 100.0, px / 100.0))
    p.setOpacity(alpha)
    painter_fn(p, ink or THEME["text"], _rail_palette())
    p.end()
    return pm


class _SideRail(QWidget):
    """§Ola12 — riel vertical de la izquierda: guarda los paneles y deja
    siempre a mano los botones de trabajo.

    Nace de dos peticiones de Guillermo (2026-09-04): poder colapsar los
    paneles para trabajar solo con los gráficos SIN perder la barra de
    cálculos (U-Pb, Trace+REE, Hf, Ti, Calculate), y poder ir guardando cada
    panel uno por uno. Con todo guardado, la ventana queda: riel angosto +
    área de gráficos.

    Tres bloques, de arriba abajo:
      1. un botón por PANEL (marcado = visible),
      2. los botones de TRABAJO, que nunca se van,
      3. el recuadro negro de resultados.

    Iconos DIBUJADOS (Ola 15, `_rail_icon_pixmap`): los glifos de fuente que
    había antes se veían pobres y a 15 px eran una mancha. A ancho normal solo
    se ve el icono (el nombre va en el tooltip); al ENSANCHAR el riel aparece
    además el rótulo debajo — decisión de Guillermo (2026-09-20), que así no
    pierde de vista cuál es U-Pb y cuál Hf."""

    WIDTH = 42          # ancho de arranque
    # Se puede ensanchar un poco, no el triple: Guillermo probó los 120 px y
    # se arrepintió ("no es necesario y antiestético", 2026-09-06). Lo justo
    # para ganar legibilidad en pantallas grandes.
    MAX_WIDTH = 64

    def __init__(self, mw):
        super().__init__(mw)
        self.mw = mw
        self.setObjectName("sideRail")
        # ⚠ Sin WA_StyledBackground, un QWidget PLANO ignora el
        # `background-color` de su hoja de estilo (solo pinta bordes y texto).
        # Antes no se notaba porque el riel usaba el mismo gris del fondo; al
        # pasarlo a tarjeta blanca, la regla simplemente no se veía.
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        # Ensanchable arrastrando su asa (queda dentro de un _GripSplitter):
        # los límites los pone el propio widget, así el splitter no lo deja
        # colapsar ni crecer de más.
        self.setMinimumWidth(self.WIDTH)
        self.setMaximumWidth(self.MAX_WIDTH)
        self.resize(self.WIDTH, self.height())
        self._btn_size = (self.WIDTH, 28, False)
        self._icon_px = 16          # Ola 15: tamaño del icono dibujado
        self._alerts = set()        # botones en ámbar (aviso de Data QA)
        # 2026-09-30: dominios APAGADOS (ícono atenuado; sigue abriendo su
        # diálogo, que es donde se encienden) y el tooltip base de cada uno.
        self._dimmed = set()
        self._tips = {}
        self._dirty = False         # 2026-09-25: punto en Save = sin guardar
        self.setStyleSheet(self._qss())
        self._build_ui(mw)

    def _qss(self, icon_px=15, text_px=10):
        return f"""
            /* §Ola12c — el riel era una banda gris que se fundía con el
               fondo ("se ve muy… gris", Guillermo). Ahora es una TARJETA
               blanca con borde y esquinas redondeadas, el mismo lenguaje que
               los paneles (§31): se lee como una pieza de la interfaz y, de
               paso, el tinte azul del botón activo resalta mucho más sobre
               blanco que sobre gris. */
            #sideRail {{ background-color:{THEME['surface']};
                         border:1px solid {THEME['border']};
                         border-radius:10px; }}
            #railRule {{ background-color:transparent; }}
            /* padding:0 es obligatorio: con el padding heredado del botón
               global, el icono y el rótulo salían RECORTADOS a un par de
               píxeles dentro del botón — medido con grab, no supuesto. */
            /* §Ola13d: la tinta va en NEGRO, no en el gris secundario — a
               34 px un icono gris sobre tarjeta blanca se lee apagado
               (reporte de Guillermo). */
            QToolButton#railBtn {{
                background-color:transparent; color:{THEME['text']};
                border:none; border-radius:7px;
                padding:0px; margin:0px; }}
            QToolButton#railBtn:hover {{
                background-color:{THEME['surface_hover']};
                color:{THEME['text']}; }}
            /* Activo: el accent_tint del tema casi no se percibía en un
               botón tan chico (lo reportó Guillermo) → tinte bastante más
               marcado y el glifo en negrita. */
            QToolButton#railBtn:checked {{
                background-color:rgba(37, 99, 235, 0.22);
                color:{THEME['accent']}; font-weight:700; }}
            QToolButton#railBtn:checked:hover {{
                background-color:rgba(37, 99, 235, 0.30); }}
            QToolButton#railBtn:disabled {{ color:{THEME['text_disabled']}; }}
            QToolButton#railBtn[alert="true"] {{ color:#b5651d; }}
            /* Latido al recibir la ventana de resultados. */
            QToolButton#railBtn[pulse="true"] {{
                background-color:rgba(37, 99, 235, 0.45);
                color:{THEME['accent_press']}; }}
            /* El rótulo bajo el icono, cuando el riel está ensanchado. OJO
               §3: poner la hoja en el botón (setStyleSheet) en vez de aquí lo
               saca de la regla #railBtn y le devuelve el padding 6px 14px del
               botón global → el rótulo se recorta. */
            QToolButton#railBtn {{ font-size:{text_px}px; font-weight:600; }}
        """

    def _build_ui(self, mw):
        lay = QVBoxLayout(self)
        # Aire: los botones iban demasiado apretados contra el borde superior
        # (reporte de Guillermo). Más margen arriba y más separación entre
        # ellos — un riel de 13 botones necesita respirar.
        # 2026-09-26 (Guillermo: "algo separados"): más compacto — 14→10 de
        # margen y 8→4 entre botones (6 con rótulos, ver resizeEvent: ahí el
        # hueco entre botones debe seguir siendo MAYOR que el que hay entre
        # un icono y su rótulo, o el rótulo parecería del icono de abajo).
        lay.setContentsMargins(5, 10, 5, 10)
        lay.setSpacing(4)
        self._lay = lay
        self._buttons = {}

        def rule():
            # Separador con aire propio: una línea pegada a los botones se lee
            # como "otro botón raro" en vez de como una división.
            box = QWidget()
            # ⚠ El contenedor pintaba el GRIS de la app (#F5F5F7) sobre la
            # tarjeta blanca del riel: la regla #sideRail sólo alcanza al riel,
            # y sus hijos caen en la hoja global. Se veían tres bandas grises
            # donde debía haber tres líneas finas (cazado con grab, Ola 15).
            box.setObjectName("railRule")
            bl = QVBoxLayout(box)
            bl.setContentsMargins(9, 3, 9, 3)   # línea corta = división discreta
            bl.setSpacing(0)
            ln = QFrame()
            ln.setFrameShape(QFrame.Shape.HLine)
            # La línea se PINTA con su fondo: el `color` de un QFrame:HLine no
            # la dibuja bajo una hoja de estilo, y con el contenedor ya
            # transparente el separador desaparecía del todo.
            ln.setStyleSheet(
                f"background-color:{THEME['border']}; border:none;"
                " min-height:1px; max-height:1px;")
            bl.addWidget(ln)
            lay.addWidget(box)

        def button(key, label, tip, slot, checkable=False):
            b = QToolButton()
            b.setObjectName("railBtn")
            # El rótulo sólo se ve con el riel ensanchado; el icono siempre.
            b.setText(label)
            b.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonIconOnly)
            # ⚠ NADA de setFixedSize: un layout lleno de widgets de ancho fijo
            # le impone al contenedor un maximumWidth igual a esa suma, y el
            # riel se negaba a ensancharse (setSizes(100) devolvía 40). Alto
            # fijo + ancho expansible.
            b.setFixedHeight(28)
            # ⚠ Ola 15: horizontal IGNORED, no Expanding. Un QToolButton con
            # texto pide de ancho lo que mide su rótulo ("Calculate"), y ese
            # mínimo se lo impone al riel: con Expanding, el riel nacía a 64 px
            # y le robaba el sitio a la columna de al lado (cazado por
            # tests/test_side_rail.py). Ignored = el botón se conforma con el
            # ancho que le den; el mínimo del riel lo pone el propio riel.
            b.setSizePolicy(QSizePolicy.Policy.Ignored,
                            QSizePolicy.Policy.Fixed)
            b.setCheckable(checkable)
            b.setToolTip(tip)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            # §85: estos botones actúan sobre la muestra/selección viva, así
            # que el filtro global de "clic fuera → deseleccionar" no debe
            # limpiarla antes de que llegue el clicked (que viene en el
            # release).
            b.setProperty("keepsSampleSelection", True)
            b.clicked.connect(slot)
            lay.addWidget(b)
            self._buttons[key] = b
            self._apply_icon(key)
            return b

        # 1 — paneles (marcado = a la vista)
        # §Ola12c — UN botón por COLUMNA, no cuatro por panel. Con cuatro,
        # el riel y las asas de los splitters competían por lo mismo y el
        # resultado era ambiguo (un panel "traído" que seguía sin verse porque
        # el asa lo tenía en cero). Ahora cada mecanismo tiene su trabajo: el
        # asa REPARTE, el riel HACE DESAPARECER.
        # Glifos elegidos MIRANDO el render, no de catálogo (§37): a 15 px el
        # alambique ⚗ y la rejilla fina ▤ quedan en una mancha ilegible.
        for key, label, name in (
                ("admin", "Projects", "Projects and samples"),
                ("numeric", "Tables", "Data entry and calculations")):
            button(key, label, f"Show / hide {name}",
                   lambda _c=False, k=key: mw._toggle_panel_visible(k),
                   checkable=True)
        rule()

        # 2 — trabajo (SIEMPRE presentes, aunque no haya ningún panel abierto:
        #     ese es el punto de todo el riel)
        # 2026-09-25 (pedido de Guillermo): guardar también desde el riel, en
        # el mismo grupo que Import y Export — y Save primero, que es lo que
        # más se usa. Un punto en su icono = hay cambios sin guardar (antes
        # ese aviso vivía sólo en el '*' del título de la ventana).
        button("save", "Save", "Save (⌘S / Ctrl+S)",
               lambda _c=False: mw._save_project(save_as=False))
        button("save_as", "Save As", "Save As… (⇧⌘S / Ctrl+Shift+S)",
               lambda _c=False: mw._save_project(save_as=True))
        button("import", "Import", "Import from Excel", mw._import_xlsx)
        button("export", "Export", "Export…", mw._open_export_dialog)
        rule()
        # Ola 16: estos son ventanas FLOTANTES, así que su botón abre o
        # cierra (marcado = abierta), igual que el de la pizarra de resultados.
        # 2026-09-30 (fusión Input | Calculations): U-Pb, Trace y Hf abren UN
        # diálogo con dos pestañas — las columnas de entrada de Tabla 1 y los
        # ajustes de cálculo —; Textures (sólo entrada) ganó botón propio,
        # junto a Sets: las dos cosas describen o agrupan granos.
        for _k, _txt, _tip, _slot in (
                ("upb", "U-Pb", "U-Pb calculation settings",
                 mw._open_upb_dialog),
                ("trace", "Trace", "Trace elements and REE — calculation "
                 "settings", mw._open_trace_ree_dialog),
                ("hf", "Hf", "Hf isotopes — calculation settings",
                 mw._open_hf_dialog),
                ("ti", "Ti", "Ti-in-zircon thermometry settings",
                 mw._open_ti_dialog),
                ("textures", "Textures", "Textures — the positions (core / "
                 "rim) and texture types Table 1 offers",
                 mw._open_textures_dialog),
                ("sets", "Sets", "Manage sets", mw.manage_sets)):
            self._tips[_k] = _tip
            button(_k, _txt, f"{_tip}\nClick again to close.", _tip and
                   (lambda _c=False, k=_k, f=_slot: mw._toggle_p4_dialog(k, f)),
                   checkable=True)
        rule()

        # 3 — el recuadro negro de resultados
        button("results", "Results",
               "Results: weighted mean, Ti thermometry and Data QA",
               mw._toggle_results_window, checkable=True)
        lay.addStretch()

    def _apply_icon(self, key):
        """(Re)dibuja el icono de un botón al tamaño actual. La tinta cambia a
        ámbar cuando ese botón está avisando (Data QA)."""
        b = self._buttons.get(key)
        if b is None:
            return
        _ink = "#b5651d" if key in self._alerts else THEME["text"]
        pm = _rail_icon_pixmap(key, self._icon_px, _ink,
                               alpha=0.35 if key in self._dimmed else 1.0)
        if key == "save" and self._dirty:
            # Punto de acento en la esquina, con aro blanco para que se
            # despegue del disquete.
            p = QPainter(pm)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            r = self._icon_px * 0.20
            c = QPointF(self._icon_px - r - 0.5, r + 0.5)
            p.setPen(QPen(QColor(THEME["surface"]), max(1.0, r * 0.45)))
            p.setBrush(QColor(THEME["accent"]))
            p.drawEllipse(c, r, r)
            p.end()
        b.setIcon(QIcon(pm))
        b.setIconSize(QSize(self._icon_px, self._icon_px))
        if key == "save":
            b.setToolTip("Save (⌘S / Ctrl+S)"
                         + (" — there are unsaved changes" if self._dirty
                            else ""))

    def set_dirty(self, dirty):
        """Enciende/apaga el punto de 'cambios sin guardar' del botón Save."""
        dirty = bool(dirty)
        if dirty != self._dirty:
            self._dirty = dirty
            self._apply_icon("save")

    def resizeEvent(self, ev):
        """Al ensanchar el riel, los iconos crecen con él y aparece el rótulo
        debajo (pedido de Guillermo: "que se pueda extender, haciendo más
        grande su simbología", y Ola 15: "icono, y rótulo al ensanchar").

        Con rótulo los botones son más altos, así que se aprieta el aire entre
        ellos: son doce y tienen que seguir cabiendo en la pantalla de una
        laptop (el riel no tiene scroll)."""
        super().resizeEvent(ev)
        w = self.width()
        k = max(1.0, min(1.7, w / float(self.WIDTH)))
        show_text = w >= 56
        icon_px = int(round(16 * k))
        if show_text:
            icon_px = min(icon_px, 20)
        text_px = 9
        bh = icon_px + 10 + (text_px + 4 if show_text else 0)
        self._lay.setSpacing(6 if show_text else 4)
        if (w, bh, show_text) == self._btn_size:
            return
        self._btn_size = (w, bh, show_text)
        self._icon_px = icon_px
        _style = (Qt.ToolButtonStyle.ToolButtonTextUnderIcon if show_text
                  else Qt.ToolButtonStyle.ToolButtonIconOnly)
        for _key, b in self._buttons.items():
            b.setFixedHeight(bh)
            b.setToolButtonStyle(_style)
            self._apply_icon(_key)
        _lay = self.layout()
        if _lay is not None:
            _lay.setSpacing(4 if show_text else 8)
            _m = 8 if show_text else 14
            _lay.setContentsMargins(5, _m, 5, _m)
        # El font-size del QSS gana sobre setFont(), así que se re-emite la
        # hoja (una sola llamada, barata).
        self.setStyleSheet(self._qss(icon_px=icon_px, text_px=text_px))

    _OFF_HINTS = {
        "textures": "Off — turn Textures on in this window and press Apply.",
    }

    def set_dimmed(self, key, on):
        """Dominio apagado: ícono atenuado y el tooltip dice dónde se
        enciende. El botón sigue activo (la pestaña Input es donde se
        enciende)."""
        b = self._buttons.get(key)
        if b is None:
            return
        on = bool(on)
        if (key in self._dimmed) == on and b.toolTip():
            return
        if on:
            self._dimmed.add(key)
        else:
            self._dimmed.discard(key)
        self._apply_icon(key)
        tip = self._tips.get(key, "")
        if on:
            tip += "\n" + self._OFF_HINTS.get(
                key, "Off — turn it on in its Input tab and press Apply.")
        b.setToolTip(tip + "\nClick again to close.")

    def set_checked(self, key, on):
        b = self._buttons.get(key)
        if b is not None and b.isChecked() != bool(on):
            b.blockSignals(True)
            b.setChecked(bool(on))
            b.blockSignals(False)

    def set_alert(self, key, on):
        """Enciende un botón en ámbar (lo usa Data QA cuando hay avisos y el
        recuadro está guardado — decisión de Guillermo: guardado se queda
        guardado, pero avisa)."""
        b = self._buttons.get(key)
        if b is None:
            return
        b.setProperty("alert", "true" if on else "false")
        b.style().unpolish(b)
        b.style().polish(b)
        # Ola 15: con iconos dibujados, el color del QSS ya no tiñe nada —
        # el aviso se pinta en el propio icono.
        if on:
            self._alerts.add(key)
        else:
            self._alerts.discard(key)
        self._apply_icon(key)

    def button(self, key):
        return self._buttons.get(key)


class _P5ScrollStrip(QWidget):
    """Barra de acciones de Panel 5 con DESPLAZAMIENTO LATERAL (2026-09-24).

    Pedido de Guillermo: al angostar la ventana, la barra (Plot it! ·
    Settings · 🔒 📏 ⧉ · Reset view · Drag · Zoom · coordenadas) debe
    desplazarse de lado con flechas ◀ ▶, como la banda de pestañas de
    diagramas (QTabBar), en vez de envolverse en varios renglones — decisión
    que revierte la del §90 (punto 8) SOLO para Panel 5; las barras de Tabla 1
    y Tabla 2 siguen envolviéndose.

    Las flechas solo aparecen cuando algo no cabe. La rueda y el trackpad
    también desplazan (el gesto vertical se traduce a horizontal, que es el
    único eje que hay). `layout()` de la franja es el QHBoxLayout interior,
    así que `addWidget` funciona igual que en la barra vieja (lo usa el
    reintegro del ⧉ para devolver la toolbar)."""

    STEP = 90

    def __init__(self, parent=None):
        super().__init__(parent)
        outer = QHBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(2)

        def _arrow(kind):
            b = QToolButton()
            b.setArrowType(kind)
            b.setAutoRaise(True)
            b.setAutoRepeat(True)
            b.setFixedSize(18, 26)
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            b.hide()
            return b

        self._left = _arrow(Qt.ArrowType.LeftArrow)
        self._right = _arrow(Qt.ArrowType.RightArrow)
        class _HintScroll(QScrollArea):
            # Pide EXACTAMENTE el ancho de sus botones: si caben, no se
            # desplaza y las coordenadas se quedan con lo que sobra.
            def sizeHint(self_):
                w = self_.widget()
                if w is None:
                    return super().sizeHint()
                sh = w.sizeHint()
                return QSize(sh.width() + 2, sh.height())

            def minimumSizeHint(self_):
                return QSize(40, super().minimumSizeHint().height())

        self._scroll = _HintScroll()
        self._scroll.setSizePolicy(QSizePolicy.Policy.Preferred,
                                   QSizePolicy.Policy.Fixed)
        self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._scroll.setWidgetResizable(True)
        self._scroll.setHorizontalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._scroll.setVerticalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._scroll.setObjectName("p5StripScroll")
        self._scroll.setStyleSheet(
            "#p5StripScroll { background: transparent; }")
        self._scroll.viewport().setAutoFillBackground(False)
        self._inner = QWidget()
        self._inner.setObjectName("p5StripInner")
        self._inner.setStyleSheet("#p5StripInner { background: transparent; }")
        self._row = QHBoxLayout(self._inner)
        self._row.setContentsMargins(0, 0, 0, 0)
        self._row.setSpacing(6)
        self._row.setAlignment(Qt.AlignmentFlag.AlignLeft
                               | Qt.AlignmentFlag.AlignVCenter)
        self._scroll.setWidget(self._inner)
        outer.addWidget(self._left)
        outer.addWidget(self._scroll)
        outer.addWidget(self._right)
        self._outer = outer

        hb = self._scroll.horizontalScrollBar()
        self._left.clicked.connect(
            lambda: hb.setValue(hb.value() - self.STEP))
        self._right.clicked.connect(
            lambda: hb.setValue(hb.value() + self.STEP))
        hb.rangeChanged.connect(lambda *_a: self._sync())
        hb.valueChanged.connect(lambda *_a: self._sync())
        self._scroll.viewport().installEventFilter(self)
        # Si un botón se va o vuelve (la toolbar viaja con el ⧉), recalcular
        # el ancho natural — si no, quedaría un hueco desplazable.
        self._inner.installEventFilter(self)
        self.setSizePolicy(QSizePolicy.Policy.Preferred,
                           QSizePolicy.Policy.Fixed)

    def row(self):
        """El QHBoxLayout donde viven los botones."""
        return self._row

    def addWidget(self, w, *a, **k):
        # Al cambiar de padre Qt deja el widget oculto hasta un evento
        # posterior, y un oculto no cuenta para el ancho: se muestra ya,
        # salvo que alguien lo haya ocultado A PROPÓSITO.
        _explicit_hidden = (w.isHidden() and w.testAttribute(
            Qt.WidgetAttribute.WA_WState_ExplicitShowHide))
        # 2026-09-27: si hay un botón "de cola" (Compose figure), lo que se
        # añade después va ANTES de él — la toolbar de matplotlib vuelve aquí
        # al reintegrar un ⧉ y no debe quedar detrás de Compose.
        tail = getattr(self, "_tail", None)
        ti = self._row.indexOf(tail) if tail is not None else -1
        if ti >= 0 and w is not tail:
            self._row.insertWidget(ti, w, *a, **k)
        else:
            self._row.addWidget(w, *a, **k)
        if not _explicit_hidden:
            w.show()
        self._fit_height()

    def addSpacing(self, n):
        self._row.addSpacing(int(n))

    def set_leading(self, w):
        """Widget FIJO a la izquierda, fuera del área que se desplaza (el
        título "Visualization", 2026-09-27): el panel se reconoce aunque la
        barra esté desplazada."""
        w.setSizePolicy(QSizePolicy.Policy.Fixed,
                        QSizePolicy.Policy.Preferred)
        self._outer.insertWidget(0, w)
        self._outer.insertSpacing(1, 10)

    def set_tail(self, w):
        """Último botón de la fila desplazable (Compose figure): queda al
        final aunque después se añadan otros (ver `addWidget`)."""
        self._tail = None
        self.addWidget(w)
        self._tail = w

    def set_trailing(self, w):
        """Widget FIJO a la derecha, fuera del área que se desplaza (las
        coordenadas X/Y): ocupa el sitio que sobre y se encoge a nada cuando
        no hay — dentro del área, al desplazarse al final, solo se veía su
        hueco en blanco."""
        # Ignored + stretch: su ancho de texto no cuenta; solo recibe el
        # espacio que SOBRA a los botones (que van con stretch 0).
        # 2026-09-27: con el título "Visualization" fijo a la izquierda, en
        # una ventana angosta ya no sobraba nada y las coordenadas quedaban en
        # 0 px — justo lo que la Ola "E" pidió evitar ("se recortan pero no
        # desaparecen"). Un mínimo de 90 px: en lo angosto cede la franja de
        # botones, que para eso tiene sus flechas.
        w.setSizePolicy(QSizePolicy.Policy.Ignored,
                        QSizePolicy.Policy.Preferred)
        w.setMinimumWidth(90)
        self._outer.addWidget(w, 1)

    def _fit_height(self):
        sh = self._inner.sizeHint()
        # El contenido NO se comprime: Qt encogería los botones (y la toolbar
        # de matplotlib escondería sus iconos tras un chevron) antes de
        # ofrecer desplazamiento. Con su ancho natural como mínimo, desplaza.
        self._inner.setMinimumWidth(sh.width())
        self._scroll.setFixedHeight(max(26, sh.height()))

    def _sync(self):
        hb = self._scroll.horizontalScrollBar()
        over = hb.maximum() > 0
        if self._left.isHidden() == over:
            self._left.setVisible(over)
            self._right.setVisible(over)
            # Recolocar en el SIGUIENTE ciclo: esto se dispara desde
            # rangeChanged, a media colocación de la propia franja, y un
            # activate() aquí reentraba y dejaba la flecha derecha con su
            # geometría vieja (fuera del borde).
            QTimer.singleShot(0, self._relayout)
        self._left.setEnabled(over and hb.value() > hb.minimum())
        self._right.setEnabled(over and hb.value() < hb.maximum())

    def _refit(self):
        try:
            self._inner.setMinimumWidth(0)       # que sizeHint no lo arrastre
            self._fit_height()
        except RuntimeError:
            pass

    def _relayout(self):
        try:
            self._outer.invalidate()
            self._outer.activate()
        except RuntimeError:
            pass              # la franja ya se destruyó (cierre de la app)

    def eventFilter(self, obj, ev):
        if obj is self._inner and ev.type() in (QEvent.Type.ChildRemoved,
                                                QEvent.Type.ChildAdded):
            QTimer.singleShot(0, self._refit)
            return False
        if ev.type() == QEvent.Type.Wheel:
            hb = self._scroll.horizontalScrollBar()
            if hb.maximum() > 0:
                d = ev.angleDelta()
                step = d.x() if abs(d.x()) > abs(d.y()) else d.y()
                if step:
                    hb.setValue(hb.value() - step)
                    return True
        return False

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._sync()


class _FlowLayout(QLayout):
    """§90 — layout de FLUJO: coloca los widgets en fila y, cuando no caben,
    sigue en el renglón de abajo.

    Por qué: las barras de acción de Panel 5 (X: … Y: … · Plot it! · Settings ·
    🔒 📏 ⧉) eran QHBoxLayout. Un QHBoxLayout comprime a sus hijos hasta el
    mínimo y, pasado ese punto, **los desborda encima unos de otros** — que es
    justo lo que ve Guillermo al angostar el panel (2026-09-04). Las pestañas y
    la barra de matplotlib no sufren eso porque son QTabBar/QToolBar, que traen
    scroll y overflow de fábrica. Decisión suya: envolver a dos renglones (nada
    se esconde) en vez de hacer scroll horizontal.

    Sustituye a QHBoxLayout sin tocar los call sites: acepta `addSpacing` (un
    hueco fijo que viaja con el flujo) y `addStretch` (no-op: en un flujo la
    alineación ya es a la izquierda y un stretch impediría el salto de línea).
    """

    def __init__(self, parent=None, spacing=6):
        super().__init__(parent)
        self._items = []
        self._space = spacing
        self.setContentsMargins(0, 0, 0, 0)

    # — API que usan las barras (compatible con QHBoxLayout) —
    def setSpacing(self, n):
        self._space = int(n)

    def spacing(self):
        return self._space

    def addSpacing(self, n):
        self.addItem(QSpacerItem(int(n), 0, QSizePolicy.Policy.Fixed,
                                 QSizePolicy.Policy.Minimum))

    def addStretch(self, _s=0):
        return          # en un flujo no aplica (ver docstring)

    # — QLayout —
    def addItem(self, item):
        self._items.append(item)

    def count(self):
        return len(self._items)

    def itemAt(self, i):
        return self._items[i] if 0 <= i < len(self._items) else None

    def takeAt(self, i):
        return self._items.pop(i) if 0 <= i < len(self._items) else None

    def expandingDirections(self):
        return Qt.Orientation(0)

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, w):
        return self._do_layout(QRect(0, 0, w, 0), test_only=True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._do_layout(rect, test_only=False)

    def sizeHint(self):
        return self.minimumSize()

    def minimumSize(self):
        # El mínimo es el del widget más ANCHO, no la suma: así el panel puede
        # angostarse todo lo que quiera y la barra responde creciendo hacia
        # abajo (que es el punto de este layout).
        w = h = 0
        for it in self._items:
            ms = it.minimumSize()
            w = max(w, ms.width())
            h = max(h, ms.height())
        m = self.contentsMargins()
        return QSize(w + m.left() + m.right(), h + m.top() + m.bottom())

    def _do_layout(self, rect, test_only):
        """§Ola13d — dos pasadas: la primera reparte los items en renglones y
        mide el alto de cada uno; la segunda los coloca CENTRADOS
        verticalmente en su renglón.

        La versión de una pasada los pegaba al TOPE, y ahí un rótulo de 16 px
        junto a un combo de 26 quedaba visiblemente más arriba — es lo que
        Guillermo vio en "Diagram:", "Plot:" y "X:/Y:" (2026-09-08). Un
        QHBoxLayout centra por defecto; al pasar esas barras a flujo (§90) se
        perdió sin querer.

        Fix (2026-09-23, reporte de Guillermo): la NavigationToolbar de
        matplotlib fundida aquí (§Ola13d) es OTRA cosa — ya trae su propio
        overflow nativo (el recuadro de coordenadas X/Y crece y, si no cabe,
        Qt le pone un chevron "»" con el resto adentro; verificado
        recortándola a mano). Envolverla como a cualquier otro item la
        empujaba ENTERA —desde "Reset view" hasta "Zoom"— a un renglón nuevo
        en cuanto el recuadro de coordenadas no cabía, en vez de dejarla
        recortarse sola donde ya estaba (lo que Guillermo pedía: "que
        funcione como el carril de botones" — como el QTabBar de las
        pestañas, que no salta de línea). Ahora NUNCA dispara un salto de
        renglón: toma lo que quede de ancho en su fila (con un piso de su
        `minimumSize()`, para no desaparecer) y dentro de eso decide sola
        qué se ve y qué queda tras el chevron."""
        m = self.contentsMargins()
        x = rect.x() + m.left()
        y = rect.y() + m.top()
        right = rect.right() - m.right()
        lines = [[]]          # [(item, x, w, h), …] por renglón
        line_h = 0
        heights = []
        for it in self._items:
            hint = it.sizeHint()
            w, h = hint.width(), hint.height()
            _w_ = it.widget()
            _flex = _w_ is not None and (
                isinstance(_w_, NavigationToolbar)
                or bool(_w_.property("p5Flex")))
            if _flex:
                _avail = right - x
                _min_w = it.minimumSize().width()
                if _w_.property("p5Flex"):
                    # La etiqueta de coordenadas no tiene mínimo propio (se
                    # recorta) — un piso de 90 px la mantiene VISIBLE aunque
                    # se salga del borde y el contenedor la corte.
                    _min_w = min(w, 90)
                w = max(_min_w, min(w, _avail)) if _avail > 0 else _min_w
            elif line_h and x + w > right:        # no cabe → renglón nuevo
                heights.append(line_h)
                lines.append([])
                x = rect.x() + m.left()
                line_h = 0
            lines[-1].append((it, x, w, h))
            x += w + self._space
            line_h = max(line_h, h)
        heights.append(line_h)
        if not test_only:
            yy = y
            for row, row_h in zip(lines, heights):
                for it, ix, iw, ih in row:
                    it.setGeometry(QRect(ix, yy + (row_h - ih) // 2, iw, ih))
                yy += row_h + self._space
        return (y + sum(heights) + self._space * (len(heights) - 1)
                + m.bottom() - rect.y())


class _ChoiceCellDelegate(QStyledItemDelegate):
    """§90 — editor de LISTA para las celdas de Tabla 1 que ofrecen opciones
    (Set, Position, Texture type, Hf Group).

    Antes cada una de esas celdas llevaba un QComboBox VIVO puesto con
    `setCellWidget`: con 266 filas eran ~1000 widgets por reconstrucción, 1.9 s
    de los 2.9 s que costaba cada rebuild (cProfile) y ~300 000 eventos extra
    atravesando los filtros de la tabla. Ahora el combo se crea SOLO mientras
    se edita la celda; el resto del tiempo la celda es un item de texto.

    No hubo que tocar a los consumidores: todos los que leían estas celdas ya
    tenían la forma `if isinstance(w, QComboBox): w.currentText() else:
    item.text()` (captura al modelo, copiar, pegar, exportar), así que ahora
    entran por el camino `else`. Los que ESCRIBEN (reglas de rango de sets §42,
    rename/borrado de texturas §62) siempre escribieron en el modelo, no en el
    widget.

    Las opciones se piden al llamador con `options_fn(row, col)` — devuelve la
    lista, o None si esa celda no es de lista — porque el Set depende de la
    MUESTRA de la fila (scope por muestra, §41) y el catálogo de texturas es
    editable por proyecto (§62).
    """

    def __init__(self, table, options_fn, is_choice_fn=None):
        super().__init__(table)
        self._table = table
        self._options_fn = options_fn
        # `paint` corre por celda visible en CADA repintado, así que no puede
        # pagar la construcción de la lista de sets (que además tiene que
        # averiguar a qué muestra pertenece la fila). Sondeo barato aparte.
        self._is_choice = is_choice_fn or (lambda r, c: options_fn(r, c) is not None)

    def createEditor(self, parent, option, index):
        # 2026-09-30: la franja de un grupo plegado no se edita (lo que hay
        # debajo es la primera columna del grupo, escondida a la vista).
        if index.column() in getattr(self._table, "_fold_stub_cols", ()):
            return None
        opts = self._options_fn(index.row(), index.column())
        if opts is None:
            return super().createEditor(parent, option, index)
        cb = QComboBox(parent)
        cb.addItems(opts)
        cb.setObjectName("cellChoice")
        return cb

    def setEditorData(self, editor, index):
        if isinstance(editor, QComboBox):
            val = index.data(Qt.ItemDataRole.DisplayRole) or ""
            i = editor.findText(str(val))
            # El valor guardado puede ser HUÉRFANO (una textura borrada, un set
            # fuera de alcance): se conserva como opción extra para no perderlo
            # en silencio — mismo criterio que tenían los combos vivos (§62).
            if i < 0 and str(val).strip():
                editor.addItem(str(val))
                i = editor.count() - 1
            editor.setCurrentIndex(max(0, i))
            editor.showPopup()          # un clic basta: se abre la lista sola
            return
        super().setEditorData(editor, index)

    def setModelData(self, editor, model, index):
        if isinstance(editor, QComboBox):
            model.setData(index, editor.currentText(),
                          Qt.ItemDataRole.EditRole)
            return
        super().setModelData(editor, model, index)

    def paint(self, painter, option, index):
        """Pinta la celda normal y, si es de lista, un chevron a la derecha:
        sin él nada delataría que la celda tiene opciones (antes lo decía la
        flechita del combo siempre visible)."""
        if index.column() in getattr(self._table, "_fold_stub_cols", ()):
            # Franja de un grupo plegado: sin texto (sería la primera columna
            # del grupo recortada, y confundiría).
            painter.fillRect(option.rect, QColor(THEME["seg"]))
            return
        super().paint(painter, option, index)
        if not self._is_choice(index.row(), index.column()):
            return
        r = option.rect
        if r.width() < 22:
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(THEME["text_disabled"]))
        cx = r.right() - 7
        cy = r.center().y() + 1
        painter.drawPolygon(QPolygonF([
            QPointF(cx - 3.0, cy - 1.5),
            QPointF(cx + 3.0, cy - 1.5),
            QPointF(cx, cy + 2.0),
        ]))
        painter.restore()


class SampleListDelegate(QStyledItemDelegate):
    """Delegate para QListWidget de muestras: nombre + litología debajo."""

    # Rol custom para guardar la litología en cada item.
    # Qt.UserRole ya está reservado por otros usos del programa (UserRole se
    # usa en _insert_sample_header_row para marcar filas-encabezado). Usamos
    # UserRole+1 para no colisionar.
    LITHOLOGY_ROLE = Qt.ItemDataRole.UserRole + 1
    # §37: nº de análisis (filas con datos) de la muestra; lo puebla
    # _refresh_sample_counts tras cada rebuild_table. None → no se pinta.
    COUNT_ROLE = Qt.ItemDataRole.UserRole + 2
    # §39 Stage 4: color de la identidad global de la muestra (hex) → swatch
    # cuadrado junto al nombre. Lo puebla _refresh_sample_counts también.
    SWATCH_ROLE = Qt.ItemDataRole.UserRole + 3
    # §Ola7 micro-efecto: intensidad (0..1) del destello al AGREGAR la muestra.
    # Lo anima _flash_sample_item (1→0); None/0 = sin destello.
    FLASH_ROLE = Qt.ItemDataRole.UserRole + 4

    # ¿Pintar el cuadro de color de cada muestra? (2026-09-27, lo decide el
    # botón de la fila de muestras de Projects & Samples.)
    show_swatches = True

    # Altura mínima de cada fila. Suficiente para 2 líneas + padding.
    ROW_HEIGHT_TWO_LINES = 34
    ROW_HEIGHT_ONE_LINE  = 22

    def sizeHint(self, option, index):
        """
        Devuelve la altura de la fila según haya o no litología.
        Sin litología, fila compacta (1 línea); con litología, doble altura.
        """
        size = super().sizeHint(option, index)
        lithology = index.data(self.LITHOLOGY_ROLE) or ""
        if lithology.strip():
            size.setHeight(self.ROW_HEIGHT_TWO_LINES)
        else:
            size.setHeight(self.ROW_HEIGHT_ONE_LINE)
        return size

    def paint(self, painter, option, index):
        """
        Pinta el item con nombre arriba (color y fuente principal) y litología
        abajo (más pequeño, gris secundario) si existe.

        Respeta los estados de selección, hover y check del item, dejando que
        QStyle dibuje el fondo y el indicador de checkbox, y nosotros solo
        sobreescribimos el texto.
        """
        painter.save()

        # 1. Dejar que QStyle pinte el fondo y el checkbox (manteniendo
        # comportamiento estándar: selección, hover, checkbox redondo).
        # Limpiamos el texto antes para que QStyle no lo pinte; nosotros
        # lo dibujaremos manualmente.
        # State_HasFocus se elimina explícitamente para que QStyle no dibuje
        # el recuadro punteado de foco. El recuadro confunde al usuario
        # porque persiste aún cuando la selección visual ya no aplica
        # (al hacer clic en áreas vacías o fuera del panel).
        opt = option.__class__(option)   # copia para no mutar el original
        self.initStyleOption(opt, index)
        opt.text = ""
        opt.state &= ~QStyle.StateFlag.State_HasFocus
        style = opt.widget.style() if opt.widget else QApplication.style()
        style.drawControl(QStyle.ControlElement.CE_ItemViewItem,
                          opt, painter, opt.widget)

        # 1b. §Ola7 micro-efecto: destello de la muestra recién agregada. Un
        # tinte de acento (bajo el texto) que se desvanece; FLASH_ROLE lo anima.
        _flash = index.data(self.FLASH_ROLE)
        if _flash:
            _fc = QColor(THEME["accent"])
            _fc.setAlphaF(min(1.0, float(_flash)) * 0.35)
            painter.fillRect(option.rect, _fc)

        # 2. Calcular el rect disponible para el texto, descontando el espacio
        # del checkbox a la izquierda y un padding interno.
        check_rect = style.subElementRect(
            QStyle.SubElement.SE_ItemViewItemCheckIndicator,
            opt, opt.widget,
        )
        # El texto empieza después del checkbox + un pequeño margen
        x_start = check_rect.right() + 8 if check_rect.width() > 0 else option.rect.x() + 8
        text_rect = option.rect.adjusted(0, 2, -6, -2)
        text_rect.setLeft(x_start)

        # 3. Leer datos
        name = index.data(Qt.ItemDataRole.DisplayRole) or ""
        lithology = (index.data(self.LITHOLOGY_ROLE) or "").strip()

        # 4. Determinar color del texto según selección.
        # Selección activa: blanco sobre azul (mantiene patrón QListWidget).
        # No seleccionado: azul-grafito para el nombre, gris secundario para
        # la litología.
        is_selected = bool(option.state & QStyle.StateFlag.State_Selected)
        # QListWidget atenúa la selección cuando pierde el foco (stylesheet
        # del programa lo refuerza con selection-background-color transparent).
        # Replicamos esa lógica: si está seleccionado pero sin foco del widget,
        # tratamos el item como no-seleccionado para colorear el texto.
        widget_has_focus = (opt.widget.hasFocus()
                            if opt.widget is not None else False)
        effective_selected = is_selected and widget_has_focus

        # T8 (2026-07-17): el tema (§31) pinta la selección con fondo TINTE
        # CLARO (accent_tint #EDF3FE), no azul sólido. El texto blanco de antes
        # (heredado de cuando la selección era azul) quedaba ilegible. Ahora el
        # nombre seleccionado va en ACENTO + negrita (abajo) → resalta y se lee
        # sobre el tinte, coherente con el QSS `::item:selected { color: text }`.
        if effective_selected:
            name_color = QColor(THEME["accent"])
            lith_color = QColor(THEME["text2"])
        else:
            name_color = QColor("#1a2a3a")
            lith_color = QColor("#6a8aaa")

        # 5. Fuente del nombre (igual a la del QListWidget) y de la litología
        # (1 punto menor, no-bold, color secundario).
        name_font = QFont(option.font)
        lith_font = QFont(option.font)
        base_size = name_font.pointSize() if name_font.pointSize() > 0 else 10
        lith_font.setPointSize(max(7, base_size - 2))
        if effective_selected:
            name_font.setBold(True)   # T8: refuerza la selección sobre el tinte

        # 6. Pintar. El nº de análisis (§37) va a la DERECHA de la línea del
        # nombre — así sirve igual con y sin litología, sin tocar sizeHint.
        if lithology:
            # Dos líneas: nombre arriba, litología abajo.
            # Reparto del rect: ~58% arriba, ~42% abajo.
            half = text_rect.height() // 2
            name_rect = text_rect.adjusted(0, 0, 0, -half + 2)
            lith_rect = text_rect.adjusted(0, half - 2, 0, 0)
        else:
            name_rect = text_rect
            lith_rect = None

        # §39: swatch de color de la identidad global, antes del nombre.
        # 2026-09-27: se puede ocultar (botón de la fila de muestras).
        swatch_hex = index.data(self.SWATCH_ROLE)
        if swatch_hex and self.show_swatches:
            sw = 9
            sy = name_rect.center().y() - sw // 2
            painter.setPen(QPen(QColor("#666677"), 0.8))
            painter.setBrush(QBrush(QColor(swatch_hex)))
            painter.drawRoundedRect(name_rect.left(), sy, sw, sw, 2, 2)
            name_rect = name_rect.adjusted(sw + 6, 0, 0, 0)

        count = index.data(self.COUNT_ROLE)
        count_txt = f"n = {count}" if isinstance(count, int) else ""
        if count_txt:
            painter.setFont(lith_font)
            painter.setPen(lith_color)
            painter.drawText(
                name_rect,
                Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                count_txt,
            )
            # Reservar el hueco para que un nombre largo no lo pise.
            cnt_w = painter.fontMetrics().horizontalAdvance(count_txt) + 8
            name_rect = name_rect.adjusted(0, 0, -cnt_w, 0)

        painter.setFont(name_font)
        painter.setPen(name_color)
        painter.drawText(
            name_rect,
            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
            name,
        )

        if lith_rect is not None:
            painter.setFont(lith_font)
            painter.setPen(lith_color)
            painter.drawText(
                lith_rect,
                Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                lithology,
            )

        painter.restore()


# ─────────────────────────────────────────────────────────────────────────────
# CutoffLineEdit — campo numérico estricto con rango forzado
# ─────────────────────────────────────────────────────────────────────────────
# Por qué esta subclase es necesaria:
#
# QIntValidator tiene dos limitaciones conocidas para este caso de uso:
#   1. editingFinished NO se dispara cuando el campo queda vacío al hacer Tab,
#      porque QIntValidator considera el vacío como estado "Intermediate".
#   2. Durante el tipeo, valores fuera de rango (ej. 4800 con max 4600) se
#      consideran "Intermediate" en lugar de inválidos, por lo que el campo
#      los acepta sin avisar.
#
# focusOutEvent SIEMPRE se dispara al perder el foco, independientemente del
# estado del validador, así que es el lugar correcto para hacer la validación
# final y forzar el rango.
# ─────────────────────────────────────────────────────────────────────────────
class CutoffLineEdit(QLineEdit):
    def __init__(self, text, min_val, max_val, parent=None):
        super().__init__(text, parent)
        self._min = min_val
        self._max = max_val
        self._last_valid = text
        # El QIntValidator sigue siendo útil: rechaza letras y decimales
        # durante el tipeo, aunque no garantiza el límite superior.
        self.setValidator(QIntValidator(min_val, max_val, self))

    def focusOutEvent(self, event):
        text = self.text().strip()
        if text == "":
            # Campo vacío: restaurar último valor válido
            self.setText(self._last_valid)
        else:
            try:
                v = int(text)
                if v < self._min:
                    self.setText(str(self._min))
                    self._last_valid = str(self._min)
                elif v > self._max:
                    self.setText(str(self._max))
                    self._last_valid = str(self._max)
                else:
                    self._last_valid = text
            except ValueError:
                self.setText(self._last_valid)
        super().focusOutEvent(event)


class _ContentScrollArea(QScrollArea):
    """
    QScrollArea que reporta como sizeHint el del widget interno (no el default
    de QScrollArea, que trunca la altura a ~288px). Así un QDialog que la
    contenga abre a la altura del contenido — y si el contenido excede la
    pantalla, basta con `setMaximumHeight(...)` en el diálogo para acotarlo y
    dejar que aparezca la barra de desplazamiento. Lo usa _make_panel4_dialog
    para que los diálogos largos (p.ej. U-Pb) no se salgan de pantalla.
    """
    def sizeHint(self):
        w = self.widget()
        if w is not None:
            s = w.sizeHint()
            # Holgura para el marco y la barra vertical.
            return QSize(s.width() + 26, s.height() + 4)
        return super().sizeHint()


# ── Guardar/abrir proyecto (§roadmap-6): serialización JSON ──────────────────
# Un archivo .zirclock es JSON con un sobre {format, format_version, kind, …}
# donde kind ∈ {"project","workspace"}. La ESCRITURA la hace json.dump (estringa
# las claves enteras de las celdas y convierte tuplas a listas). La RECONSTRUCCIÓN
# al leer es lo no-trivial → _restore_project deshace eso para que el dict cargado
# sea idéntico al que produce la app en runtime. Solo se guardan las ENTRADAS del
# proyecto (muestras/datos, sets, configs); Tabla 2 / Panel 5 son derivados y se
# recalculan con Calculate al abrir.
ZIRCLOCK_FORMAT = "zirclock"
# El programa se llamó "Zirchron" hasta la v1.3 y "Chronikon" de la 2.0 a la
# 2.3. Los renombres NO cambiaron nada del formato de datos —solo la etiqueta
# del sobre y la extensión—, así que los archivos viejos se siguen abriendo
# para siempre; Save escribe ya la etiqueta nueva.
ZIRCLOCK_LEGACY_FORMATS = ("chronikon", "zirchron")
# Extensiones que reconocen Open, el doble-clic y Save. La primera es la que
# lleva un archivo nuevo; uno que llegó con una vieja se guarda con la suya.
ZIRCLOCK_EXTENSIONS = (".zirclock", ".chronikon", ".zirchron")
# v2 (§39): al abrir v1 se purgan los valores FANTASMA de la familia "Samples"
# (color_by/sample_styles/legend_samples) en las pestañas donde §30 la tenía
# OCULTA. v3 (§39 Stage 4): purga el `color_by` fantasma que hf_style/tibox_style
# pudieron re-adquirir en archivos v2 (esas dos familias se expusieron en Stage 4,
# así que un color_by previo NO fue elección del usuario). El FANTASMA ya no se
# re-introduce: `_build_style_section` dejó de escribir las familias ocultas.
ZIRCLOCK_FORMAT_VERSION = 6

# §Ola8: versión visible del SOFTWARE (distinta del format_version del archivo).
# Se muestra en About ▸ Version & credits (y será útil para el empaquetado, Ola 10).
ZIRCLOCK_VERSION = "3.1"


def _zirclock_json_default(o):
    """Fallback de json.dump: convierte tipos no-JSON que pudieran colarse en las
    configs (set/tuple) a algo serializable; cualquier otro tipo inesperado lanza
    TypeError (lo cazamos en el test de ida-y-vuelta)."""
    if isinstance(o, set):
        return sorted(o)
    if isinstance(o, tuple):
        return list(o)
    raise TypeError(f"No JSON-serializable: {type(o)!r}")


# ── Ola 3 (T19): clave de VISTA ──────────────────────────────────────────────
# Un "gráfico" de Panel 5 se identifica por (pestaña, VARIANTE, muestra) — no
# solo por pestaña. La variante es lo que cambia el diagrama sin cambiar de
# pestaña: el espacio de Concordia (Wetherill/TW), el tipo de plot de Hf, el
# modo del KDE (curva/stacked/matriz), el par X|Y del Bivariate, el diagrama
# tectónico. La clave es un string "variante@muestra" (muestra = "__all__" en
# modo combinado). El estado de vista (anotaciones §59, rótulos §58, posición
# de leyenda §57, y a futuro encuadre congelado/insets) vive en
# <tab>_style["views"][clave] → una flecha dibujada en Wetherill de SM21 NO
# aparece en Tera-Wasserburg ni en otra muestra, y VUELVE al regresar.
# Función PURA (módulo-nivel) porque la migración v4 corre sin MainWindow.

# Claves (modo, muestra) por pestaña + default del modo (0 = per-sample en
# todos MENOS Multi-element, que arranca en All combined). tibox no aparece:
# no tiene selector de muestra (sus modos son multi-caja) → siempre "__all__".
_P5_VIEW_SAMPLE_KEYS = {
    "concordia_style": ("mode", "sample", 0),
    "wmean_style": ("wmean_mode", "wmean_sample", 0),
    "kde_style": ("kde_mode", "kde_sample", 0),
    "hf_style": ("hf_mode", "hf_sample", 0),
    "biv_style": ("biv_mode", "biv_sample", 0),
    "me_style": ("me_mode", "me_sample", 1),
    "tect_style": ("tect_mode", "tect_sample", 0),
}

# ── Configuración POR MUESTRA (2026-10-08, pedido de Guillermo) ────────────
# "Que toda la configuración de una muestra sólo aplique a la muestra en
# cuestión y perdure en la memoria." Cada pestaña con modo por muestra guarda
# un PERFIL por muestra (y uno, "__all__", para los modos combinados): sus
# claves de contenido (`<prefijo>_*`) y su estilo plano (tipografía, leyenda,
# marco — sin `views`). Los EJES (rangos, proporción, ventana de edades)
# siguen en views["variante@muestra"] como desde §63/§79.
# Mecanismo: la config PLANA siempre es la del perfil ACTIVO
# (`_profile_on[pestaña]`); al cambiar de muestra se guarda en el perfil que
# se deja y se carga el de la nueva (`_p5_profile_sync`). Así ningún builder
# ni diálogo cambia su manera de leer la config. Decisiones de Guillermo:
# por MUESTRA (no por diagrama: Wetherill y TW de JH1 comparten colores);
# una muestra sin perfil arranca con los valores de FÁBRICA (al migrar un
# proyecto viejo, cada muestra que ya existía recibe el aspecto de hoy);
# "Copy from sample…" y "Apply to all samples" copian TODO, ejes incluidos.
_P5_PROFILE_PREFIX = {
    "concordia_style": "concordia_", "wmean_style": "wmean_",
    "kde_style": "kde_", "hf_style": "hf_", "biv_style": "biv_",
    "me_style": "me_", "tect_style": "tect_",
    # 2026-10-24: el boxplot de Ti también tiene "Per sample" (§39); §148 lo
    # dejó fuera porque su modo no es un entero (`tibox_primary`).
    "tibox_style": "tibox_",
}
# Claves de esas familias que NO son de la muestra: las que ELIGEN la muestra
# o el diagrama, la lista del modo combinado y todo el side-by-side (que es
# siempre combinado y tiene su propio contenido, §118).
_P5_PROFILE_SKIP = frozenset({
    "concordia_space", "concordia_sbs_on", "kde_diagram",
    "kde_radial_sample", "hf_plot_type", "biv_x", "biv_y", "biv_stack_on",
    "biv_stack_ys", "tect_diagram", "tibox_primary",
})


def _p5_profiled(style_key):
    """Decorador de los `_update_*_plot`: antes de graficar, la config plana
    pasa a ser la de la muestra que se va a dibujar (`_p5_profile_sync`).
    Descarta los argumentos a propósito (gotcha §119: un `clicked` de Qt
    manda `checked` y los updaters no reciben nada)."""
    import functools

    def deco(fn):
        @functools.wraps(fn)
        def wrapper(self, *_args, **_kwargs):
            try:
                self._p5_profile_sync(style_key)
            except Exception:
                pass
            return fn(self)
        return wrapper
    return deco


def _p5_profile_owns(style_key, k):
    """¿La clave `k` de panel5_config es parte del perfil por muestra de esa
    pestaña?"""
    pre = _P5_PROFILE_PREFIX.get(style_key)
    if not pre or not k.startswith(pre) or k == style_key:
        return False
    if (k in _P5_PROFILE_SKIP or k.endswith("_mode") or k.endswith("_sample")
            or k.endswith("_hidden_samples") or k.startswith("concordia_sbs_")
            or k.startswith("kde_stk_") or k.startswith("kde_stack_")
            or k.endswith("_style")):
        # (Paso 10: `kde_stack_*` es de las VERSIONES del Stacked, que
        # siempre va con el perfil combinado: si los perfiles también la
        # intercambiaran, los dos sistemas se pisarían.)
        return False
    return True


