def _cfg_snapshot(obj):
    """Foto de una config que recuerda los OBJETOS (dicts y listas) además de
    su contenido, para que `_cfg_restore` los devuelva tal cual: mismos
    objetos, en su sitio, con su contenido de ese momento.

    Lo usa el "ensayo" de cambios pendientes de los Settings de Panel 5: se
    corre el commit del diálogo sobre la config real y luego se deshace. Un
    `clear()` + `update(copia)` dejaría en la config objetos NUEVOS, y quien
    guardara una referencia al original (un bloque del diálogo que capturó su
    `me_ramp`, cualquier otra parte de la app) seguiría escribiendo en un
    dict que ya no está en la config — en silencio."""
    import copy
    if isinstance(obj, dict):
        return (obj, {k: _cfg_snapshot(v) for k, v in obj.items()})
    if isinstance(obj, list):
        return (obj, [_cfg_snapshot(v) for v in obj])
    return (None, copy.deepcopy(obj))


def _cfg_restore(snap):
    orig, content = snap
    if orig is None:
        return content
    if isinstance(orig, dict):
        vals = {k: _cfg_restore(v) for k, v in content.items()}
        orig.clear()
        orig.update(vals)
    else:
        orig[:] = [_cfg_restore(v) for v in content]
    return orig


def _p5_view_key_for(p5cfg, style_key, variant_override=None):
    """Clave de vista "variante@muestra" para la pestaña `style_key`, computada
    desde `p5cfg` (el panel5_config del proyecto). `variant_override` fuerza la
    variante (lo usa la migración v4 para repartir label_pos de Hf)."""
    cfg = p5cfg or {}
    # 2026-09-25: las concordias LADO A LADO son otro diagrama. Antes
    # compartían la clave de la concordia sencilla de la muestra elegida
    # (p. ej. "wetherill@JH1") y heredaban su 🔒 encuadre congelado, su
    # leyenda y sus anotaciones — con el encuadre de UNA muestra, las
    # etiquetas de edad del lado a lado se salían del área de dibujo.
    if (variant_override is None and style_key == "concordia_style"
            and cfg.get("concordia_sbs_on")):
        # Paso 10: cada versión con nombre tiene su propia vista.
        return f"sbs{_version_view_suffix(cfg, 'sbs')}@__all__"
    if variant_override is not None:
        var = variant_override
    elif style_key == "concordia_style":
        var = cfg.get("concordia_space", "wetherill")
    elif style_key == "hf_style":
        var = cfg.get("hf_plot_type", "ehf_t_vs_age")
    elif style_key == "kde_style":
        var = {"radial": "radial", "stacked": "stacked",
               "matrix": "matrix"}.get(_kde_diagram_of(cfg), "curve")
    elif style_key == "biv_style":
        var = f"{cfg.get('biv_x') or 'x'}|{cfg.get('biv_y') or 'y'}"
    elif style_key == "tect_style":
        var = cfg.get("tect_diagram", "uyb_nbyb")
    else:
        var = "main"      # wmean / tibox / me: sus modos son agrupación, no variante
    keys = _P5_VIEW_SAMPLE_KEYS.get(style_key)
    sample = "__all__"
    # El boxplot de TDM es multi-caja (ignora hf_mode/hf_sample) → "__all__".
    if keys is not None and not (style_key == "hf_style"
                                 and var == "tdm_boxplot"):
        mode_key, sample_key, mode_default = keys
        try:
            mode = int(cfg.get(mode_key, mode_default) or 0)
        except (TypeError, ValueError):
            mode = mode_default
        # Concordia tiene DOS modos per-sample: 0 (combined dentro de la
        # muestra) y 4 (by set dentro de la muestra, Bug §7-2). El resto de
        # las pestañas: solo el 0.
        per_sample = (mode in (0, 4) if style_key == "concordia_style"
                      else mode == 0)
        if per_sample:
            sample = str(cfg.get(sample_key, "") or "")
        # El radial elige su muestra aparte ("" = todas las activas).
        if style_key == "kde_style" and var == "radial":
            sample = str(cfg.get("kde_radial_sample", "") or "") or "__all__"
        # El Stacked y la matriz son de varias muestras (paso 8).
        if style_key == "kde_style" and var in ("stacked", "matrix"):
            sample = "__all__"
    # 2026-10-24 (reporte de Guillermo con SJC): el boxplot de Ti también
    # tiene "Per sample" (§39, `tibox_primary`, que no es un modo entero y
    # por eso quedó fuera de _P5_VIEW_SAMPLE_KEYS). Con UNA vista para todas
    # las muestras, el título editado a mano en 33b ("… — 33b") seguía
    # encima del gráfico de 13b, y con él la leyenda, los ejes y el 🔒.
    if style_key == "tibox_style" and cfg.get("tibox_primary") == "per_sample":
        sample = str(cfg.get("tibox_sample", "") or "") or "__all__"
    if (variant_override is None and style_key == "kde_style"
            and var == "stacked"):
        var += _version_view_suffix(cfg, "stacked")      # paso 10
    return f"{var}@{sample}"


def _migrate_p5_views_v4(p5cfg):
    """Migración v4 (Ola 3 / T19): mueve el estado de vista PLANO de cada
    <tab>_style (annotations §59, label_pos §58, legend_loc/legend_bbox §57) a
    style["views"][clave-de-vista]. La clave destino es la de la config
    GUARDADA — la vista que el usuario tenía activa, que es donde dibujó sus
    flechas/acomodó su leyenda. Caso especial Hf: sus label_pos ya venían con
    prefijo de variante ("ehf_"/"ratio_", parche local pre-Ola 3) → se reparten
    a la vista de SU variante, no a la activa."""
    # ⚠ El valor real de hf_plot_type para la razón es "hf_init_vs_age";
    # "hf_ratio_vs_age" nunca existió (dedazo de §63, cazado el 2026-09-07 al
    # escribir el test de las líneas corticales). Con el nombre inventado, los
    # label_pos migrados de un archivo v3 aterrizaban en una clave de vista
    # muerta y los rótulos de ese diagrama volvían a su sitio por defecto.
    _HF_LABEL_VARIANTS = {"ehf": "ehf_t_vs_age", "ratio": "hf_init_vs_age"}
    for sk in ("concordia_style", "wmean_style", "kde_style", "hf_style",
               "biv_style", "me_style", "tect_style", "tibox_style"):
        st = p5cfg.get(sk)
        if not isinstance(st, dict):
            continue
        flat = {k: st.pop(k) for k in ("annotations", "label_pos",
                                       "legend_loc", "legend_bbox")
                if st.get(k) is not None}
        # pop de claves presentes pero None: basura, fuera sin migrar
        for k in ("annotations", "label_pos", "legend_loc", "legend_bbox"):
            st.pop(k, None)
        if not flat:
            continue
        views = st.setdefault("views", {})

        def _entry(vk):
            return views.setdefault(vk, {})

        vk_now = _p5_view_key_for(p5cfg, sk)
        for k in ("annotations", "legend_loc", "legend_bbox"):
            if k in flat:
                _entry(vk_now)[k] = flat[k]
        lp = flat.get("label_pos")
        if isinstance(lp, dict) and lp:
            for key, pos in lp.items():
                var = None
                if sk == "hf_style":
                    var = _HF_LABEL_VARIANTS.get(str(key).split("_", 1)[0])
                vk = (vk_now if var is None
                      else _p5_view_key_for(p5cfg, sk, variant_override=var))
                _entry(vk).setdefault("label_pos", {})[key] = pos


def _migrate_tibox_sample_views(p5cfg, sample_names):
    """2026-10-24: el boxplot de Ti pasa a tener una vista por muestra en
    "Per sample" (ver _p5_view_key_for). Hasta hoy todas compartían
    "main@__all__", así que esa vista ES la que el usuario veía en cada
    muestra: se COPIA a la de cada una que aún no tenga la suya (nada cambia
    a la vista al reabrir). Excepción: un título que nombra a OTRA muestra y
    no a esta (el "… — 33b" de SJC) no se copia — esa muestra recupera el
    suyo de fábrica. Corre una sola vez por proyecto (`_tibox_sample_views`;
    sin el prefijo "tibox_", que lo haría viajar con cada perfil)."""
    import copy
    import re
    if not isinstance(p5cfg, dict) or p5cfg.get("_tibox_sample_views"):
        return
    p5cfg["_tibox_sample_views"] = True
    st = p5cfg.get("tibox_style")
    views = st.get("views") if isinstance(st, dict) else None
    base = (views or {}).get("main@__all__")
    if not isinstance(base, dict) or not base:
        return
    names = [str(n) for n in sample_names if n]

    def _names_in(text):
        return {n for n in names if re.search(
            r"(?<![\w-])" + re.escape(n) + r"(?![\w-])", text)}
    for n in names:
        vk = f"main@{n}"
        if vk in views:
            continue
        v = copy.deepcopy(base)
        _t = v.get("title")
        if isinstance(_t, str) and _names_in(_t) - {n} and n not in _names_in(_t):
            v.pop("title", None)
        views[vk] = v


def _mc_to_hex_dark(hex_color, k=0.65):
    """La versión oscura de un color que usa la línea de las filas del KDE
    apilado cuando el usuario no eligió una (hex → hex)."""
    import matplotlib.colors as _m
    return _m.to_hex(tuple(c * k for c in _m.to_rgb(hex_color)))


def _purge_legacy_text_edits(p5cfg):
    """Ediciones de texto hechas en el gráfico (doble clic) guardadas con la
    clave VIEJA, que convertía en "#" también los números de los nombres de
    muestra ("SJ25-37" → "SJ##") y separaba las iguales con un índice: al
    cambiar qué muestras se ven, caían sobre OTRA (bug de 2026-09-27). Con la
    clave nueva ya no coinciden con nada; se retiran para que no queden
    colgando. Se reconocen porque la clave nueva nunca pone un "#" pegado a
    una letra. Idempotente, corre siempre al abrir."""
    import re
    bad = re.compile(r"[^\W\d_]#|#[^\W\d_]")
    for st in (p5cfg or {}).values():
        views = st.get("views") if isinstance(st, dict) else None
        if not isinstance(views, dict):
            continue
        for v in views.values():
            te = v.get("text_edits") if isinstance(v, dict) else None
            if not isinstance(te, dict):
                continue
            for k in [k for k in te if isinstance(k, str)
                      and k[:4] in ("leg:", "txt:")
                      and bad.search(k[4:].rsplit("#", 1)[0])]:
                te.pop(k, None)


def _migrate_sbs_label_positions(p5cfg):
    """El lado a lado tiene clave de vista propia desde 2026-09-25 ("sbs@
    __all__"). Sus rótulos arrastrados (`label_pos["sbs_<muestra>"]`) vivían
    en la vista de la concordia sencilla que estuviera activa: se MUDAN a la
    vista nueva para no perder dónde los dejó el usuario. Idempotente (sin
    claves sbs_ fuera de su vista no hace nada), así que corre siempre."""
    st = (p5cfg or {}).get("concordia_style")
    views = st.get("views") if isinstance(st, dict) else None
    if not isinstance(views, dict):
        return
    dest = None
    for vk, v in list(views.items()):
        if vk == "sbs@__all__" or not isinstance(v, dict):
            continue
        lp = v.get("label_pos")
        if not isinstance(lp, dict):
            continue
        moved = {k: lp.pop(k) for k in [k for k in lp
                                          if str(k).startswith("sbs_")]}
        if not moved:
            continue
        if dest is None:
            dest = views.setdefault("sbs@__all__", {}).setdefault(
                "label_pos", {})
        for k, val in moved.items():
            dest.setdefault(k, val)


# 2026-09-27 (decisión de Guillermo): "Side-by-side Wetherill" es un diagrama
# PROPIO de la pestaña Concordia (entre Wetherill y Tera-Wasserburg en la
# columna Diagram de Settings), con su CONTENIDO propio: quién pone el color y
# cómo se dibuja cada grano ya no se comparten con la concordia sencilla — unas
# clases en la figura de comparación no deben recolorear tu Wetherill. La
# tipografía (Style) sí se comparte, para que las figuras del artículo casen;
# lo que es de cada diagrama (título, marco, proporciones, rango de edades) ya
# vivía por vista (§79). Clave canónica → clave del side-by-side:
_SBS_OWN_KEYS = {
    "concordia_color_by": "concordia_sbs_color_by",
    "concordia_ramp": "concordia_sbs_ramp",
    "concordia_ellipse_alpha": "concordia_sbs_ellipse_alpha",
    "concordia_ellipse_lw": "concordia_sbs_ellipse_lw",
    "concordia_show_excluded": "concordia_sbs_show_excluded",
    "concordia_unassigned_fill": "concordia_sbs_unassigned_fill",
    "concordia_unassigned_edge": "concordia_sbs_unassigned_edge",
    "concordia_single_color": "concordia_sbs_single_color",
    "concordia_set_ramp": "concordia_sbs_set_ramp",     # 2026-09-29
    "concordia_sample_ramp": "concordia_sbs_sample_ramp",   # 2026-10-08
}
# Los colores propios por muestra (3 · Color by ▸ Sample) de la concordia
# sencilla viven en concordia_style["sample_styles"]; los del side-by-side,
# aquí (fuera del estilo, que es compartido).
_SBS_SAMPLE_STYLES_KEY = "concordia_sbs_sample_styles"


def _sbs_cfg_view(p5cfg):
    """Copia PLANA de panel5_config en la que las claves de contenido de la
    concordia apuntan a las del side-by-side. La leen su builder y su diálogo
    con el mismo código de siempre. Los valores son los MISMOS objetos (la
    rampa, sobre todo): lo que se escriba dentro de ellos —el tamaño de la
    barra de color arrastrada— cae en la config del side-by-side."""
    cfg = p5cfg or {}
    view = dict(cfg)
    for canon, own in _SBS_OWN_KEYS.items():
        if own in cfg:
            view[canon] = cfg[own]
        else:
            view.pop(canon, None)
    # Sin Color by propio, `_concordia_color_by` lo deduciría del MODO de la
    # concordia sencilla ("By sample" = por muestra); aquí el modo no existe.
    view["mode"] = 0
    st = dict(cfg.get("concordia_style") or {})
    st["sample_styles"] = cfg.get(_SBS_SAMPLE_STYLES_KEY) or {}
    view["concordia_style"] = st
    return view


def _migrate_sbs_own_content(p5cfg):
    """Al separar el contenido del side-by-side (2026-09-27), un proyecto
    guardado antes se ve IGUAL: la primera vez que se abre, el side-by-side
    hereda una sola vez el color y las elipses que compartía con la concordia
    sencilla. Desde ahí son independientes. Idempotente (marca
    `concordia_sbs_own`)."""
    import copy
    if not isinstance(p5cfg, dict) or p5cfg.get("concordia_sbs_own"):
        return
    for canon, own in _SBS_OWN_KEYS.items():
        if canon in p5cfg and own not in p5cfg:
            p5cfg[own] = copy.deepcopy(p5cfg[canon])
    if "concordia_sbs_color_by" not in p5cfg:
        # Lo que se VEÍA: la rampa encendida mandaba; si no, el modo 2 (por
        # muestra) — misma deducción que `_concordia_color_by`.
        r = p5cfg.get("concordia_ramp") or {}
        if r.get("on") and r.get("var"):
            cb = "classes" if r.get("mode") == "classes" else "ramp"
        else:
            cb = "sample" if int(p5cfg.get("mode", 0) or 0) == 2 else "set"
        p5cfg["concordia_sbs_color_by"] = cb
    ss = (p5cfg.get("concordia_style") or {}).get("sample_styles")
    if ss and _SBS_SAMPLE_STYLES_KEY not in p5cfg:
        p5cfg[_SBS_SAMPLE_STYLES_KEY] = copy.deepcopy(ss)
    p5cfg["concordia_sbs_own"] = True


# ── Paso 8 (L8, 2026-10-09): Age distribution con CUATRO diagramas ─────────
# "Stacked KDE" y "Similarity matrix" eran MODOS de Age distribution
# (`kde_mode` 2 y 3, junto a Per sample / All combined); ahora son diagramas
# de la columna Diagram, como el side-by-side en Concordia (§118). Decisiones
# de Guillermo: también la matriz; el Stacked con TODO PROPIO (su edad, ancho
# de banda, picos, MDA, puntos y su LISTA de muestras) — la primera vez
# hereda lo de hoy, así que se ve igual; la matriz comparte con "All
# combined"; nombre "Stacked KDE". Lo que es de la pestaña (tipografía,
# identidad de las muestras, §79) sigue compartido; lo de la vista (título,
# rangos, proporción) ya era por diagrama (`stacked@__all__`).
# `kde_mode` 2/3 sigue LEYÉNDOSE como "Stacked"/"Matrix" (proyectos y
# pruebas de antes): es la codificación vieja de "ese diagrama, con el KDE
# en All combined". Elegir "Age distribution" en la columna la limpia.
_KDE_DIAGRAMS = ("kde", "stacked", "matrix", "radial")   # orden de la columna
_KDE_STACK_OWN_KEYS = {k: "kde_stk_" + k[len("kde_"):] for k in (
    "kde_age_source", "kde_bandwidth", "kde_bw_auto", "kde_bin_width",
    "kde_show_peaks", "kde_peak_mark", "kde_peak_label", "kde_peak_min_n",
    "kde_peak_sigma", "kde_peak_prominence", "kde_align_peaks",
    "kde_band_color", "kde_band_alpha", "kde_label_side", "kde_show_labels",
    "kde_show_mda", "kde_mda_mark", "kde_show_excluded", "kde_show_rug",
    "kde_dots_color_by", "kde_dots_ramp", "kde_dots_set_ramp",
    "kde_dots_sample_ramp", "kde_dots_single_color", "kde_dots_size",
    "kde_dots_alpha", "kde_hidden_samples")}
# Lo que un cuerpo de Stacked o de matriz NO escribe de vuelta: eligen el
# diagrama, el modo y la muestra del KDE (que ahí ni se ven).
_KDE_VIEW_SKIP = frozenset({"kde_mode", "kde_diagram", "kde_sample"})


def _kde_diagram_of(p5cfg):
    """"kde" | "stacked" | "matrix" | "radial": el diagrama de Age
    distribution que toca dibujar. `kde_mode` 2/3/4 son las codificaciones
    viejas del apilado, la matriz y el radial provisional (§116)."""
    cfg = p5cfg or {}
    d = cfg.get("kde_diagram")
    if d in ("stacked", "matrix", "radial"):
        return d
    try:
        m = int(cfg.get("kde_mode", 0) or 0)
    except (TypeError, ValueError):
        m = 0
    return {2: "stacked", 3: "matrix", 4: "radial"}.get(m, "kde")


def _kde_diag_view(p5cfg, diagram=None):
    """La config que leen el builder y el Settings de ese diagrama. Para el
    KDE y el radial, la de siempre (el MISMO dict). Para el Stacked, una copia
    PLANA donde las claves de siempre (`kde_bandwidth`…) apuntan a las suyas
    (`kde_stk_bandwidth`…) — los mismos OBJETOS, como `_sbs_cfg_view`: lo que
    se escriba dentro de un dict cae en el suyo. En las dos vistas nuevas
    `kde_mode` vale 2 / 3, así el código de siempre sabe qué dibuja."""
    cfg = p5cfg if p5cfg is not None else {}
    d = diagram or _kde_diagram_of(cfg)
    if d not in ("stacked", "matrix"):
        return cfg
    view = dict(cfg)
    if d == "stacked":
        for canon, own in _KDE_STACK_OWN_KEYS.items():
            if own in cfg:
                view[canon] = cfg[own]
            else:
                view.pop(canon, None)
    view["kde_mode"] = 2 if d == "stacked" else 3
    return view


def _kde_view_write_through(view, before, real, diagram):
    """Lleva a la config REAL lo que el commit de un Settings cambió en la
    vista (`before` = la vista justo antes): cada clave propia del Stacked a
    la suya; las demás tal cual; nunca las que eligen diagrama, modo o
    muestra (`_KDE_VIEW_SKIP`). Un valor RE-ASIGNADO cuenta como cambio (un
    número igual, re-escrito, no hace daño); lo cambiado DENTRO de un dict ya
    está en el real (son los mismos objetos)."""
    own_map = _KDE_STACK_OWN_KEYS if diagram == "stacked" else {}
    for k in set(before) | set(view):
        if k in _KDE_VIEW_SKIP:
            continue
        tgt = own_map.get(k, k)
        if k not in view:
            real.pop(tgt, None)
        elif k not in before or view[k] is not before[k]:
            real[tgt] = view[k]


def _ensure_kde_stack_own(p5cfg):
    """La primera vez (proyectos de antes del 2026-10-09), el Stacked hereda
    UNA vez lo que compartía con el KDE — el perfil del combinado (§148),
    que es el que dibujaba — y desde ahí es independiente. Idempotente
    (marca `kde_stk_own`)."""
    import copy
    if not isinstance(p5cfg, dict) or p5cfg.get("kde_stk_own"):
        return
    src = p5cfg
    prof = (((p5cfg.get("sample_profiles") or {}).get("kde_style") or {})
            .get("__all__"))
    on = (p5cfg.get("_profile_on") or {}).get("kde_style")
    if isinstance(prof, dict) and on not in (None, "__all__"):
        src = dict(p5cfg)
        src.update(prof.get("content") or {})
    for canon, own in _KDE_STACK_OWN_KEYS.items():
        if canon in src and own not in p5cfg:
            p5cfg[own] = copy.deepcopy(src[canon])
    # Los puntos del apilado usaban su propia rampa si no había la común.
    if ("kde_stk_dots_ramp" not in p5cfg
            and isinstance(p5cfg.get("kde_stack_dot_ramp"), dict)):
        p5cfg["kde_stk_dots_ramp"] = copy.deepcopy(
            p5cfg["kde_stack_dot_ramp"])
    p5cfg["kde_stk_own"] = True


# ── Paso 9 (L20, 2026-10-12): GAPS en el Stacked ───────────────────────────
# Un gap parte la pila en GRUPOS, cada uno en su propio recuadro y con su
# rótulo vertical. Se guarda en la VISTA del Stacked (`stack_gaps`: nombres de
# muestra) anclado a la muestra de ARRIBA, por nombre — así viaja con ella al
# reordenar y se migra al renombrar (§115). Decisiones de Guillermo: si la
# muestra ancla no se ve, el gap pasa a la visible ANTERIOR (los grupos
# siguen separados); si no queda ninguna arriba, no se dibuja.
_STACK_GAP_PCT_DEFAULT = 50.0      # % de la distancia entre filas


# ── Paso 10 (L7, 2026-10-14): VERSIONES con nombre del side-by-side y del
# Stacked ────────────────────────────────────────────────────────────────
# Decisiones de Guillermo: varias versiones por diagrama, en la columna
# Diagram de Settings (bajo su diagrama, con sangría, "+ New" y clic derecho
# ▸ Rename / Duplicate / Delete); cada una con su CONTENIDO y su VISTA
# (muestras, Color by, espaciado, gaps, encuadre, 🔒, leyenda, textos,
# anotaciones); la tipografía se comparte; una nueva nace como COPIA de la
# activa; elegir otra la activa al momento (como la muestra, §148); en el
# compositor, un panel puede llevar una versión concreta.
# Modelo: la config PLANA de siempre es la de la versión ACTIVA (todo el
# código que ya existe la sigue leyendo igual); las demás guardan su
# contenido en `diagram_versions[kind]["items"][…]["content"]`. La vista de
# la primera conserva su clave de siempre ("sbs@__all__"); las demás llevan
# "~<id>" ("sbs~v2@__all__").
_P5_VERSION_KINDS = {
    # kind: (pestaña, style_key, nombre base, texto del diagrama en la columna)
    "sbs": ("concordia", "concordia_style", "Side-by-side",
            "Side-by-side Wetherill"),
    "stacked": ("kde", "kde_style", "Stacked", "Stacked KDE"),
}
# Los colores de las filas del Stacked viven en `kde_style` (Content ▸ KDE
# curve — Stacked rows): son contenido de la versión, no tipografía.
_STACK_ROW_STYLE_KEYS = ("stack_color_mode", "stack_color_rows",
                         "stack_single_color", "stack_fill_strength",
                         "stack_line_color", "stack_line_width")


def _version_owns(kind, k):
    """¿La clave `k` de panel5_config es contenido de una versión?"""
    if kind == "sbs":
        return (k.startswith("concordia_sbs_")
                and k not in ("concordia_sbs_on", "concordia_sbs_own"))
    if kind == "stacked":
        return ((k.startswith("kde_stk_") and k != "kde_stk_own")
                or k.startswith("kde_stack_"))
    return False


def _versions(p5cfg, kind, create=False):
    """{"active": id, "items": [{"id", "name", "content"?}]} o None. La
    primera vez nace con la versión de hoy: "Side-by-side 1" / "Stacked 1"."""
    if not isinstance(p5cfg, dict) or kind not in _P5_VERSION_KINDS:
        return None
    allv = p5cfg.get("diagram_versions")
    reg = allv.get(kind) if isinstance(allv, dict) else None
    if (not isinstance(reg, dict) or not reg.get("items")) and create:
        reg = {"active": "v1",
               "items": [{"id": "v1",
                          "name": f"{_P5_VERSION_KINDS[kind][2]} 1"}]}
        p5cfg.setdefault("diagram_versions", {})[kind] = reg
    if isinstance(reg, dict) and reg.get("items"):
        if reg.get("active") not in [it.get("id") for it in reg["items"]]:
            reg["active"] = reg["items"][0].get("id")
        return reg
    return None


def _version_item(reg, vid):
    return next((it for it in (reg or {}).get("items", [])
                 if it.get("id") == vid), None)


def _version_view_suffix(p5cfg, kind):
    """"" para la versión "v1" (la de siempre, clave de vista intacta) o
    "~<id>" para las demás."""
    reg = _versions(p5cfg, kind)
    vid = (reg or {}).get("active")
    return "" if vid in (None, "v1") else f"~{vid}"


def _version_capture(p5cfg, kind):
    """Copia del contenido de la versión ACTIVA (lo que hoy está plano)."""
    import copy
    content = {k: copy.deepcopy(v) for k, v in p5cfg.items()
               if _version_owns(kind, k)}
    style = {}
    if kind == "stacked":
        st = p5cfg.get("kde_style") or {}
        style = {k: copy.deepcopy(st[k]) for k in _STACK_ROW_STYLE_KEYS
                 if k in st}
    return {"content": content, "style": style}


def _version_load(p5cfg, kind, snap):
    """Pone en la config plana el contenido `snap`. EN SITIO cuando ya hay un
    dict (quien guarde la referencia —una barra de color— la sigue viendo),
    como `_p5_profile_load`."""
    import copy
    snap = snap or {}
    content = snap.get("content") or {}
    for k in [k for k in p5cfg if _version_owns(kind, k)
              and k not in content]:
        del p5cfg[k]
    for k, v in content.items():
        if isinstance(v, dict) and isinstance(p5cfg.get(k), dict):
            p5cfg[k].clear()
            p5cfg[k].update(copy.deepcopy(v))
        else:
            p5cfg[k] = copy.deepcopy(v)
    if kind == "stacked":
        st = p5cfg.setdefault("kde_style", {})
        sty = snap.get("style") or {}
        for k in _STACK_ROW_STYLE_KEYS:
            if k in sty:
                st[k] = copy.deepcopy(sty[k])
            else:
                st.pop(k, None)


def _version_activate(p5cfg, kind, vid):
    """Activa la versión `vid`: el contenido plano de hoy se guarda en la que
    se deja y se carga el de la nueva. True si cambió algo."""
    reg = _versions(p5cfg, kind, create=True)
    new = _version_item(reg, vid)
    if new is None or reg.get("active") == vid:
        return False
    old = _version_item(reg, reg.get("active"))
    if old is not None:
        old["content"] = _version_capture(p5cfg, kind)
    _version_load(p5cfg, kind, new.get("content"))
    new.pop("content", None)            # la activa vive en lo plano
    reg["active"] = vid
    return True


def _version_view_key(kind, vid):
    """La clave de vista de una versión (la de "v1" es la de siempre)."""
    var = "sbs" if kind == "sbs" else "stacked"
    return f"{var}{'' if vid == 'v1' else '~' + vid}@__all__"


def _stack_effective_gaps(order_all, shown, anchors):
    """{i: [anclas]} — un gap DEBAJO de la fila `i` de `shown` (las filas que
    se dibujan, en orden). `order_all` = todas las muestras del proyecto en
    el orden de Projects & Samples; `anchors` = lo guardado. Cada ancla cae
    en su muestra o, si esa no se dibuja, en la visible anterior; dos anclas
    en el mismo límite son UN gap (la lista conserva las dos, para poder
    cerrarlo de una vez). Un gap debajo de la última fila no existe."""
    pos = {n: k for k, n in enumerate(order_all)}
    row_of = {n: k for k, n in enumerate(shown)}
    out = {}
    for a in anchors or []:
        j = pos.get(a)
        if j is None:
            continue                   # muestra borrada: el gap se va
        while j >= 0 and order_all[j] not in row_of:
            j -= 1
        if j < 0:
            continue                   # ninguna visible arriba
        i = row_of[order_all[j]]
        if i >= len(shown) - 1:
            continue
        out.setdefault(i, []).append(a)
    return out


# ── §120: estilos pegados → una hoja por cuerpo de Settings ────────────────
# (2026-09-27, pedido de Guillermo). Los Settings de Panel 5 traían ~290 hojas
# de estilo PEGADAS a controles sueltos (`background: transparent`,
# `font-size: 12px`…) y Qt calcula el estilo de cada control contra las hojas
# de TODOS sus ancestros: cambiar de diagrama costaba ~230 ms, casi todo eso.
# Mientras se construye un Settings, `setStyleSheet` se INTERCEPTA: la hoja se
# guarda sin aplicarse (quitarla después cuesta lo mismo que ponerla, medido)
# y al terminar `_hq_end` la convierte en una REGLA de una sola hoja puesta en
# el cuerpo; el control solo lleva una propiedad que la selecciona. Nada
# cambia en pantalla — verificado píxel a píxel en los 8 Settings:
#   · hoja SIN selector en un contenedor (solo fondo transparente): se
#     heredaba a TODO lo de adentro, botones, campos y combos incluidos
#     (medido sobre fondo rosa) → se marca al contenedor y a cada descendiente
#     (`hqt`); una regla con descendientes (`X Y`) resultó MÁS lenta;
#   · la de un control hoja → regla de ese control (`hq`);
#   · la que trae selectores de tipo (`QPushButton:hover`, `QComboBox
#     QAbstractItemView`…) → los mismos selectores, anclados al control.
# La hoja del cuerpo está más cerca que el tema del diálogo, así que le gana
# igual que le ganaban las pegadas; y la heredada va primero, para que a
# igual especificidad gane la propia (un combo blanco dentro de un contenedor
# transparente). Lo que no encaja (selectores con #id…) se aplica normal.
_HQ_REAL_SET = QWidget.setStyleSheet          # para LLAMARLOS: f(widget, …)
_HQ_REAL_GET = QWidget.styleSheet
# ⚠ Para REPONERLOS hacen falta los descriptores del diccionario de la clase:
# `QWidget.setStyleSheet` devuelve la versión sin enlazar y, reasignada, deja
# de recibir `self` (TypeError en `self.setStyleSheet(…)`, cazado al probar).
_HQ_SET_DESC = QWidget.__dict__["setStyleSheet"]
_HQ_GET_DESC = QWidget.__dict__["styleSheet"]
_HQ_STATE = {"pending": None}
_HQ_ENABLED = True       # interruptor (la prueba compara encendido/apagado)
# Catálogo de la SESIÓN: cada hoja conocida (texto normalizado [+ clase]) →
# su propiedad y sus reglas. Todo cuerpo de Settings NACE con el catálogo en
# su hoja — con el cuerpo aún vacío, ponérsela no cuesta nada —, así que al
# terminar solo hay que agregar lo nuevo, y eso pasa casi solo la primera vez.
# (Ponerla al FINAL, con ~500 controles dentro, costaba 35–50 ms: Qt la
# propaga a todos.)
_HQ_CATALOG = {}
_HQ_TYPES = {}                  # clave → tipos de sus selectores
_HQ_RULES = []
_HQ_BODY_BASE = "#p5sBody { background: transparent; }"


def _hq_body_sheet():
    return "\n".join([_HQ_BODY_BASE,
                      'QWidget[hqt="1"] { background: transparent; }']
                     + _HQ_RULES)


def _hq_norm(s):
    import re as _re
    s = _re.sub(r"/\*.*?\*/", "", s or "", flags=_re.S)
    return " ".join(s.split())


def _hq_hoistable(s):
    n = _hq_norm(s)
    if not n:
        return False
    if "{" not in n:
        return True
    return not any("#" in part.split("{", 1)[0]
                   for part in n.split("}") if "{" in part)


def _hq_set(self, s):
    pend = _HQ_STATE["pending"]
    if pend is not None and _hq_hoistable(s):
        self._hq_pending = s
        pend.append(self)
        return
    if getattr(self, "_hq_pending", None) is not None:
        self._hq_pending = None
    _HQ_REAL_SET(self, s)


def _hq_get(self):
    p = getattr(self, "_hq_pending", None)
    return p if p is not None else _HQ_REAL_GET(self)


def _hq_begin():
    """Empieza a interceptar (False si ya estaba: no se anida)."""
    if not _HQ_ENABLED or _HQ_STATE["pending"] is not None:
        return False
    _HQ_STATE["pending"] = []
    QWidget.setStyleSheet = _hq_set
    QWidget.styleSheet = _hq_get
    return True


def _hq_end(root=None):
    """Deja de interceptar y resuelve lo pendiente: lo de dentro de `root`
    se convierte en reglas de su hoja; lo demás se aplica tal cual."""
    import re as _re
    from PyQt6 import sip
    pend = _HQ_STATE["pending"]
    if pend is None:
        return
    _HQ_STATE["pending"] = None
    setattr(QWidget, "setStyleSheet", _HQ_SET_DESC)
    setattr(QWidget, "styleSheet", _HQ_GET_DESC)
    seen, live = set(), []
    for w in pend:
        if id(w) in seen or sip.isdeleted(w):
            continue
        seen.add(id(w))
        if getattr(w, "_hq_pending", None) is not None:
            live.append(w)

    def _real(w):
        ss = w._hq_pending
        w._hq_pending = None
        _HQ_REAL_SET(w, ss)

    inside = []
    for w in live:
        if root is not None and not sip.isdeleted(root) and (
                w is root or root.isAncestorOf(w)):
            inside.append(w)
        else:
            _real(w)
    if not inside:
        return

    def _kids(w):
        return any(isinstance(c, QWidget) for c in w.children())

    def _only_bg_transparent(body):
        props = [p.strip() for p in body.split(";") if p.strip()]
        return bool(props) and all(
            p.split(":", 1)[0].strip() in ("background", "background-color")
            and p.split(":", 1)[1].strip() == "transparent" for p in props)

    # 1) contenedores transparentes: se marca a ellos y a sus descendientes
    rest, touched = [], []
    for w in inside:
        n = _hq_norm(w._hq_pending)
        if "{" not in n and _kids(w) and _only_bg_transparent(n):
            w._hq_pending = None
            for d in [w] + w.findChildren(QWidget):
                if d.property("hqt") != "1":
                    d.setProperty("hqt", "1")
                    touched.append(d)
        else:
            rest.append(w)
    # 2) hojas propias → reglas ancladas a `hq` (catálogo de la sesión)
    n_rules0 = len(_HQ_RULES)
    for w in rest:
        n = _hq_norm(w._hq_pending)
        kids = _kids(w)
        key = n if "{" not in n else (n, w.metaObject().className())
        tok = _HQ_CATALOG.get(key)
        if tok is None:
            tok = f"h{len(_HQ_CATALOG)}"
            new_rules = []
            ok = True
            types = []
            if "{" not in n:
                ok = not kids           # contenedor con otra cosa: tal cual
                new_rules.append(f'QWidget[hq="{tok}"] {{ {n.rstrip(";")}; }}')
            else:
                for part in n.split("}"):
                    if "{" not in part:
                        continue
                    sel, body = part.split("{", 1)
                    outs = []
                    for one in sel.split(","):
                        one = one.strip()
                        m = _re.match(r"^([A-Za-z_]\w*)(.*)$", one)
                        if not m or not w.inherits(m.group(1)):
                            ok = False
                            break
                        types.append(m.group(1))
                        # El primer compuesto ES el control: la propiedad va
                        # antes de su pseudo-estado o subcontrol.
                        tail = m.group(2)
                        cut = len(tail)
                        for ch in (":", " ", "["):
                            i = tail.find(ch)
                            if 0 <= i < cut:
                                cut = i
                        outs.append(f"{m.group(1)}{tail[:cut]}"
                                    f'[hq="{tok}"]{tail[cut:]}')
                    if not ok:
                        break
                    new_rules.append(f"{', '.join(outs)} {{ {body.strip()} }}")
                # Una hoja con selector de tipo se aplica también a los
                # descendientes de ESE tipo: si los hay (salvo el combo, cuyas
                # reglas de descendientes van explícitas), se queda tal cual.
                if ok and kids and not w.inherits("QComboBox") and any(
                        d.inherits(t) for d in w.findChildren(QWidget)
                        for t in types):
                    ok = False
            if not ok:
                _real(w)
                continue
            _HQ_CATALOG[key] = tok
            _HQ_TYPES[key] = tuple(types)
            _HQ_RULES.extend(new_rules)
        elif "{" not in n and kids:
            _real(w)                    # (la conocida era de un control hoja)
            continue
        elif (kids and not w.inherits("QComboBox") and any(
                d.inherits(t) for d in w.findChildren(QWidget)
                for t in _HQ_TYPES.get(key, ()))):
            _real(w)                    # éste sí tiene descendientes del tipo
            continue
        w._hq_pending = None
        w.setProperty("hq", tok)
        touched.append(w)
    if len(_HQ_RULES) != n_rules0 or _HQ_REAL_GET(root) != _hq_body_sheet():
        _HQ_REAL_SET(root, _hq_body_sheet())     # re-estiliza todo el cuerpo
    else:
        # ⚠ Qt NO re-evalúa el estilo al cambiar una propiedad dinámica. Un
        # control que ya se estilizó durante la construcción (algunos
        # diálogos piden tamaños mientras se arman) se quedaría con el aspecto
        # SIN su regla — cazado por el diff píxel a píxel en Tectonic y
        # Weighted mean. A esos, y solo a esos, se les recalcula.
        _pol = Qt.WidgetAttribute.WA_WState_Polished
        for w in touched:
            if w.testAttribute(_pol):
                st_ = w.style()
                st_.unpolish(w)
                st_.polish(w)


def _migrate_canvas_size_to_aspect(p5cfg):
    """Retiro de "Canvas size (px)" (Ola "E", 2026-09-23, pedido de
    Guillermo): reemplazado por el arrastre de esquinas, que define la
    PROPORCIÓN (aspect_wh) en vez de un tamaño de píxeles absoluto — así el
    lienzo nunca puede salirse del panel. Migra cada vista que aún traiga
    canvas_w/canvas_h a un aspect_wh EQUIVALENTE (reducido a una fracción
    simple) + lock_aspect, y borra los píxeles: no se pierde la FORMA que el
    usuario había elegido, solo la manera de expresarla. Sin versión de
    formato propia: es idempotente (sin canvas_w/canvas_h no hace nada), así
    que corre siempre, no solo por debajo de cierto file_version."""
    from fractions import Fraction
    for sk in ("concordia_style", "wmean_style", "kde_style", "hf_style",
               "biv_style", "me_style", "tect_style", "tibox_style"):
        st = p5cfg.get(sk)
        if not isinstance(st, dict):
            continue
        for vs in (st.get("views") or {}).values():
            if not isinstance(vs, dict):
                continue
            w, h = vs.pop("canvas_w", None), vs.pop("canvas_h", None)
            if not w or not h:
                continue
            try:
                frac = Fraction(int(w), int(h)).limit_denominator(20)
                vs["aspect_wh"] = f"{frac.numerator}:{frac.denominator}"
                vs["lock_aspect"] = True
            except (ValueError, ZeroDivisionError, TypeError):
                pass


# ── Leyendas por RENGLONES (Ola 17 · Paso 5b, 2026-10-06) ─────────────────
# matplotlib reparte las entradas de una leyenda en COLUMNAS de ancho común:
# con una entrada larga (la edad) y tres cortas salían tres arriba y una abajo,
# en un recuadro larguísimo. Aquí la leyenda ya construida se RE-EMPACA por
# renglones —cada uno con las entradas que le toquen—, alineados a la
# izquierda, al centro o a la derecha, y con un ancho mínimo opcional (el del
# recuadro que el usuario fijó). Reusa las cajas internas de la leyenda
# (símbolo + texto), así que sus textos, símbolos, edición y arrastre son los
# de siempre. ⚠ Al cambiar `_legend_box` hay que volver a darle su
# `set_offset(leg._findoffset)` o se dibuja en (0, 0); y el arrastre nativo
# (DraggableLegend) guarda la caja vieja → re-hacerla arrastrable después.
_LEGEND_ALIGNS = ("left", "center", "right")


def _legend_entry_pairs(leg):
    """[(caja del símbolo, caja del texto)] de cada entrada, en su orden. Se
    guardan en la leyenda la primera vez (al re-empacar, las cajas originales
    ya no cuelgan de las columnas de matplotlib)."""
    pairs = getattr(leg, "_zirclock_pairs", None)
    if pairs is not None:
        return pairs
    pairs = []
    try:
        for col in leg._legend_handle_box.get_children():
            for ib in col.get_children():
                kids = list(ib.get_children())
                if len(kids) == 2:
                    pairs.append((kids[0], kids[1]))
    except Exception:
        return []
    leg._zirclock_pairs = pairs
    return pairs


def _legend_item_widths(leg, renderer, align="left"):
    """Ancho en píxeles de cada entrada (símbolo + texto) y la separación
    entre entradas de un mismo renglón."""
    from matplotlib.offsetbox import HPacker
    fs = float(getattr(leg, "_fontsize", 8.0) or 8.0)
    out = []
    for h, t in _legend_entry_pairs(leg):
        kids = [t, h] if align == "right" else [h, t]
        try:
            box = HPacker(pad=0, sep=leg.handletextpad * fs,
                          children=kids, align="baseline")
            out.append(float(box.get_bbox(renderer).width))
        except Exception:
            out.append(0.0)
    try:
        sep = renderer.points_to_pixels(leg.columnspacing * fs)
    except Exception:
        sep = leg.columnspacing * fs
    return out, float(sep)


def _legend_balanced_rows(widths, sep, avail):
    """Reparto en renglones CONTIGUOS (respeta el orden): el menor número de
    renglones en el que todo cabe en `avail` píxeles y, con ese número, el
    reparto cuyo renglón más ancho es el más angosto (en JH-1: la edad sola
    arriba y las otras tres abajo). Si ni una por renglón cabe, una por
    renglón (el texto lo parte quien llame)."""
    n = len(widths)
    if n == 0:
        return []
    pre = [0.0]
    for w in widths:
        pre.append(pre[-1] + w)

    def roww(i, j):
        return pre[j] - pre[i] + sep * (j - i - 1)
    if roww(0, n) <= avail:
        return [list(range(n))]
    inf = float("inf")
    for k in range(2, n + 1):
        best = [[inf] * (n + 1) for _ in range(k + 1)]
        cut = [[0] * (n + 1) for _ in range(k + 1)]
        best[0][0] = 0.0
        for r in range(1, k + 1):
            for j in range(r, n + 1):
                for i in range(r - 1, j):
                    if best[r - 1][i] == inf:
                        continue
                    v = max(best[r - 1][i], roww(i, j))
                    if v < best[r][j] - 1e-9:
                        best[r][j] = v
                        cut[r][j] = i
        if best[k][n] <= avail or k == n:
            rows, j = [], n
            for r in range(k, 0, -1):
                i = cut[r][j]
                rows.append(list(range(i, j)))
                j = i
            return rows[::-1]
    return [[i] for i in range(n)]


def _legend_rows_for(keys, mode, breaks, detached, widths=None, sep=0.0,
                     avail=None, ncol=0):
    """Los renglones (listas de índices) según el modo de la vista:
    "auto" (compacto si hay `avail`; si no, uno por renglón), "one", "all",
    "custom" (empieza renglón en cada clave de `breaks`). Las entradas
    `detached` (llevadas a su propio recuadro) no entran. Con `ncol` ≥ 2 se
    devuelven COLUMNAS (la rejilla de siempre), marcadas con `cols=True`."""
    idx = [i for i, k in enumerate(keys) if k not in set(detached or ())]
    if ncol and ncol >= 2:
        import numpy as _np
        cols = [list(map(int, c)) for c in _np.array_split(idx, ncol)
                if len(c)]
        return cols, True
    if mode == "one":
        return [[i] for i in idx], False
    if mode == "all":
        return ([idx] if idx else []), False
    if mode == "custom":
        brk = set(breaks or ())
        rows = []
        for i in idx:
            if not rows or keys[i] in brk:
                rows.append([i])
            else:
                rows[-1].append(i)
        return rows, False
    if avail is None or widths is None:
        return [[i] for i in idx], False
    sub = _legend_balanced_rows([widths[i] for i in idx], sep, avail)
    return [[idx[j] for j in r] for r in sub], False


def _legend_pack_rows(leg, rows, align="left", width_pt=None, columns=False):
    """Re-empaca la leyenda por renglones (o columnas, con `columns=True`)
    con la alineación pedida; `width_pt` = ancho mínimo del bloque de
    entradas, en puntos (el recuadro fijado a mano). Las entradas que no
    aparezcan en `rows` no se dibujan (su texto queda invisible: así ni se
    pinta ni lo encuentra el doble clic). Devuelve True si pudo."""
    from matplotlib.offsetbox import HPacker, VPacker, DrawingArea
    pairs = _legend_entry_pairs(leg)
    if not pairs:
        return False
    align = align if align in _LEGEND_ALIGNS else "left"
    fs = float(getattr(leg, "_fontsize", 8.0) or 8.0)
    used = set()

    def _item(i):
        h, t = pairs[i]
        try:
            t._text.set_multialignment(align)
        except Exception:
            pass
        kids = [t, h] if align == "right" else [h, t]
        return HPacker(pad=0, sep=leg.handletextpad * fs, children=kids,
                       align="baseline")
    groups = []
    for r in rows:
        its = []
        for i in r:
            if 0 <= i < len(pairs):
                used.add(i)
                its.append(_item(i))
        if its:
            groups.append(its)
    if not groups:
        return False
    try:
        if columns:
            colboxes = [VPacker(pad=0, sep=leg.labelspacing * fs,
                                align=("right" if align == "right"
                                       else "baseline"), children=g)
                        for g in groups]
            block = HPacker(pad=0, sep=leg.columnspacing * fs,
                            align="baseline", children=colboxes)
        else:
            rowboxes = [HPacker(pad=0, sep=leg.columnspacing * fs,
                                align="baseline", children=g)
                        for g in groups]
            block = VPacker(pad=0, sep=leg.labelspacing * fs, align=align,
                            children=rowboxes)
        if width_pt and width_pt > 0:
            # Un separador invisible da el ancho; el bloque se alinea dentro.
            block = VPacker(pad=0, sep=0, align=align,
                            children=[block, DrawingArea(float(width_pt), 0)])
        leg._legend_handle_box = block
        leg._legend_box = VPacker(pad=leg.borderpad * fs,
                                  sep=leg.labelspacing * fs,
                                  align=leg._alignment,
                                  children=[leg._legend_title_box, block])
        leg._legend_box.set_figure(leg.get_figure(root=False))
        leg._legend_box.axes = leg.axes
        leg._legend_box.set_offset(leg._findoffset)
    except Exception:
        return False
    for i, (h, t) in enumerate(pairs):
        try:
            t._text.set_visible(i in used)
        except Exception:
            pass
    leg._zirclock_rows = [list(r) for r in rows]
    leg._zirclock_align = align
    leg._zirclock_columns = bool(columns)
    leg.stale = True
    return True


def _concordia_xy_at(t_ma, is_tw):
    """Punto (x, y) de la concordia a t Ma, en Wetherill (²⁰⁷Pb/²³⁵U,
    ²⁰⁶Pb/²³⁸U) o Tera-Wasserburg (²³⁸U/²⁰⁶Pb, ²⁰⁷Pb/²⁰⁶Pb). Acepta arreglos.
    En TW, t ≤ 0 no existe (²³⁸U/²⁰⁶Pb → ∞): devuelve NaN."""
    import numpy as np
    t = np.asarray(t_ma, dtype=float) * 1.0e6
    e5 = np.expm1(LAMBDA_U235 * t)
    e8 = np.expm1(LAMBDA_U238 * t)
    if not is_tw:
        return e5, e8
    with np.errstate(divide="ignore", invalid="ignore"):
        ok = e8 > 0
        u = np.where(ok, 1.0 / np.where(ok, e8, 1.0), np.nan)
        v = np.where(ok, (e5 / np.where(ok, e8, 1.0)) / U238_U235_RATIO,
                     np.nan)
    return u, v


def _concordia_age_span_in_box(x0, x1, y0, y1, is_tw=False):
    """Ola 17 · L6: el tramo de la concordia que se ve dentro de la región
    [x0, x1] × [y0, y1] (la de un inset). Devuelve (t_min, t_max) en Ma o
    None si la curva no la cruza. Motor PURO.

    En los dos espacios x e y son monótonos con la edad, así que lo que queda
    dentro es UN tramo: se muestrea la curva entre −10 Ma (Wetherill; la
    curva baja de cero para los zircones jóvenes, §131) y 4600 Ma, y los dos
    bordes se afinan por bisección."""
    import numpy as np
    xa, xb = sorted((float(x0), float(x1)))
    ya, yb = sorted((float(y0), float(y1)))

    def inside(t):
        x, y = _concordia_xy_at(t, is_tw)
        return (np.isfinite(x) & np.isfinite(y)
                & (x >= xa) & (x <= xb) & (y >= ya) & (y <= yb))
    ts = np.geomspace(1.0e-4, 4600.0, 8000)
    if not is_tw:
        ts = np.concatenate([np.linspace(-10.0, 0.0, 400), ts])
    m = inside(ts)
    if not m.any():
        return None
    idx = np.flatnonzero(m)
    i0, i1 = int(idx[0]), int(idx[-1])

    def refine(t_in, t_out):
        for _ in range(48):
            mid = 0.5 * (t_in + t_out)
            if bool(inside(mid)):
                t_in = mid
            else:
                t_out = mid
        return t_in
    lo = refine(ts[i0], ts[i0 - 1]) if i0 > 0 else float(ts[i0])
    hi = refine(ts[i1], ts[i1 + 1]) if i1 + 1 < len(ts) else float(ts[i1])
    if hi - lo <= 0:
        return None
    return float(lo), float(hi)


def _repair_out_of_scope_sets(proj):
    """Limpia las celdas "Set" cuya muestra está FUERA del alcance de ese set
    y devuelve cuántas limpió (L16, 2026-10-05).

    Es la regla de siempre (reducir el alcance limpia esas asignaciones,
    decisión de Guillermo del 2026-07-11), aplicada al ABRIR: hasta el arreglo
    de L16, un segundo Apply con Manage Sets abierto no aplicaba nada, y los
    archivos guardados así traen granos asignados a sets que ya no aplican a
    su muestra — y esos granos seguían entrando a las medias de esos sets.
    Pura: trabaja sobre el dict restaurado con SUS propias `dynamic_cols`
    (las celdas están indexadas con ellas)."""
    try:
        names = [c[0] for c in (proj.get("dynamic_cols") or [])]
        col = len(UPB_COLUMNS) + names.index("Set")
    except (ValueError, TypeError, IndexError):
        return 0
    scopes = {}
    for g in proj.get("sets") or []:
        sc = g.get("scope", "all")
        scopes[g.get("name")] = list(sc) if isinstance(sc, list) else "all"
    n = 0
    for s in proj.get("samples") or []:
        for r in s.get("rows") or []:
            cells = r.get("cells") or {}
            v = str(cells.get(col, "") or "").strip()
            sc = scopes.get(v)
            if v and isinstance(sc, list) and s.get("name") not in sc:
                cells[col] = ""
                n += 1
    return n


def _restore_project(d, file_version=None):
    """Reconstruye un dict de proyecto desde su forma JSON (json.loads):
      • las celdas recuperan su clave ENTERA (JSON las guardó como string);
      • dynamic_cols / dynamic_groups vuelven a ser TUPLAS (JSON las hizo listas),
        igual que las crea apply_variables → el resto del código no nota diferencia.
    Tolerante a claves ausentes (defaults de proyecto vacío).

    `file_version` = format_version del archivo; con < 2 se ejecuta la
    migración v2 (§39): purgar los valores FANTASMA de la familia Samples."""
    proj = {
        "samples": [],
        "dynamic_cols": [],
        "dynamic_groups": [],
        "sets": d.get("sets") or [],
        "panel2_config": d.get("panel2_config"),
        "panel4_config": d.get("panel4_config"),
        "panel5_config": d.get("panel5_config"),
        "panel6_config": d.get("panel6_config"),   # §50: lienzo de composición
        "ui_state": d.get("ui_state"),             # Tarea 2: layout de paneles
        # T17 (Ola 2b): catálogo de texturas del proyecto (TODO editable).
        # Archivo sin la clave (pre-catálogo) → se siembra con los defaults.
        # OJO: esta whitelist es explícita — una clave nueva de proyecto que
        # no se agregue aquí se PIERDE en silencio al abrir el .zirclock.
        "texture_catalog": d.get("texture_catalog")
                           or _default_texture_catalog(),
    }
    # 2026-10-08 (Guillermo): "None (single global mean)" se retiró de
    # U-Pb ▸ U-Pb ages — juntar en una sola media los granos de rocas
    # distintas no tiene sentido. Los proyectos que la traían pasan a
    # "Sample" (con una sola muestra activa, la misma media).
    if (isinstance(proj["panel4_config"], dict)
            and proj["panel4_config"].get("wmean_group_means") == "none"):
        proj["panel4_config"]["wmean_group_means"] = "sample"
    # ── Migración v2 (§39): en archivos v1, las pestañas con la familia
    # "Samples" OCULTA (hf/ti/kde/wmean/concordia) guardaron color_by="set" y
    # compañía sin que el usuario pudiera elegirlo (el patrón type-aware de §30
    # escribe los valores iniciales de lo oculto). Se purgan para que aplique la
    # identidad por muestra (default nuevo).
    if (file_version or 1) < 2 and isinstance(proj["panel5_config"], dict):
        for _sk in ("hf_style", "tibox_style", "kde_style", "wmean_style",
                    "concordia_style"):
            _st = proj["panel5_config"].get(_sk)
            if isinstance(_st, dict):
                for _pk in ("color_by", "sample_styles", "legend_samples"):
                    _st.pop(_pk, None)
        # Bivariate/Tectonic (familia VISIBLE): solo se resetea el ESQUEMA
        # color_by al nuevo default "sample" (decisión 2026-07-10: la identidad
        # global aplica PAREJA en todos los gráficos; quien quiera por-set lo
        # re-elige en Settings). Los overrides per-muestra (sample_styles) y
        # legend_samples SÍ son elecciones del usuario → se conservan.
        for _sk in ("biv_style", "tect_style"):
            _st = proj["panel5_config"].get(_sk)
            if isinstance(_st, dict):
                _st.pop("color_by", None)
    # v3 (§39 Stage 4): hf_style/tibox_style se EXPUSIERON ahora → un color_by
    # guardado en un archivo v2 es fantasma (la familia estaba oculta cuando se
    # guardó). Se purga para que aplique el default por-muestra; quien quiera
    # por-set lo re-elige en el Settings (ya visible).
    if (file_version or 1) < 3 and isinstance(proj["panel5_config"], dict):
        for _sk in ("hf_style", "tibox_style"):
            _st = proj["panel5_config"].get(_sk)
            if isinstance(_st, dict):
                _st.pop("color_by", None)
    # ── Migración v4 (Ola 3 / T19): estado de vista plano → por clave de vista.
    if (file_version or 1) < 4 and isinstance(proj["panel5_config"], dict):
        _migrate_p5_views_v4(proj["panel5_config"])
    # ── Migración v5 (Ola 4 / §43): símbolo/opacidad por set del spider
    # (me_set_styles, LOCAL) → CANÓNICOS en project["sets"] (Manage Sets ▸
    # Style…). No pisa un estilo canónico ya presente.
    if (file_version or 1) < 5 and isinstance(proj["panel5_config"], dict):
        _mss = proj["panel5_config"].pop("me_set_styles", None) or {}
        if _mss:
            for _g in proj["sets"]:
                _st5 = _mss.get(_g.get("name")) or {}
                if _st5.get("marker") and not _g.get("marker"):
                    _g["marker"] = _st5["marker"]
                if _st5.get("alpha") is not None and _g.get("alpha") is None:
                    _g["alpha"] = _st5["alpha"]
    # ── Migración v6 (§79): el Settings pasa a ser POR DIAGRAMA en las claves
    # propias de la variante (ejes, rangos, notación, título, grid,
    # proporciones). Lo que había plano era, de hecho, la configuración del
    # diagrama que el usuario tenía a la vista al guardar → se MUEVE a la
    # entrada de ESA variante y se BORRA del plano. Consecuencia buscada: el
    # diagrama activo se ve exactamente igual que antes al reabrir, y las otras
    # variantes arrancan limpias (en sus defaults) en vez de heredar ajustes
    # pensados para otro gráfico.
    if (file_version or 1) < 6 and isinstance(proj["panel5_config"], dict):
        _p5c6 = proj["panel5_config"]
        for _sk6 in ("concordia_style", "hf_style", "kde_style",
                     "biv_style", "tect_style"):
            _st6 = _p5c6.get(_sk6)
            if not isinstance(_st6, dict):
                continue
            _moved = {k: _st6.pop(k) for k in list(_P5_VIEW_STYLE_KEYS)
                      if k in _st6}
            if not _moved:
                continue
            _vk6 = _p5_view_key_for(_p5c6, _sk6)
            _v6 = _st6.setdefault("views", {}).setdefault(_vk6, {})
            for _k6, _val6 in _moved.items():
                _v6.setdefault(_k6, _val6)
    if isinstance(proj["panel5_config"], dict):
        _migrate_canvas_size_to_aspect(proj["panel5_config"])
        _migrate_sbs_label_positions(proj["panel5_config"])
        _migrate_sbs_own_content(proj["panel5_config"])
        _ensure_kde_stack_own(proj["panel5_config"])     # paso 8
        _purge_legacy_text_edits(proj["panel5_config"])
        _migrate_tibox_sample_views(
            proj["panel5_config"],
            [s.get("name") for s in (d.get("samples") or [])])
    for s in (d.get("samples") or []):
        rows = []
        for r in (s.get("rows") or []):
            row = dict(r)
            row["cells"] = {int(k): v
                            for k, v in (r.get("cells") or {}).items()}
            # Ola 17 · L18 (decisión de Guillermo): las casillas de las
            # tablas arrancan VACÍAS al abrir — también encienden análisis en
            # Panel 5, y un halo olvidado acabaría en una figura exportada.
            row["selected"] = False
            rows.append(row)
        samp = dict(s)
        samp["rows"] = rows
        proj["samples"].append(samp)
    for c in (d.get("dynamic_cols") or []):
        # c = [header, width, widget_info]; widget_info = None | [type, payload]
        wi = c[2] if len(c) > 2 else None
        if isinstance(wi, list):
            wi = tuple(wi)
        proj["dynamic_cols"].append((c[0], c[1], wi))
    for g in (d.get("dynamic_groups") or []):
        proj["dynamic_groups"].append((g[0], list(g[1])))
    # M16: catálogo de texturas 1 → 2 (nombres, descripciones, dos nuevas).
    # Aquí, con las celdas y las columnas ya reconstruidas.
    _migrate_texture_catalog_v2(proj)
    return proj


def _plain_log_formatter(v, _pos):
    """Etiqueta de tick en escala log como DECIMAL plano (0.001, 1, 1000) en vez
    de la notación 10ⁿ (§6.1). Sirve para ticks MAYORES y MENORES: un menor en
    esta notación es un decimal más (0.2, 0.5), sin nada especial."""
    import math
    if v <= 0:
        return ""
    e = int(math.floor(math.log10(v) + 1e-9))
    if e >= 0:
        return f"{v:.0f}"
    # Un tick MENOR no es potencia de 10 (0.02, 0.5): hacen falta los decimales
    # de su propia magnitud, no los del exponente pelado.
    return f"{v:.{max(0, -e)}f}".rstrip("0").rstrip(".") or f"{v:g}"


def _minor_log_formatter_for(fmt):
    """Formateador de los ticks MENORES de un eje log, en la MISMA notación que
    los mayores.

    Bug reportado por Guillermo (2026-09-21): en un sub-plot de la pila cuyo
    rango sólo contenía UNA potencia de 10 dentro de la vista (Th/U de JH1,
    0.017–0.76 → sólo el 0.1), matplotlib compensaba rotulando los secundarios
    — y lo hacía con SU formateador, no con el nuestro, porque
    `_apply_axes_style` sólo fijaba el MAYOR. Resultado medido: con "Exponent"
    el mismo eje mezclaba `−2, −1, 0` con `2×10⁻², 3×10⁻²`, dos notaciones
    incompatibles; con "Plain", `0.01` junto a `2×10⁻²`.

    Devuelve un formateador que respeta la notación y además rotula SÓLO los
    múltiplos 2 y 5 (la convención de las figuras publicadas). En notación de
    exponente no se rotula ninguno: el eje habla en log₁₀ y un "2×10⁻²" no
    tiene exponente entero que escribir."""
    import math

    def _f(v, _pos):
        if v <= 0:
            return ""
        _m = v / (10.0 ** math.floor(math.log10(v) + 1e-9))
        if not any(abs(_m - k) < 0.05 for k in (2.0, 5.0)):
            return ""
        if fmt == "exponent":
            return ""
        if fmt == "plain":
            return _plain_log_formatter(v, _pos)
        _e = int(math.floor(math.log10(v) + 1e-9))
        return f"$\\mathdefault{{{round(_m):g}\\times10^{{{_e}}}}}$"
    return _f


def _exponent_log_formatter(v, _pos):
    """Etiqueta de tick en escala log como el EXPONENTE pelón (−3, −2, −1, 0),
    la convención "log₁₀ (Nb/Yb)" (§78).

    El eje sigue siendo LOGARÍTMICO —la geometría del gráfico no cambia en
    absoluto—; lo único que cambia es cómo se rotula. Es la notación de la
    Fig. 11 de Grimes et al. (2015) y de muchas revistas, y permite replicar
    esas figuras sin re-calcular nada. Ojo: quien la active debe ver también
    el rótulo del eje envuelto en `log₁₀ (…)`, o la figura miente (una razón
    no puede valer −2) — de eso se encarga _apply_axes_style.

    Solo ticks MAYORES (potencias de 10). Usa el signo menos tipográfico
    (U+2212), como matplotlib en su notación científica."""
    import math
    if v <= 0:
        return ""
    e = int(round(math.log10(v)))
    return f"−{abs(e)}" if e < 0 else f"{e}"


class _CollapsibleHeader(QPushButton):
    """Header de sección colapsable (§Ola7 micro-efectos): QPushButton sin
    borde estilizado como label que además PINTA un chevron a la izquierda del
    texto y lo ROTA de forma animada al expandir/contraer. La rotación vive en
    la Qt property `arrow_rotation` (0° = ▸ colapsado / apunta a la derecha;
    90° = ▾ expandido / apunta abajo) para que QPropertyAnimation la interpole
    suave. Antes la flecha era un glifo ▸/▾ que se cambiaba de golpe."""
    _ARROW_PAD = 15   # px reservados a la izquierda para la flecha (padding-left)

    def __init__(self, text, accent, parent=None):
        super().__init__(text, parent)
        self._arrow_rotation = 0.0
        self._accent = accent
        self._base_accent = accent      # para volver del atenuado (set_dimmed)
        self._dimmed = False

    def get_arrow_rotation(self):
        return self._arrow_rotation

    def set_arrow_rotation(self, value):
        self._arrow_rotation = float(value)
        self.update()

    arrow_rotation = pyqtProperty(float, get_arrow_rotation, set_arrow_rotation)

    def set_dimmed(self, dimmed):
        """Atenúa el header SIN deshabilitarlo (pedido de Guillermo,
        2026-09-22): antes, grisear una sección colapsable por modo la hacía
        además INCOLAPSABLE — `setEnabled(False)` en el contenedor apaga
        también este QPushButton, que deja de recibir clics — así que no se
        podía ni siquiera desplegarla para ver qué había dentro. Ahora el
        header se queda SIEMPRE clicable; solo cambia de color (el mismo tono
        de la regla `:disabled` de siempre). Quien deshabilita de verdad las
        opciones que no aplican es el CONTENIDO (`content.setEnabled`),
        aparte — eso sí debe seguir sin responder."""
        if dimmed == self._dimmed:
            return
        self._dimmed = dimmed
        self._accent = THEME['text_disabled'] if dimmed else self._base_accent
        self.setStyleSheet(f"""
            QPushButton {{
                color: {self._accent}; font-size: 12px; font-weight: bold;
                background: transparent; border: none;
                text-align: left; padding: 2px 0px 2px 15px;
            }}
            QPushButton:hover {{ color: {THEME['text_disabled'] if dimmed
                                         else THEME['accent_hover']}; }}
        """)
        self.update()

    def paintEvent(self, event):
        # El texto + el hover los pinta el QPushButton normal (con padding-left
        # que deja hueco a la flecha); encima dibujamos el chevron rotado.
        super().paintEvent(event)
        from PyQt6.QtGui import QPainter, QPolygonF, QColor
        from PyQt6.QtCore import QPointF
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.translate(self._ARROW_PAD / 2.0 + 1.0, self.height() / 2.0)
        p.rotate(self._arrow_rotation)
        s = 3.4
        tri = QPolygonF([QPointF(-s * 0.7, -s),
                         QPointF(s * 0.95, 0.0),
                         QPointF(-s * 0.7, s)])
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(self._accent))
        p.drawPolygon(tri)
        p.end()


def _draw_app_icon_pixmap(S=256):
    """Ícono de la app dibujado en código, parametrizado por tamaño (geometría
    fraccional → escala limpia). Fuente ÚNICA de verdad, sin archivo externo:
    lo usan el QIcon de la ventana (_make_app_icon), el generador de .icns
    (packaging/make_icns.py, §74), el de .ico (make_ico.py, §82) y el logo del
    README. Requiere QApplication vivo (QPixmap).

    Ola 15b (2026-09-20, diseño elegido por Guillermo sobre cuatro variantes):
    zircón con el NÚCLEO magmático en ámbar zonado dentro de un borde
    recristalizado gris, y la curva de concordia cruzando POR DELANTE. La curva
    va perfilada en blanco porque sobre el ámbar, a pelo, se pierde. A 16 px la
    curva casi desaparece —medido— y lo que identifica es el cristal ámbar; por
    eso el cristal manda en la composición y no al revés.

    2026-09-29 (pedido de Guillermo): el núcleo pasa del ámbar al AZUL del
    programa (la zona exterior es el acento del tema, #2563EB), más acorde
    con el resto de la interfaz. La curva conserva su perfil blanco, que es
    lo que la separa del núcleo ahora que los dos son azules."""
    RIM_FILL, RIM_EDGE = "#C6CEDA", "#5C6B80"
    CORE = ("#2563EB", "#4F8BF0", "#9DC2F9")   # zonas del núcleo, fuera→dentro
    CURVE = "#1F5FA8"

    def hexa(w, h, pyr=0.22):
        yt, yb = -h / 2, h / 2
        return QPolygonF([
            QPointF(0, yt), QPointF(w / 2, yt + h * pyr),
            QPointF(w / 2, yb - h * pyr), QPointF(0, yb),
            QPointF(-w / 2, yb - h * pyr), QPointF(-w / 2, yt + h * pyr)])

    def curve_path():
        path = QPainterPath(QPointF(0.02 * S, 0.88 * S))
        path.cubicTo(QPointF(0.34 * S, 0.80 * S), QPointF(0.56 * S, 0.44 * S),
                     QPointF(0.98 * S, 0.12 * S))
        return path

    pm = QPixmap(S, S)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    p.save()
    p.translate(S / 2, S / 2)
    p.setBrush(QColor(RIM_FILL))
    _pen = QPen(QColor(RIM_EDGE))
    _pen.setWidthF(S * 0.05)
    _pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
    p.setPen(_pen)
    p.drawPolygon(hexa(S * 0.46, S * 0.92))
    for i, col in enumerate(CORE):
        _s = 0.66 - i * 0.19
        p.setBrush(QColor(col))
        p.setPen(QPen(QColor(col).darker(115), S * 0.012))
        p.drawPolygon(hexa(S * 0.46 * _s, S * 0.92 * _s))
    p.restore()
    for _col, _w in ((QColor("#FFFFFF"), 0.085), (QColor(CURVE), 0.05)):
        _pen = QPen(_col)
        _pen.setWidthF(S * _w)
        _pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(_pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(curve_path())
    p.end()
    return pm


def _app_settings():
    """Configuración persistente de la app (recientes, secciones plegables).

    2026-09-27 (reporte de Guillermo: Welcome ya no le mostraba su proyecto
    más reciente): las PRUEBAS abren y guardan proyectos, y escribían en la
    MISMA lista de recientes que la app real — UHT_Xenoliths, SJuárez y
    archivos temporales empujaban fuera a SJC new-2026. Con la variable de
    entorno ZIRCLOCK_SETTINGS_ORG (la fija tests/_harness.py) usan un ámbito
    aparte y no tocan las preferencias del usuario.

    2026-10-19 (renombre a ZirClock, v3.0): la primera vez que el ámbito nuevo
    está VACÍO se copian TODAS las claves del de Chronikon (recientes,
    secciones plegadas, colores de muestras), para que el renombre no le borre
    las preferencias a nadie. Una sola vez por sesión: después ya hay claves."""
    global _SETTINGS_MIGRATED
    _t = os.environ.get("ZIRCLOCK_SETTINGS_ORG")
    st = QSettings(_t or "ZirClock", "ZirClock")
    if not _SETTINGS_MIGRATED:
        _SETTINGS_MIGRATED = True
        try:
            # ⚠ macOS: con los "fallbacks" de QSettings (encendidos por
            # omisión) allKeys() incluye también las preferencias GLOBALES del
            # sistema (NSGlobalDomain: idioma, trackpad… ~70 claves) → el
            # ámbito nuevo nunca parecía vacío y la copia no corría (y si
            # corriera, las copiaría). Se miran SOLO las claves propias.
            st.setFallbacksEnabled(False)
            if not st.allKeys():
                old = (QSettings(_t + "_Chronikon", "Chronikon") if _t
                       else QSettings("Chronikon", "Chronikon"))
                old.setFallbacksEnabled(False)
                for k in old.allKeys():
                    st.setValue(k, old.value(k))
        except Exception:
            pass
        st.setFallbacksEnabled(True)
    return st


_SETTINGS_MIGRATED = False


def _legacy_settings():
    # Donde vivían los recientes con el nombre anterior del programa (hasta
    # la v1.3); en pruebas, un ámbito aparte también.
    _t = os.environ.get("ZIRCLOCK_SETTINGS_ORG")
    return (QSettings(_t + "_Zirchron", "Zirchron") if _t
            else QSettings("Zirchron", "Zirchron"))


class _P5InlineTextEditor(QPlainTextEdit):
    """Recuadro de edición de un texto del gráfico (2026-09-26): aparece
    sobre el texto con el cursor parpadeando. Enter = nueva línea (pedido de
    Guillermo); ⌘/Ctrl+Enter o clic fuera = aceptar; Esc = cancelar. Crece
    con el texto. Acepta cualquier carácter (y el mathtext de matplotlib,
    p. ej. $^{206}$Pb)."""

    def __init__(self, canvas, text, pos, font_px, family, on_commit):
        super().__init__(canvas)
        self._on_commit = on_commit
        self._done = False
        self._pos = pos
        self.setPlainText(text)
        fam = f"font-family: '{family}';" if family else ""
        self.setStyleSheet(
            "QPlainTextEdit { background: white; color: #1a1a1a; "
            f"border: 1.5px solid {THEME['accent']}; border-radius: 3px; "
            f"padding: 1px 3px; font-size: {font_px:.0f}px; {fam} }}")
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setHorizontalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setLineWrapMode(QPlainTextEdit.LineWrapMode.NoWrap)
        self.setToolTip("Enter = new line · ⌘/Ctrl+Enter or click outside = "
                        "done · Esc = cancel")
        self.document().contentsChanged.connect(self._autosize)
        self._autosize()
        self.show()
        self.raise_()
        self.setFocus()
        self.selectAll()

    def _autosize(self):
        fm = self.fontMetrics()
        lines = self.toPlainText().split("\n") or [""]
        w = max(fm.horizontalAdvance(ln) for ln in lines) + 26
        h = len(lines) * fm.lineSpacing() + 14
        par = self.parentWidget()
        w = max(70, min(w, par.width() - 4 if par else w))
        x = min(max(0, self._pos.x()), max(0, (par.width() if par else w) - w))
        y = min(max(0, self._pos.y()),
                max(0, (par.height() if par else h) - h))
        self.setGeometry(int(x), int(y), int(w), int(h))

    def keyPressEvent(self, e):
        if e.key() == Qt.Key.Key_Escape:
            self.finish(False)
            return
        if (e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter)
                and e.modifiers() & (Qt.KeyboardModifier.ControlModifier
                                     | Qt.KeyboardModifier.MetaModifier)):
            self.finish(True)
            return
        super().keyPressEvent(e)

    def focusOutEvent(self, e):
        super().focusOutEvent(e)
        self.finish(True)

    def finish(self, ok):
        if self._done:
            return
        self._done = True
        txt = self.toPlainText()
        self.hide()
        self.deleteLater()
        if ok:
            self._on_commit(txt)


class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        # M11: los rótulos de los íconos se leen ANTES de armar los paneles.
