        _kd_al = QLineEdit("" if cfg.get("kde_dots_alpha") is None
                           else f"{float(cfg.get('kde_dots_alpha')):g}")
        _kd_al.setPlaceholderText("0.85" if _is_rad else "0.4")
        _kd_al.setFixedWidth(50)
        _kd_al.setToolTip("0 = invisible, 1 = opaque (empty = 0.85 in the "
                          "radial plot, 0.4 in the age distribution).")
        for _w_ in (_kd_sz_cap, _kd_sz, _kd_al_cap, _kd_al):
            _kdl_row.addWidget(_w_)
        _kdl_row.addStretch(1)
