    def on_trace_toggled(self, checked):
        color = "#1a2a3a" if checked else "#9ab0c8"
        for cb in self.trace_checkboxes.values():
            cb.setEnabled(checked)
            cb.setStyleSheet(f"QCheckBox {{ font-size:11px; color:{color}; }} QCheckBox::indicator {{ width:11px; height:11px; }}")
        self.trace_se_check.setEnabled(checked)
        self.trace_se_check.setStyleSheet(f"QCheckBox {{ font-size:11px; color:{color}; }}")
        # Sub-bloque "Th input mode" (Paquete 3c): sigue el estado de Trace Elements
        if hasattr(self, "th_mode_widget"):
            self.th_mode_widget.setEnabled(checked)
        self._update_negative_values_visibility()
        self._refresh_panel4_domain_buttons()

    @staticmethod
    def _row_has_upb_cells(cells):
        """¿La fila trae ALGÚN dato U-Pb (razones, ±2se, Rho, edades, Disc%;
        columnas 2–15)?"""
        for c in range(2, len(UPB_COLUMNS)):
            v = cells.get(c, "")
            if isinstance(v, str) and v.strip():
                return True
        return False

    def _upb_is_active(self):
        """¿Hay geocronología U-Pb en el proyecto? Desde 2026-09-30 no es un
        interruptor sino un HECHO de los datos: True si alguna fila de una
        muestra activa trae datos U-Pb — o si todavía no hay datos (un
        proyecto vacío muestra todo). False = proyecto de química o isotopía
        sin U-Pb (el caso Oaxaquia, §18)."""
        proj = (getattr(self, "projects", None) or {}).get(
            getattr(self, "current_project", None))
        if not proj:
            return True
        any_rows = False
        for smp in proj.get("samples", []):
            if not smp.get("active", True):
                continue
            for row in smp.get("rows", []):
                cells = row.get("cells") or {}
                if not any(isinstance(v, str) and v.strip()
                           for v in cells.values()):
                    continue
                any_rows = True
                if self._row_has_upb_cells(cells):
                    return True
        return not any_rows

    def _t1_filled_headers(self):
        """Encabezados de las columnas DINÁMICAS de Tabla 1 que traen algún
        dato en una muestra activa (2026-09-30: la tabla nace completa, así
        que "existe la columna" ya no quiere decir "hay datos")."""
        proj = (getattr(self, "projects", None) or {}).get(
            getattr(self, "current_project", None))
        dyn = getattr(getattr(self, "data_table", None), "dynamic_cols",
                      None) or []
        if not proj or not dyn:
            return set()
        # 2026-10-14 (lag al abrir Settings): recorría TODAS las celdas en
        # cada llamada —8 por Settings, ~100 ms en UHT—; ahora una vez por
        # versión de la Tabla 1.
        _key = self._t1_data_key(proj, dyn)
        _c = self.__dict__.get("_t1_filled_cache")
        if _c is not None and _c[0] == _key:
            return set(_c[1])
        n_fixed = len(UPB_COLUMNS)
        by_col = {n_fixed + i: h for i, (h, _w, _x) in enumerate(dyn)}
        found = set()
        for smp in proj.get("samples", []):
            if not smp.get("active", True):
                continue
            for row in smp.get("rows", []):
                for c, v in (row.get("cells") or {}).items():
                    h = by_col.get(c)
                    if (h is not None and h not in found
                            and isinstance(v, str) and v.strip()):
                        found.add(h)
        self.__dict__["_t1_filled_cache"] = (_key, frozenset(found))
        return found

    def _t1_data_key(self, proj, dyn):
        """Huella barata de "qué hay en la Tabla 1": cambia con cada edición
        de datos (`_t1_gen`, lo sube `calc_results_stale` y la captura de la
        tabla viva), con el proyecto, las columnas y, por muestra, si está
        activa y cuántas filas tiene."""
        return (getattr(self, "current_project", None), id(proj),
                self.__dict__.get("_t1_gen", 0), id(dyn), len(dyn),
                tuple((s.get("name"), bool(s.get("active", True)),
                       len(s.get("rows", [])))
                      for s in proj.get("samples", [])))

    def _ti_has_data(self):
        """¿Hay Ti (ppm) en alguna fila de una muestra activa? Desde
        2026-09-30 la termometría no tiene interruptor: se calcula si hay
        con qué (y la muestra tiene P, aTiO₂ y aSiO₂)."""
        return "Ti" in self._t1_filled_headers()

    def _hf_has_data(self):
        """¿Alguna fila de una muestra activa trae datos Hf? (2026-09-30: el
        bloque Hf de Tabla 2 ya no depende de un interruptor.)"""
        proj = (getattr(self, "projects", None) or {}).get(
            getattr(self, "current_project", None))
        dyn = getattr(getattr(self, "data_table", None), "dynamic_cols",
                      None) or []
        if not proj or not dyn:
            return False
        _key = self._t1_data_key(proj, dyn)          # (2026-10-14, caché)
        _c = self.__dict__.get("_hf_data_cache")
        if _c is not None and _c[0] == _key:
            return _c[1]
        n_fixed = len(UPB_COLUMNS)
        idx = [n_fixed + i for i, (h, _w, _x) in enumerate(dyn)
               if h in HF_T1_DATA_HEADERS]
        found = False
        for smp in proj.get("samples", []) if idx else []:
            if not smp.get("active", True):
                continue
            for row in smp.get("rows", []):
                cells = row.get("cells") or {}
                for c in idx:
                    v = cells.get(c, "")
                    if isinstance(v, str) and v.strip():
                        found = True
                        break
                if found:
                    break
            if found:
                break
        self.__dict__["_hf_data_cache"] = (_key, found)
        return found

    def _apply_upb_column_visibility(self):
        """2026-09-30: Tabla 1 siempre completa — razones Y edades U-Pb a la
        vista (antes el modo escondía unas u otras y U-Pb apagado las
        escondía todas). La preferencia de qué gana cuando una fila trae las
        dos vive en el ⚙ de Tabla 1. Lo que se esconde ahora (grupos
        plegados, ±2se) lo decide `_apply_t1_column_visibility`."""
        self._apply_t1_column_visibility()

    # ── Grupos plegables de Tabla 1 (2026-09-30) ───────────────────────────
    def _t1_families(self):
        """{familia: [columnas]} de Tabla 1 (ver _T1_FOLD_FAMILY)."""
        fams = {"ratios": list(range(2, 9)), "ages": list(range(9, 16))}
        for label, idxs in (getattr(self, "_last_dynamic_groups", None) or []):
            f = _T1_FOLD_FAMILY.get(label)
            if f:
                fams.setdefault(f, []).extend(idxs)
        return fams

    def _t1_filled_cols(self):
        """Columnas de Tabla 1 con algún dato en una muestra activa."""
        proj = (getattr(self, "projects", None) or {}).get(
            getattr(self, "current_project", None))
        found = set()
        if not proj:
            return found
        for smp in proj.get("samples", []):
            if not smp.get("active", True):
                continue
            for row in smp.get("rows", []):
                for c, v in (row.get("cells") or {}).items():
                    if c not in found and isinstance(v, str) and v.strip():
                        found.add(c)
        return found

    def _t1_folded(self):
        """(familias plegadas, {familia: columnas}). Manda lo que el usuario
        eligió con un clic; si no eligió, se pliega la que no tiene datos —
        salvo que el proyecto aún no tenga NINGÚN dato (tabla nueva: todo a
        la vista para capturar a mano) o que el plegado automático esté
        apagado en el ⚙ de Tabla 1."""
        fams = self._t1_families()
        filled = self._t1_filled_cols()
        user = getattr(self, "_t1_fold_user", None) or {}
        auto = (getattr(self, "_t1_auto_fold", True)
                and bool(filled - {0, 1}))
        out = set()
        for f, cols in fams.items():
            if f in user:
                if user[f]:
                    out.add(f)
            elif auto and not (set(cols) & filled):
                out.add(f)
        return out, fams

    def _apply_t1_column_visibility(self):
        """Qué columnas de Tabla 1 se ven: las de un grupo plegado quedan en
        UNA franja angosta (para poder desplegarlo con un clic en la banda) y
        las ±2se de las trazas se esconden si así se eligió en el ⚙."""
        t = getattr(self, "data_table", None)
        if t is None:
            return
        n = t.columnCount()
        folded, fams = self._t1_folded()
        hide, stubs = set(), {}
        for f in folded:
            cols = sorted(c for c in fams.get(f, []) if c < n)
            if not cols:
                continue
            stubs[f] = cols[0]
            hide.update(cols[1:])
        if not getattr(self, "_t1_show_se", False):
            trace_cols = set(fams.get("trace", []))
            n_fixed = len(UPB_COLUMNS)
            for i, (h, _w, _x) in enumerate(getattr(t, "dynamic_cols", [])
                                            or []):
                if (n_fixed + i) in trace_cols and h.startswith("±2se"):
                    hide.add(n_fixed + i)
        stub_cols = set(stubs.values())
        old = set(getattr(t, "_fold_stub_cols", ()) or ())
        saved = getattr(t, "_fold_saved_width", None)
        if saved is None:
            saved = t._fold_saved_width = {}
        f = getattr(t, "_zoom_factor", 1.0) or 1.0
        base = getattr(t, "_base_column_widths", None)
        for c in old - stub_cols:                # vuelve a su ancho
            if c >= n:
                saved.pop(c, None)
                continue
            w = (round(base[c] * f) if base and c < len(base)
                 else saved.get(c, 60))
            saved.pop(c, None)
            t.setColumnWidth(c, max(8, w))
        for c in stub_cols - old:
            saved.setdefault(c, t.columnWidth(c))
        t._fold_stub_cols = stub_cols
        for c in range(2, n):
            if t.isColumnHidden(c) != (c in hide):
                t.setColumnHidden(c, c in hide)
        for c in stub_cols:
            t.setColumnWidth(c, max(8, round(_T1_STUB_W * f)))
        gh = getattr(self, "group_header", None)
        if gh is not None:
            gh.folded = stubs
            gh.update()
        t.viewport().update()

    def _toggle_t1_family(self, fam):
        """Clic en la banda de Tabla 1: pliega o despliega esa familia. Se
        recuerda con el proyecto (lo elegido a mano gana al automático)."""
        folded, _f = self._t1_folded()
        user = dict(getattr(self, "_t1_fold_user", None) or {})
        user[fam] = fam not in folded
        self._t1_fold_user = user
        self._apply_t1_column_visibility()
        self._mark_dirty()
        self._p2_mark_applied()

    def _apply_panel5_upb_visibility(self):
        """
        HfIn-2c: oculta las pestañas Concordia y Weighted Mean de Panel 5
        cuando el dominio U-Pb está OFF (son 100% geocronología U-Pb → no
        aplican sin ella). Reaparecen al reactivar U-Pb. Usa indexOf sobre
        los widgets guardados (robusto si el orden de pestañas cambia).
        """
        if not hasattr(self, "panel5_tabs"):
            return
        visible = self._upb_is_active()
        for w in (getattr(self, "_concordia_tab_widget", None),
                  getattr(self, "_wmean_tab_widget", None)):
            if w is None:
                continue
            idx = self.panel5_tabs.indexOf(w)
            if idx >= 0:
                self.panel5_tabs.setTabVisible(idx, visible)
        self._p5_sync_tab_combos()      # el desplegable lista las visibles

    def _sync_hf_age_manual_for_upb(self):
        """
        HfIn-2a: con U-Pb OFF no hay edad interna que usar para Hf → la edad
        para Hf se FUERZA a manual (checkbox ON + bloqueado). Al reactivar
        U-Pb se libera (vuelve editable, conservando el último estado).
        """
        # 2026-09-30: sin efecto — la edad para Hf se decide fila por fila
        # (la del grano si tiene U-Pb; si no, la de 'Age for Hf'), y la
        # preferencia vive en Hf ▸ Calculations.
        return

    def on_upb_active_toggled(self, checked):
        """
        HfIn-2a: activar/desactivar el dominio U-Pb (Panel 2). Aplica la
        visibilidad de columnas (inmediato, como el cambio de modo U-Pb),
        deshabilita el selector de modo cuando OFF, y fuerza la edad para Hf
        a manual. La columna 'Age for Hf' se agrega/quita en el próximo
        Apply Variables (convención de Panel 2).
        """
        if hasattr(self, "upb_mode_widget"):
            self.upb_mode_widget.setEnabled(checked)
        self._apply_upb_column_visibility()
        self._sync_hf_age_manual_for_upb()
        self._apply_panel5_upb_visibility()
        self.calc_results_stale = True
        msg = ("U-Pb Geochronology enabled — press Apply to update "
               "Table 1."
               if checked else
               "U-Pb Geochronology disabled — project runs without "
               "geochronology. The age for Hf is now manual; press Apply "
               "to update Table 1.")
        self.statusBar().showMessage(msg, 6000)

    def _on_upb_mode_changed(self):
        """
        Sincroniza UI cuando cambia el modo U-Pb (3e.1.b).
        
        Modo MANUAL (default):
          - Cols 9-15 de Tabla 1 visibles (edades + ±2se + Disc%).
        Modo CALCULATE:
          - Cols 9-15 de Tabla 1 ocultas. Los datos persisten en el modelo
            (rebuild_table no las borra) — si el usuario vuelve a MANUAL,
            los valores reaparecen.
        
        Opción A del plan 3e.1.b: NO llamamos a apply_variables. Ocultar
        columnas no destruye datos, así que no hay riesgo de Data Loss y
        el cambio es inmediato. Esto rompe el patrón general "los cambios
        de Panel 2 se materializan con Apply Variables" como excepción
        consciente.
        
        Status bar avisa si hay datos ocultos para que el usuario no los
        pierda de vista.
        """
        if not hasattr(self, "upb_mode_radio_group") or not hasattr(self, "data_table"):
            return
        mode = self.upb_mode_radio_group.checkedId()
        is_calculate = (mode == UPB_MODE_CALCULATE)

        # Ocultar/mostrar cols 9-15 sin tocar el modelo de datos
        self._apply_upb_column_visibility()

        # Aviso en status bar. Refleja qué cambió visualmente en Tabla 1,
        # sin afirmar nada sobre qué se va a calcular: con el fallback
        # automático activado, una fila en cualquiera de los dos modos
        # puede calcularse desde ratios o desde edades según qué columnas
        # tenga llenas.
        if is_calculate:
            n_with_ages = self._count_rows_with_age_data()
            if n_with_ages > 0:
                self.statusBar().showMessage(
                    f"Age columns hidden in Table 1 ({n_with_ages} row(s) "
                    f"still contain age data — preserved for fallback "
                    f"or for switching back to manual mode).",
                    6000,
                )
            else:
                self.statusBar().showMessage(
                    "Age columns hidden in Table 1.", 4000
                )
        else:
            self.statusBar().showMessage(
                "Age columns visible in Table 1.", 4000
            )

    def _count_rows_with_age_data(self):
        """
        Cuenta filas en el proyecto activo que tienen al menos una celda con
        datos en las cols 9-15 (edades, ±2se, Disc%). Usado para avisar al
        usuario cuántos datos quedan ocultos al cambiar a modo CALCULATE.
        
        Lee directamente del modelo (sample["rows"]) sin tocar la tabla viva,
        para no necesitar _capture_table_into_samples (que es costoso).
        Aquí asumimos que cualquier dato sin guardar ya no es relevante para
        el aviso (el conteo es informativo, no transaccional).
        """
        if not self.current_project or self.current_project not in self.projects:
            return 0
        # Capturamos por si el usuario acaba de escribir algo y aún no se
        # ha volcado al modelo. Coste asumible: solo se llama al cambiar
        # de modo, no en bucle.
        self._capture_table_into_samples()
        n = 0
        for sample in self.projects[self.current_project]["samples"]:
            for row_data in sample.get("rows", []):
                cells = row_data.get("cells", {})
                if any(cells.get(c, "").strip() for c in UPB_AGE_COLS_TO_HIDE):
                    n += 1
        return n

    def _on_th_mode_changed(self):
        """
        Sincroniza UI cuando cambia el modo de ingreso de Th.
        - Sub-bloque Calc/Manual: visible solo en modo RATIO.
        - Checkbox Th del grid: visible solo en modo SEPARATE.

        El cambio NO toca columnas de Tabla 1. El usuario debe pulsar
        Apply Variables para materializar la nueva estructura.
        """
        if not hasattr(self, "th_mode_radio_group"):
            return
        mode = self.th_mode_radio_group.checkedId()
        is_ratio = (mode == TH_MODE_RATIO)

        self.th_ratio_submode_widget.setVisible(is_ratio)

        th_cb = self.trace_checkboxes.get("Th")
        if th_cb is not None:
            th_cb.setVisible(not is_ratio)
            if is_ratio:
                # Al pasar a RATIO, desmarcar Th del grid para no dejarlo en
                # estado "marcado pero invisible" — que confundiría a
                # apply_variables si el modo se interpretara mal.
                th_cb.blockSignals(True)
                th_cb.setChecked(False)
                th_cb.blockSignals(False)

    def build_ree_section(self):
        container = QWidget()
        container.setStyleSheet("background-color: transparent;")
        layout = QVBoxLayout(container)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)

        self.ree_check = QCheckBox("REE")
        self.ree_check.toggled.connect(self.on_ree_toggled)
        layout.addWidget(self.ree_check)

        self.ree_options = QWidget()
        self.ree_options.setVisible(False)
        self.ree_options.setStyleSheet("background-color: transparent;")
        ree_opts_layout = QVBoxLayout(self.ree_options)
        ree_opts_layout.setContentsMargins(18, 2, 0, 2)
        ree_opts_layout.setSpacing(3)

        ree_hint = QLabel("Classify as:")
        ree_hint.setStyleSheet("color: #6a8aaa; font-size: 11px; background: transparent;")
        ree_opts_layout.addWidget(ree_hint)

        # IDs de modo:
        #   0 = All REE together (no separation)
        #   1 = LREE / HREE (Eu separate, not summed)
        #   2 = LREE / MREE / HREE
        self.ree_radio_group = QButtonGroup(self)
        rb_all  = QRadioButton("All REE together (no separation)")
        rb_lh   = QRadioButton("LREE / HREE (Eu kept separate)")
        rb_lmh  = QRadioButton("LREE / MREE / HREE (Eu within MREE)")

        rb_lh.setChecked(True)   # modo recomendado por defecto
        for rb in (rb_all, rb_lh, rb_lmh):
            rb.setStyleSheet("QRadioButton { font-size: 12px; }")
        self.ree_radio_group.addButton(rb_all, 0)
        self.ree_radio_group.addButton(rb_lh,  1)
        self.ree_radio_group.addButton(rb_lmh, 2)
        ree_opts_layout.addWidget(rb_all)
        ree_opts_layout.addWidget(rb_lh)
        ree_opts_layout.addWidget(rb_lmh)

        layout.addWidget(self.ree_options)
        return container

